      function dashKpiNavigate(kind) {
        const { fromIso, toIso } = dashGetCurrentMonthRange();
        state.rpDashPreset = null;
        fpState.status = [];
        fpState.stage = [];
        fpState.vtypes = [];
        fpState.employees = [];
        fpState.regions = [];
        fpState.branches = [];
        fpState.supervisors = [];
        fpState.observers = [];

        if (kind === 'approved') fpState.status = ['approved'];
        else if (kind === 'pending') fpState.status = ['pending'];
        else if (kind === 'overdue') fpState.status = ['auto'];

        const searchInput = document.getElementById('rp-search');
        if (searchInput) searchInput.value = '';
        dashApplyReportsMonthFilter(fromIso, toIso);

        populateFpSelects();
        dashSyncFpChipsFromState();
        updateActiveFiltersTags();

        dashGoTab('reports');
        filterReports();
        showToast(DASH_KPI_TOAST[kind] || '╪╣╪▒╪╢ ╪º┘ä╪¬┘é╪º╪▒┘è╪▒', 'info');
      }

      function dashKpiKey(ev, kind) {
        if (ev.key === 'Enter' || ev.key === ' ') {
          ev.preventDefault();
          dashKpiNavigate(kind);
        }
      }

      function dashFunnelNavigate(stateKey) {
        const { fromIso, toIso } = dashGetCurrentMonthRange();
        state.rpDashPreset = null;
        fpState.status = [];
        fpState.stage = [stateKey];
        fpState.vtypes = [];
        fpState.employees = [];
        fpState.regions = [];
        fpState.branches = [];
        fpState.supervisors = [];
        fpState.observers = [];

        const searchInput = document.getElementById('rp-search');
        if (searchInput) searchInput.value = '';
        dashApplyReportsMonthFilter(fromIso, toIso);
        populateFpSelects();
        dashSyncFpChipsFromState();
        updateActiveFiltersTags();
        dashGoTab('reports');
        filterReports();
      }

