      function syncTopbarHeightVar() {
        const bar = document.querySelector('.topbar.unified-banner');
        const sb = document.getElementById('sidebar');
        if (!bar) return;
        const h = Math.ceil(bar.getBoundingClientRect().height);
        if (h > 0) {
          const px = h + 'px';
          document.documentElement.style.setProperty('--unified-topbar-h', px);
          if (sb) sb.style.setProperty('--sb-top', px);
        }
      }

      function syncSafeAreaInsets() {
        const probe = document.createElement('div');
        probe.style.cssText = 'position:fixed;top:0;left:0;padding:env(safe-area-inset-top) env(safe-area-inset-right) env(safe-area-inset-bottom) env(safe-area-inset-left);visibility:hidden;pointer-events:none';
        document.body.appendChild(probe);
        const s = getComputedStyle(probe);
        const top = parseFloat(s.paddingTop) || 0;
        const bottom = parseFloat(s.paddingBottom) || 0;
        probe.remove();
        if (top > 0) document.documentElement.style.setProperty('--mr-safe-top', top + 'px');
        if (bottom > 0) document.documentElement.style.setProperty('--mr-safe-bottom', bottom + 'px');
        syncTopbarHeightVar();
      }

