      async function fetchToBlobUrlWithProgress(url, mimeType, onStatus, label) {
        const res = await fetch(url);
        if (!res.ok) throw new Error('╪¬╪╣╪░┘æ╪▒ ╪¬╪¡┘à┘è┘ä ' + (label || url) + ' (' + res.status + ')');
        const total = parseInt(res.headers.get('Content-Length') || '0', 10);
        if (!res.body || !total) {
          onStatus?.('╪¬╪¡┘à┘è┘ä ' + (label || '┘à┘ä┘ü') + 'ΓÇª');
          return URL.createObjectURL(new Blob([await res.arrayBuffer()], { type: mimeType }));
        }
        const reader = res.body.getReader();
        const chunks = [];
        let received = 0;
        while (true) {
          const { done, value } = await reader.read();
          if (done) break;
          chunks.push(value);
          received += value.length;
          const pct = Math.min(99, Math.round((received / total) * 100));
          onStatus?.('╪¬╪¡┘à┘è┘ä ' + (label || '┘à┘ä┘ü') + 'ΓÇª ' + pct + '%');
        }
        const blob = new Blob(chunks, { type: mimeType });
        return URL.createObjectURL(blob);
      }

      async function probeAssetUrl(url) {
        try {
          let res = await fetch(url, { method: 'HEAD', cache: 'no-store', mode: 'cors' });
          if (res.ok) return true;
          if (res.status === 405) {
            res = await fetch(url, { method: 'GET', cache: 'no-store', mode: 'cors', headers: { Range: 'bytes=0-0' } });
            return res.ok;
          }
          return false;
        } catch (_) {
          try {
            const res = await fetch(url, { method: 'GET', cache: 'no-store', mode: 'cors', headers: { Range: 'bytes=0-0' } });
            return res.ok;
          } catch (__) {
            return false;
          }
        }
      }

