      // ╪¬╪¡┘à┘è┘ä ╪╡┘ê╪▒ ╪º┘ä┘à╪▒┘ü┘é╪º╪¬ ╪╣┘å╪» ╪º┘é╪¬╪▒╪º╪¿┘ç╪º ┘à┘å ╪º┘ä╪┤╪º╪┤╪⌐ ┘ü┘é╪╖ (Lazy + ╪¡╪» ╪¬╪▓╪º┘à┘å)
      let _cfThumbObserver = null;
      let _cfThumbActive = 0;
      const _cfThumbQueue = [];
      const CF_THUMB_MAX_CONCURRENT = 3;

      function pumpCfThumbQueue() {
        while (_cfThumbActive < CF_THUMB_MAX_CONCURRENT && _cfThumbQueue.length) {
          const img = _cfThumbQueue.shift();
          if (!img || !img.isConnected) continue;
          if (img.dataset.cfThumbDone === '1' || img.dataset.loading === 'true') continue;
          void loadOneCloudflareThumb(img);
        }
      }

      function queueCfThumbLoad(img) {
        if (!img || img.dataset.cfThumbDone === '1' || img.dataset.loading === 'true') return;
        if (_cfThumbQueue.includes(img)) return;
        _cfThumbQueue.push(img);
        pumpCfThumbQueue();
      }

      function attLoadCtx() {
        return state._attComplaintCtx || state.editingTicket || null;
      }

      async function loadOneCloudflareThumb(img) {
        const fid = img.dataset.cfId;
        if (!fid) return;
        img.dataset.loading = 'true';
        _cfThumbActive++;
        try {
          const resolved = await loadCloudflareFile(fid, attLoadCtx());
          if (!img.isConnected) return;
          const ck = cfCacheKey(fid, attLoadCtx());
          img.onload = () => {
            img.dataset.cfThumbDone = '1';
            img.style.opacity = '1';
          };
          img.onerror = () => {
            if (img.dataset.cfRetry === '1') {
              delete _cloudflareCache[ck];
              delete img.dataset.cfThumbDone;
              img.alt = '╪«╪╖╪ú ┘ü┘è ╪º┘ä╪¬╪¡┘à┘è┘ä';
              img.style.opacity = '0.3';
              return;
            }
            img.dataset.cfRetry = '1';
            const directFb = typeof readVideoDirectR2Url === 'function'
              ? readVideoDirectR2Url(ck)
              : '';
            if (directFb && img.src !== directFb && !isR2StreamPlayUrl(directFb)) {
              img.referrerPolicy = 'no-referrer';
              img.src = directFb;
              return;
            }
            delete _cloudflareCache[ck];
            delete img.dataset.cfThumbDone;
            img.alt = '╪«╪╖╪ú ┘ü┘è ╪º┘ä╪¬╪¡┘à┘è┘ä';
            img.style.opacity = '0.3';
          };
          img.referrerPolicy = 'no-referrer';
          img.src = resolved;
        } catch (e) {
          const ck = cfCacheKey(fid, attLoadCtx());
          delete _cloudflareCache[ck];
          if (img.isConnected) {
            img.alt = '╪«╪╖╪ú ┘ü┘è ╪º┘ä╪¬╪¡┘à┘è┘ä';
            img.style.opacity = '0.3';
          }
        } finally {
          delete img.dataset.loading;
          _cfThumbActive = Math.max(0, _cfThumbActive - 1);
          pumpCfThumbQueue();
        }
      }

      function ensureCfThumbObserver() {
        if (typeof IntersectionObserver === 'undefined') return null;
        if (_cfThumbObserver) return _cfThumbObserver;
        _cfThumbObserver = new IntersectionObserver((entries) => {
          for (const entry of entries) {
            if (!entry.isIntersecting) continue;
            const img = entry.target;
            try { _cfThumbObserver.unobserve(img); } catch (_) { /* */ }
            queueCfThumbLoad(img);
          }
        }, { root: null, rootMargin: '160px 0px', threshold: 0.01 });
        return _cfThumbObserver;
      }

      function loadAllCloudflareImages(opts = {}) {
        const root = opts.root && opts.root.querySelectorAll
          ? opts.root
          : document;
        const images = root.querySelectorAll('img[data-cf-id]');
        if (!images.length) return;
        if (isMirsadDebugLog()) console.log(`[CloudflareProxy] Lazy thumbs: ${images.length}`);
        const force = !!opts.force;
        const obs = force ? null : ensureCfThumbObserver();
        images.forEach((img) => {
          if (img.dataset.cfThumbDone === '1') return;
          if (!obs || force) {
            queueCfThumbLoad(img);
            return;
          }
          if (img.dataset.cfObserved === '1') return;
          img.dataset.cfObserved = '1';
          obs.observe(img);
        });
      }

      async function handleFiles(event, scope) {
        const files = Array.from(event.target.files || []);
        if (!files.length) return;

        if (!state.uploadedFiles[scope]) state.uploadedFiles[scope] = [];

        const areaId = scope === 'nt' ? 'ntFileArea'
          : scope === 'cp' ? 'cpFileArea'
            : scope === 'cpr' ? 'cprFileArea'
              : 'respFileArea';
        const area = document.getElementById(areaId);
        if (!area) {
          showToast('╪¬╪╣╪░┘æ╪▒ ╪º┘ä╪╣╪½┘ê╪▒ ╪╣┘ä┘ë ┘à┘å╪╖┘é╪⌐ ╪º┘ä┘à╪▒┘ü┘é╪º╪¬', 'error');
          event.target.value = '';
          return;
        }

        for (let fileIndex = 0; fileIndex < files.length; fileIndex++) {
          const file = files[fileIndex];
          if (file.size > 500 * 1024 * 1024) {
            showToast(`╪º┘ä┘à┘ä┘ü "${file.name}" ┘â╪¿┘è╪▒ ╪¼╪»╪º┘ï (╪ú┘â╪¿╪▒ ┘à┘å 500MB). ┘è╪▒╪¼┘ë ╪╢╪║╪╖┘ç ╪ú┘ê ╪▒┘ü╪╣ ┘à┘ä┘ü ╪ú╪╡╪║╪▒.`, 'error');
            continue;
          }

          const item = document.createElement('div');
          item.className = 'file-item';

          try {
            const isImg = file.type.startsWith('image/');
            const isVid = file.type.startsWith('video/')
              || /\.(mp4|mov|webm|avi|mkv|m4v|mpeg|mpg|ts|m2ts)$/i.test(file.name);
            let base64Data = null;
            let finalType = file.type;
            let uploadFile = file;

            item.innerHTML = `
            <div class="file-item-content">
              <i class="fas fa-file-alt" style="color:var(--blue)"></i>
              <span style="flex:1; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;" title="${Sec.escapeHTML(file.name)}">${Sec.escapeHTML(file.name)}</span>
              <span class="file-item-status" style="font-size:11px; color:var(--text3);">╪¼╪º╪▒┘è ╪º┘ä╪¬╪¡╪╢┘è╪▒ΓÇª</span>
              <button disabled style="opacity:.5">╪¡╪░┘ü ╪º┘ä┘à╪▒┘ü┘é <i class="fas fa-times"></i></button>
            </div>`;
            area.appendChild(item);
            const statusEl = item.querySelector('.file-item-status');

            let vCodecHint = null;
            let imageCompressed = false;
            if (isImg) {
              if (statusEl) statusEl.textContent = '╪╢╪║╪╖ ╪º┘ä╪╡┘ê╪▒╪⌐ΓÇª';
              const compressResult = await compressImageFile(file);
              base64Data = null;
              finalType = compressResult.type || 'image/jpeg';
              imageCompressed = !!compressResult.isCompressed;
              if (compressResult.isCompressed && compressResult.blob) {
                const outName = renameAttachmentWithExt(file.name, compressResult.ext || 'jpg');
                uploadFile = new File([compressResult.blob], outName, { type: finalType });
                const savedMb = (file.size - uploadFile.size) / 1048576;
                if (savedMb >= 1) {
                  showToast(`╪¬┘à ╪╢╪║╪╖ ╪º┘ä╪╡┘ê╪▒╪⌐ ┘ê┘ê┘ü┘æ╪▒┘å╪º ~${savedMb.toFixed(1)}MB.`, 'info');
                }
              } else if (compressResult.blob instanceof Blob) {
                uploadFile = compressResult.blob instanceof File
                  ? compressResult.blob
                  : new File([compressResult.blob], file.name, { type: finalType });
              }
            } else if (isVid) {
              vCodecHint = await sniffMp4VideoCodec(file);
              const gate = explainVideoTranscodeGate(file, file.name, vCodecHint);
              if (gate) {
                showToast(gate, 'error');
                item.remove();
                continue;
              }
              if (shouldPrepTranscodeVideo(file, file.name, vCodecHint)) {
                const mb = Math.round(file.size / 1048576);
                showToast(
                  mb >= 40
                    ? `╪│┘è╪¬┘à ╪¬╪¡┘ê┘è┘ä ╪º┘ä┘ü┘è╪»┘è┘ê (${mb}MB) ╪Ñ┘ä┘ë H.264 ╪¬┘ä┘é╪º╪ª┘è╪º┘ï ΓÇö ┘é╪» ┘è╪│╪¬╪║╪▒┘é ╪╣╪»╪⌐ ╪»┘é╪º╪ª┘é╪î ┘ä╪º ╪¬╪║┘ä┘é ╪º┘ä╪╡┘ü╪¡╪⌐.`
                    : '╪│┘è╪¬┘à ╪¬╪¡┘ê┘è┘ä ╪º┘ä┘ü┘è╪»┘è┘ê ╪Ñ┘ä┘ë H.264 ╪¬┘ä┘é╪º╪ª┘è╪º┘ï ╪ú╪½┘å╪º╪í ╪º┘ä╪¬╪¡╪╢┘è╪▒.',
                  'info',
                );
              }
            }

            const fileId = (typeof crypto !== 'undefined' && crypto.randomUUID)
              ? crypto.randomUUID()
              : ('f_' + Date.now() + '_' + Math.random().toString(36).slice(2, 9));

            state.uploadedFiles[scope].push({
              _fileId: fileId,
              name: uploadFile.name,
              type: finalType,
              base64: base64Data,
              rawFile: uploadFile,
              blobUrl: URL.createObjectURL(uploadFile),
              prepStatus: 'preparing',
              prepStatusMsg: '',
              prepError: null,
              tempKey: null,
              transcoded: false,
              imageCompressed,
              codecHint: vCodecHint,
            });
            const idx = state.uploadedFiles[scope].length - 1;
            const entry = state.uploadedFiles[scope][idx];

            item.dataset.attFileId = fileId;
            item.innerHTML = `
            <div class="file-item-content">
              <i class="fas fa-file-alt" style="color:var(--blue)"></i>
              <span style="flex:1; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;" title="${Sec.escapeHTML(uploadFile.name)}">${Sec.escapeHTML(uploadFile.name)}</span>
              <span class="file-item-status" style="font-size:11px; color:var(--text3);">${Sec.escapeHTML(attachmentPrepStatusLabel(entry))}</span>
              <button onclick="removeFileById('${scope}', '${fileId}', this)">╪¡╪░┘ü ╪º┘ä┘à╪▒┘ü┘é <i class="fas fa-times"></i></button>
            </div>`;

            void runAttachmentBackgroundPrep(scope, entry);
            syncAttachmentSubmitButtons(scope);
          } catch (err) {
            item.innerHTML = `<i class="fas fa-times" style="color:var(--red)"></i><span>${Sec.escapeHTML(file.name)} - ┘ü╪┤┘ä ╪º┘ä╪¬╪¡╪╢┘è╪▒</span>`;
            showToast('┘ü╪┤┘ä ┘à╪╣╪º┘ä╪¼╪⌐ ╪º┘ä┘à┘ä┘ü: ' + err.message, 'error');
          }
        }
        event.target.value = '';
      }

      function removeFileById(scope, fileId, btn) {
        const list = state.uploadedFiles[scope] || [];
        const idx = list.findIndex((f) => f._fileId === fileId);
        if (idx === -1) return;
        const file = list[idx];
        cancelAttachmentPrep(file);
        void deleteAttachmentTempKey(file).finally(() => {
          list.splice(idx, 1);
          if (btn) btn.closest('.file-item')?.remove();
          syncAttachmentSubmitButtons(scope);
        });
      }

      function removeFile(scope, idx, btn) {
        const file = state.uploadedFiles[scope]?.[idx];
        if (file?._fileId) return removeFileById(scope, file._fileId, btn);
        state.uploadedFiles[scope].splice(idx, 1);
        btn.closest('.file-item').remove();
      }

      // ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ
      // 20. WORKFLOW (┘à╪╣╪º┘ä╪¼╪⌐ ╪º┘ä╪¬╪░╪º┘â╪▒)
      // ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ

