          getOrCreateTicketMobBody(list).innerHTML = mobBodyHtml;
          const mobBodyScroll = list.querySelector('.wf-mob-tickets-body');
          if (mobBodyScroll) delete mobBodyScroll.dataset.rpColSig;
          const scrollTab = isReportsList ? 'reports' : 'workflow';
