      function rdCmpTheadHTML(view) {
        if (view === 'branches') {
          return `
            <div class="rd-cmp-thead rd-cmp-thead--branch" role="row">
              <span>╪º┘ä┘ü╪▒╪╣</span><span>╪º┘ä┘à┘ê╪╕┘ü┘ê┘å</span><span>┘à╪╣╪»┘ä ╪º┘ä╪º┘ä╪¬╪▓╪º┘à</span>
            </div>`;
        }
        if (view === 'employees') {
          return `
            <div class="rd-cmp-thead rd-cmp-thead--emp" role="row">
              <span>╪º┘ä┘à┘ê╪╕┘ü</span><span>╪º┘ä╪»┘ê╪▒</span><span>┘à╪╣╪»┘ä ╪º┘ä╪º┘ä╪¬╪▓╪º┘à</span>
            </div>`;
        }
        return `
          <div class="rd-cmp-thead rd-cmp-thead--region" role="row">
            <span>╪º┘ä┘à┘å╪╖┘é╪⌐</span><span>╪º┘ä┘à╪»┘è╪▒</span><span>╪º┘ä┘ü╪▒┘ê╪╣</span><span>╪º┘ä┘à┘ê╪╕┘ü┘ê┘å</span><span>┘à╪╣╪»┘ä ╪º┘ä╪º┘ä╪¬╪▓╪º┘à</span>
          </div>`;
      }

      function cmpNeoExtremesBarHTML(extremes, view) {
        if (!extremes) return '';
        if (typeof isComplianceAtharUi === 'function' && isComplianceAtharUi()) {
          return rdCmpHiLoHTML(extremes, view);
        }
        const labels = view === 'branches'
          ? { top: '╪ú╪╣┘ä┘ë ┘ü╪▒╪╣', bottom: '╪ú╪»┘å┘ë ┘ü╪▒╪╣' }
          : view === 'employees'
            ? { top: '╪ú╪╣┘ä┘ë ╪¬┘é┘è┘è┘à', bottom: '╪ú┘é┘ä ╪¬┘é┘è┘è┘à' }
            : { top: '╪ú╪╣┘ä┘ë ┘à┘å╪╖┘é╪⌐', bottom: '╪ú╪»┘å┘ë ┘à┘å╪╖┘é╪⌐' };
        const icons = { top: 'fa-trophy', bottom: 'fa-arrow-trend-down' };
        const onClick = view === 'branches'
          ? (id) => `cmpOpenBranchCompliance('${id}')`
          : view === 'employees'
            ? (id) => `openCmpItemDetail('employee','${id}')`
            : (id) => `cmpOpenRegionCompliance('${id}')`;
        const pill = (kind, item) => {
          const score = Math.round(Number(item.score) * 10) / 10;
          const scoreStr = score.toFixed(1) + '%';
          const tone = cmpScoreRateColor(item.score);
          const subMeta = view === 'regions' ? cmpRegionSupervisorMeta(item.id) : null;
          const subText = subMeta ? subMeta.text : cmpNeoExtremeSub(item, view);
          const subCls = subMeta?.missing ? ' cmp-neo-extreme__sub--no-sup' : '';
          return `
            <button type="button" class="cmp-neo-extreme cmp-neo-extreme--${kind}" onclick="${onClick(item.id)}">
              <span class="cmp-neo-extreme__icon" aria-hidden="true"><i class="fas ${Sec.escapeHTML(icons[kind])}"></i></span>
              <span class="cmp-neo-extreme__body">
                <span class="cmp-neo-extreme__lbl">${labels[kind]}</span>
                <span class="cmp-neo-extreme__name" title="${Sec.escapeHTML(item.name)}">${Sec.escapeHTML(item.name)}</span>
                <span class="cmp-neo-extreme__sub${subCls}">${Sec.escapeHTML(subText)}</span>
              </span>
              <span class="cmp-neo-extreme__score" style="color:${tone}">${scoreStr}</span>
            </button>`;
        };
        return `<div class="cmp-neo-extremes" role="group" aria-label="╪ú╪╣┘ä┘ë ┘ê╪ú╪»┘å┘ë ╪ú╪»╪º╪í">${pill('top', extremes.top)}${pill('bottom', extremes.bottom)}</div>`;
      }

      function cmpNeoBoardCardHTML(card, view, opts = {}) {
        const rawScore = Number(card.score);
        const isNeg = rawScore < 0;
        const rateNum = Math.round(rawScore * 10) / 10;
        const rateStr = rateNum.toFixed(1) + '%';
        const animKey = `${view}-${card.id || card.name}-score`;
        const ring = cmpNeoRingSVG(rawScore, { animKey });
        const rateTone = cmpScoreRateColor(rawScore);
        const cardLow = isNeg || rawScore < 75;
        const cardId = String(card.id || '').replace(/'/g, "\\'").replace(/"/g, '&quot;');
        const clickAttr = card.onClick ? `onclick="${Sec.escapeHTML(card.onClick)}"` : 'data-static="true"';
        const statA = view === 'regions' ? '╪º┘ä┘ü╪▒┘ê╪╣' : (view === 'branches' ? '┘à┘å╪╢╪¿╪╖┘ê┘å' : '╪º┘ä┘à╪«╪º┘ä┘ü╪º╪¬');
        const statB = view === 'employees' ? '╪º┘ä┘å┘é╪º╪╖' : '╪º┘ä┘à┘ê╪╕┘ü┘ê┘å';
        const rankCls = card.rank === 'top' ? ' cmp-neo-card--top' : (card.rank === 'bottom' ? ' cmp-neo-card--bottom' : '');

        if (typeof isComplianceAtharUi === 'function' && isComplianceAtharUi()) {
          if (view === 'regions') return rdCmpRegionCardHTML(card);
          if (view === 'branches') return rdCmpBranchCardHTML(card);
          return rdCmpRegionCardHTML(card);
        }

        const rankTitle = view === 'branches'
          ? (card.rank === 'top' ? '╪ú╪╣┘ä┘ë ┘ü╪▒╪╣' : '╪ú╪»┘å┘ë ┘ü╪▒╪╣')
          : (card.rank === 'top' ? '╪ú╪╣┘ä┘ë ┘à┘å╪╖┘é╪⌐' : '╪ú╪»┘å┘ë ┘à┘å╪╖┘é╪⌐');
        const rankBadge = card.rank === 'top'
          ? `<span class="cmp-neo-rank cmp-neo-rank--top" title="${Sec.escapeHTML(rankTitle)}" aria-label="${Sec.escapeHTML(rankTitle)}"><i class="fas fa-trophy" aria-hidden="true"></i></span>`
          : (card.rank === 'bottom'
            ? `<span class="cmp-neo-rank cmp-neo-rank--bottom" title="${Sec.escapeHTML(rankTitle)}" aria-label="${Sec.escapeHTML(rankTitle)}"><i class="fas fa-arrow-trend-down" aria-hidden="true"></i></span>`
            : '');
        return `
              <article class="cmp-neo-card${cardLow ? ' cmp-neo-card--low' : ''}${rankCls}" ${clickAttr} role="${card.onClick ? 'button' : 'presentation'}" tabindex="${card.onClick ? '0' : '-1'}">
                ${rankBadge}
                <div class="cmp-neo-head">
                  <h4><span class="cmp-neo-head-text" title="${Sec.escapeHTML(card.name)}">${Sec.escapeHTML(card.name)}</span></h4>
                  <span>${card.subHtml != null ? card.subHtml : Sec.escapeHTML(card.sub || 'ΓÇö')}</span>
                </div>
                <div class="cmp-neo-body">
                  <div class="cmp-neo-metrics">
                    <div class="cmp-neo-stat"><span class="cmp-neo-stat__lbl">${Sec.escapeHTML(statA)}</span><strong class="cmp-neo-stat__val">${card.branches}</strong></div>
                    <div class="cmp-neo-stat"><span class="cmp-neo-stat__lbl">${Sec.escapeHTML(statB)}</span><strong class="cmp-neo-stat__val">${card.employees}</strong></div>
                    <div class="cmp-neo-stat"><span class="cmp-neo-stat__lbl">┘à╪╣╪»┘ä ╪º┘ä╪º┘ä╪¬╪▓╪º┘à</span><strong class="cmp-neo-stat__val cmp-neo-rate-val" data-cmp-anim-key="${Sec.escapeHTML(animKey + '-rate')}" data-cmp-target="${rawScore}" style="color:${rateTone}">${rateStr}</strong></div>
                  </div>
                  ${ring.html}
                </div>
              </article>`;
      }

      function cmpNeoCardHTML(card, view, opts = {}) {
        const pct = Math.max(0, Math.min(100, Math.round(card.score)));
        const tone = cmpNeoRingTone(card.score);
        const trendCls = card.trend.cls === 'up' ? 'mk-badge--green' : (card.trend.cls === 'down' ? 'mk-badge--red' : 'mk-badge--gray');
        const clickAttr = opts.expandable
          ? 'data-expandable="true"'
          : (card.onClick ? `onclick="${Sec.escapeHTML(card.onClick)}"` : 'data-static="true"');
        const radius = 26;
        const circ = (2 * Math.PI * radius).toFixed(2);
        const offset = (circ * (1 - pct / 100)).toFixed(2);
        const statALabel = view === 'regions' ? '╪º┘ä┘ü╪▒┘ê╪╣' : (view === 'branches' ? '┘à┘å╪╢╪¿╪╖┘ê┘å' : '╪º┘ä┘à╪«╪º┘ä┘ü╪º╪¬');
        const statBLabel = view === 'employees' ? '╪º┘ä┘å┘é╪º╪╖' : '╪º┘ä┘à┘ê╪╕┘ü┘ê┘å';
        const respPct = view === 'employees' && card.responseRate != null ? Math.round(card.responseRate) : null;
        const isEmpDualRings = view === 'employees' && card.responseRate != null;
        const entityIcon = Sec.escapeHTML(opts.icon || card.icon || (view === 'regions' ? 'fa-map-marker-alt' : (view === 'branches' ? 'fa-store' : 'fa-user')));
        const featured = opts.featured ? ' mk-cmp-card--featured' : '';
        const animKey = `${view}-${card.id}-score`;
        const ringsBlock = isEmpDualRings
          ? `<div class="mk-cmp-card__rings">
              ${cmpMkDonutHTML(card.score, '╪º┘ä╪º┘à╪¬╪½╪º┘ä', { small: true, animKey: 'emp-' + card.id + '-score' })}
              ${cmpMkDonutHTML(card.responseRate, '╪º┘ä╪º╪│╪¬╪¼╪º╪¿╪⌐', { small: true, animKey: 'emp-' + card.id + '-response' })}
            </div>`
          : `<div class="mk-donut" data-cmp-anim-key="${Sec.escapeHTML(animKey)}" data-cmp-target="${pct}" aria-hidden="true">
              <svg viewBox="0 0 64 64">
                <circle class="mk-donut__bg" cx="32" cy="32" r="${radius}" fill="none" stroke-width="6"/>
                <circle class="mk-donut__fg" cx="32" cy="32" r="${radius}" fill="none" stroke-width="6"
                        stroke="${tone.ring}" stroke-dasharray="${circ}" stroke-dashoffset="${offset}"/>
              </svg>
              <span class="mk-donut__val">${pct}</span>
            </div>`;
        return `
              <article class="mk-cmp-card${featured}" ${clickAttr}>
                <div class="mk-cmp-card__hd">
                  <div class="mk-cmp-card__title">
                    <span class="mk-cmp-card__ico"><i class="fas ${entityIcon}"></i></span>
                    <div>
                      <h3>${Sec.escapeHTML(card.name)}</h3>
                      <span class="mk-cmp-card__city">${Sec.escapeHTML(card.sub || 'ΓÇö')}</span>
                    </div>
                  </div>
                  <span class="mk-badge ${trendCls}" style="cursor:help" title="${Sec.escapeHTML(card.trend.hint || '')}" aria-label="${Sec.escapeHTML(card.trend.hint || '')}"><i class="fas ${card.trend.icon}"></i> ${Sec.escapeHTML(card.trend.pct)}</span>
                </div>
                <div class="mk-cmp-card__bd">
                  <div class="mk-cmp-card__stats">
                    <div class="mk-cmp-card__stat">
                      <span class="mk-cmp-card__stat-lbl">${Sec.escapeHTML(statALabel)}</span>
                      <span class="mk-cmp-card__stat-val">${card.branches}</span>
                    </div>
                    <div class="mk-cmp-card__stat">
                      <span class="mk-cmp-card__stat-lbl">${Sec.escapeHTML(statBLabel)}</span>
                      <span class="mk-cmp-card__stat-val">${card.employees}</span>
                    </div>
                    ${isEmpDualRings ? '' : `
                    <div class="mk-cmp-card__stat">
                      <span class="mk-cmp-card__stat-lbl">┘à╪╣╪»┘ä ╪º┘ä╪º┘à╪¬╪½╪º┘ä</span>
                      <span class="mk-cmp-card__stat-val" style="color:${tone.ring}">${pct}%</span>
                    </div>`}
                  </div>
                  ${ringsBlock}
                </div>
              </article>`;
      }

      function buildCmpBranchExpandableShell(branchCardHTML, employeesHTML, opts = {}) {
        const empCount = opts.empCount ?? 0;
        const openCls = opts.defaultOpen ? ' is-open' : '';
        const expanded = opts.defaultOpen ? 'true' : 'false';
        const emptyInner = employeesHTML || '<div class="mk-empty"><i class="fas fa-user-slash"></i><p>┘ä╪º ┘è┘ê╪¼╪» ┘à┘ê╪╕┘ü┘ê┘å ┘ü┘è ┘ç╪░╪º ╪º┘ä┘ü╪▒╪╣</p></div>';
        return `
          <div class="mk-cmp-branch-shell${openCls}">
            <div class="mk-cmp-branch-shell__trigger" role="button" tabindex="0" aria-expanded="${expanded}"
                 onclick="toggleCmpBranchEmployees(this)"
                 onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();toggleCmpBranchEmployees(this);}">
              ${branchCardHTML}
              <div class="mk-cmp-branch-shell__toggle">
                <span class="mk-cmp-branch-shell__toggle-lbl"><i class="fas fa-users"></i> ╪º┘à╪¬╪½╪º┘ä ╪º┘ä┘à┘ê╪╕┘ü┘è┘å (${empCount})</span>
                <i class="fas fa-chevron-down mk-cmp-branch-shell__chev" aria-hidden="true"></i>
              </div>
            </div>
            <div class="mk-cmp-branch-shell__body">
              <div class="mk-cmp-grid mk-cmp-grid--nested">${emptyInner}</div>
            </div>
          </div>`;
      }

      function buildCmpBranchCardForId(branchId, violations) {
        const branchObj = (state.branches || []).find(b => b.id === branchId);
        if (!branchObj) return '';
        const regionObj = (state.regions || []).find(r => r.id === branchObj.region_id);
        const branchStat = calcBranchSafety(branchId, violations);
        const branchViols = violations.filter(v => v.branch_id === branchId);
        return cmpNeoCardHTML({
          name: branchObj.name,
          sub: branchObj.city || regionObj?.name || 'ΓÇö',
          branches: branchStat.safeEmps,
          employees: branchStat.totalEmps,
          score: branchStat.score,
          trend: cmpNeoTrendMeta(branchViols),
          onClick: ''
        }, 'branches', { icon: 'fa-store', featured: true, expandable: true });
      }

      function toggleCmpBranchEmployees(triggerEl) {
        const shell = triggerEl?.closest?.('.mk-cmp-branch-shell');
        if (!shell) return;
        shell.classList.toggle('is-open');
        const open = shell.classList.contains('is-open');
        triggerEl.setAttribute('aria-expanded', open ? 'true' : 'false');
      }

      function cmpBackToRegions() {
        if (state.currentUser?.role === 'branch_manager') {
          const bid = state.currentUser.branch_id;
          const br = bid && state.branches.find(b => b.id === bid);
          state._cmpDrill = { view: 'branches', regionId: br?.region_id || '', branchId: '' };
          state._cmpActiveTab = 'branches';
          renderCompliance();
          return;
        }
        state._cmpDrill = { view: 'regions', regionId: '', branchId: '' };
        state._cmpActiveTab = 'regions';
        cmpfState.scope = 'regions';
        cmpfState.region = '';
        cmpfState.branch = '';
        cmpfState.employee = '';
        renderCompliance();
      }

      function cmpOpenRegionCompliance(regionId) {
        state._cmpDrill = { view: 'branches', regionId, branchId: '' };
        state._cmpActiveTab = 'branches';
        renderCompliance();
      }

      function cmpOpenBranchCompliance(branchId) {
        const b = state.branches.find(x => x.id === branchId);
        state._cmpDrill = { view: 'employees', regionId: b?.region_id || '', branchId };
        state._cmpActiveTab = 'employees';
        renderCompliance();
      }

      function cmpBackToBranches() {
        if (state.currentUser?.role === 'branch_manager') {
          const bid = state.currentUser.branch_id;
          const br = bid && state.branches.find(b => b.id === bid);
          state._cmpDrill = { view: 'branches', regionId: br?.region_id || '', branchId: '' };
          state._cmpActiveTab = 'branches';
          renderCompliance();
          return;
        }
        const d = state._cmpDrill || { regionId: '' };
        state._cmpDrill = { view: 'branches', regionId: d.regionId || '', branchId: '' };
        state._cmpActiveTab = 'branches';
        cmpfState.scope = 'branches';
        cmpfState.branch = '';
        cmpfState.employee = '';
        renderCompliance();
      }

      function renderCompliance() {
        const board = document.getElementById('cmpBoard');
        if (!board) return;

        const violations = getViolationsForScoring();
        const role = state.currentUser?.role;
        const isBranchMgr = role === 'branch_manager';
        const bmBranchId = isBranchMgr ? (state.currentUser?.branch_id || '') : '';

        if (!state._cmpDrill) state._cmpDrill = { view: 'regions', regionId: '', branchId: '' };
        let view = state._cmpDrill.view || state._cmpActiveTab || 'regions';

        if (isBranchMgr && !canSeeAllCompliance()) {
          const br = bmBranchId && state.branches.find(b => b.id === bmBranchId);
          view = 'employees';
          state._cmpDrill = { view: 'employees', regionId: br?.region_id || '', branchId: bmBranchId };
          applyCmpBranchManagerGeoScope();
        }

        state._cmpActiveTab = view;
        cmpfState.scope = view;
        if (view === 'branches' && state._cmpDrill.regionId) cmpfState.region = state._cmpDrill.regionId;
        if (view === 'employees' && state._cmpDrill.branchId) {
          cmpfState.branch = state._cmpDrill.branchId;
          if (state._cmpDrill.regionId) cmpfState.region = state._cmpDrill.regionId;
        }

        let items = buildCmpItems();
        cmpSortItems(items);

        let title = '┘à╪ñ╪┤╪▒╪º╪¬ ╪º┘ä╪º┘à╪¬╪½╪º┘ä';
        let titleContext = '';
        let subtitle = '┘å╪╕╪▒╪⌐ ╪╣╪º┘à╪⌐ ╪╣┘ä┘ë ╪ú╪»╪º╪í ┘â┘ä ╪º┘ä┘à┘å╪º╪╖┘é';
        let backNav = '';
        const rdCmp = typeof isComplianceAtharUi === 'function' && isComplianceAtharUi();

        if (view === 'branches') {
          const region = state.regions.find(r => r.id === state._cmpDrill.regionId);
          if (state._cmpDrill.regionId && region) {
            title = '╪¬┘é┘è┘è┘à ╪º┘ä┘ü╪▒┘ê╪╣';
            titleContext = cmpRegionHeadLabel(region);
            subtitle = '';
            backNav = cmpNeoBackBtnHTML('┘â┘ä ╪º┘ä┘à┘å╪º╪╖┘é', 'cmpBackToRegions()', null, { combo: true });
          } else {
            title = '┘à╪ñ╪┤╪▒╪º╪¬ ╪º┘ä╪º┘à╪¬╪½╪º┘ä';
            titleContext = '';
            subtitle = '┘å╪╕╪▒╪⌐ ╪╣╪º┘à╪⌐ ╪╣┘ä┘ë ╪ú╪»╪º╪í ┘â┘ä ╪º┘ä┘ü╪▒┘ê╪╣';
          }
        } else if (view === 'employees') {
          const branch = state.branches.find(b => b.id === state._cmpDrill.branchId);
          if (state._cmpDrill.branchId && branch && !isBranchMgr) {
            title = '╪¬┘é┘è┘è┘à ╪º┘ä┘à┘ê╪╕┘ü┘è┘å';
            titleContext = branch.name;
            subtitle = rdCmp ? '' : '┘å╪╕╪▒╪⌐ ╪╣╪º┘à╪⌐ ╪╣┘ä┘ë ╪ú╪»╪º╪í ┘â┘ä ╪º┘ä┘à┘ê╪╕┘ü┘è┘å';
            backNav = cmpNeoBackBtnHTML('┘â┘ä ╪º┘ä┘ü╪▒┘ê╪╣', 'cmpBackToBranches()', null, { combo: true });
          } else if (isBranchMgr) {
            title = '╪¬┘é┘è┘è┘à ╪º┘ä┘à┘ê╪╕┘ü┘è┘å';
            titleContext = branch?.name || 'ΓÇö';
            subtitle = '';
          } else {
            title = '┘à╪ñ╪┤╪▒╪º╪¬ ╪º┘ä╪º┘à╪¬╪½╪º┘ä';
            titleContext = '';
            subtitle = '┘å╪╕╪▒╪⌐ ╪╣╪º┘à╪⌐ ╪╣┘ä┘ë ╪ú╪»╪º╪í ┘â┘ä ╪º┘ä┘à┘ê╪╕┘ü┘è┘å';
          }
        }
        if (rdCmp && view === 'regions') {
          subtitle = '╪ú╪»╪º╪í ╪º┘ä┘à┘å╪º╪╖┘é ╪¡╪│╪¿ ┘à╪╣╪»┘ä ╪º┘ä╪º┘ä╪¬╪▓╪º┘à';
        }

        const scoreExtremes = cmpFindScoreExtremes(items);
        const topId = scoreExtremes?.top?.id || '';
        const bottomId = scoreExtremes?.bottom?.id || '';
        const extremesBarHTML = cmpNeoExtremesBarHTML(scoreExtremes, view);

        const cmpDataPending = state._dataLoading || !state._dataReady;
        let cardsHTML = '';
        if (cmpDataPending) {
          cardsHTML = '<div class="cmp-neo-empty cmp-neo-empty--loading"><i class="fas fa-spinner fa-spin" style="font-size:28px;opacity:.7" aria-hidden="true"></i><p>╪¼╪º╪▒┘è ╪¬╪¡┘à┘è┘ä ┘à╪ñ╪┤╪▒╪º╪¬ ╪º┘ä╪º┘à╪¬╪½╪º┘äΓÇª</p></div>';
        } else if (!items.length) {
          cardsHTML = '<div class="cmp-neo-empty"><i class="fas fa-folder-open" style="font-size:28px;opacity:.45"></i><p>┘ä╪º ╪¬┘ê╪¼╪» ╪¿┘è╪º┘å╪º╪¬ ┘à╪╖╪º╪¿┘é╪⌐ ┘ä┘ä┘ü┘ä╪º╪¬╪▒</p></div>';
        } else if (view === 'employees') {
          cardsHTML = items.map(item => {
            const stat = item.stat || calcEmpScore(item.id, violations);
            const resp = calcResponseRate(item.id, 'employee');
            const empViols = violations.filter(v => v.employee_id === item.id);
            const branch = state.branches.find(b => b.id === (state.users.find(u => u.id === item.id)?.branch_id));
            const isMgr = !!(branch && state.users.find(u => u.id === item.id && u.role === 'branch_manager'));
            const empCard = {
              id: item.id,
              name: item.name,
              empNumber: item.empNumber || item.extraInfo?.empNumber,
              score: stat.score,
              violationsCount: stat.violationsCount,
              violCount: stat.violationsCount,
              deducted: stat.deducted,
              pendingCount: stat.pendingCount,
              respAuto: resp.autoCount,
              respOnTime: resp.respondedCount,
              responseRate: resp.score,
              respPenalty: resp.penalty,
              respBonus: resp.bonus,
              streakBonus: stat.streakBonus,
              scoreHealed: stat.scoreHealed,
              isBm: isMgr,
              trend: cmpNeoTrendMeta(empViols),
              rank: item.id === topId ? 'top' : (item.id === bottomId ? 'bottom' : ''),
              onClick: `openCmpItemDetail('employee','${item.id}')`
            };
            return rdCmp
              ? rdCmpEmpRowHTML(empCard)
              : cmpEmpCardHTML(empCard);
          }).join('');
        } else if (view === 'branches') {
          cardsHTML = items.map(item => {
            const stat = item.stat || calcBranchSafety(item.id, violations);
            const brViols = violations.filter(v => v.branch_id === item.id);
            const region = state.regions.find(r => r.id === (state.branches.find(b => b.id === item.id)?.region_id));
            const br = state.branches.find(b => b.id === item.id);
            return cmpNeoBoardCardHTML({
              id: item.id,
              name: item.name,
              sub: br?.city || region?.name || 'ΓÇö',
              branches: stat.safeEmps,
              employees: stat.totalEmps,
              score: stat.score,
              trend: cmpNeoTrendMeta(brViols),
              rank: item.id === topId ? 'top' : (item.id === bottomId ? 'bottom' : ''),
              onClick: `cmpOpenBranchCompliance('${item.id}')`
            }, 'branches', { icon: 'fa-store' });
          }).join('');
        } else {
          cardsHTML = items.map(item => {
            const stat = item.stat || calcRegionStability(item.id, violations);
            const regBranches = state.branches.filter(b => b.region_id === item.id);
            const branchIds = regBranches.map(b => b.id);
            const regViols = violations.filter(v => branchIds.includes(v.branch_id));
            const supMeta = cmpRegionSupervisorMeta(item.id);
            return cmpNeoBoardCardHTML({
              id: item.id,
              name: item.name,
              sub: supMeta.text,
              subHtml: supMeta.html,
              branches: stat.branchesCount,
              employees: stat.totalEmps,
              score: stat.score,
              trend: cmpNeoTrendMeta(regViols),
              rank: item.id === topId ? 'top' : (item.id === bottomId ? 'bottom' : ''),
              onClick: `cmpOpenRegionCompliance('${item.id}')`
            }, 'regions', { icon: 'fa-location-dot' });
          }).join('');
        }

        const gridCls = cmpDataPending ? 'cmp-neo-pending-wrap' : (view === 'employees' ? 'mk-cmp-grid mk-cmp-grid--emp' : 'cmp-neo-grid');
        const dateLabel = cmpGetDateButtonLabel();
        const cmpSearchVal = document.getElementById('cmp-search')?.value || '';
        const cmpSearchPh = cmpSearchPlaceholder(view);
        if (!cmpDataPending) cmpSnapshotBoardAnim(board);

        if (rdCmp) {
          const isRegionsRoot = view === 'regions';
          const desk = typeof isAtharDesktopScreenUi === 'function' && isAtharDesktopScreenUi();
          const drilledRegion = state.regions.find(r => r.id === state._cmpDrill.regionId);
          const drilledBranch = state.branches.find(b => b.id === state._cmpDrill.branchId);
          let listTitle = '╪¡╪│╪¿ ╪º┘ä┘à┘å╪╖┘é╪⌐';
          let rdBack = '';
          if (view === 'branches' && drilledRegion) {
            listTitle = '┘ü╪▒┘ê╪╣ ' + drilledRegion.name;
            rdBack = `<button type="button" class="rd-cmp-back" onclick="cmpBackToRegions()"><i class="fas fa-arrow-right" aria-hidden="true"></i>┘â┘ä ╪º┘ä┘à┘å╪º╪╖┘é</button>`;
          } else if (view === 'employees' && drilledBranch && !isBranchMgr) {
            listTitle = '┘à┘ê╪╕┘ü┘ê ' + drilledBranch.name;
            rdBack = `<button type="button" class="rd-cmp-back" onclick="cmpBackToBranches()"><i class="fas fa-arrow-right" aria-hidden="true"></i>┘ü╪▒┘ê╪╣ ${Sec.escapeHTML(drilledRegion?.name || '')}</button>`;
          } else if (view === 'employees' && isBranchMgr) {
            listTitle = '┘à┘ê╪╕┘ü┘ê ' + (drilledBranch?.name || '╪º┘ä┘ü╪▒╪╣');
          } else if (view === 'branches') {
            listTitle = '╪¡╪│╪¿ ╪º┘ä┘ü╪▒╪╣';
          } else if (view === 'employees') {
            listTitle = '╪¡╪│╪¿ ╪º┘ä┘à┘ê╪╕┘ü';
          }

          let orgScore = 100;
          if (!cmpDataPending && isRegionsRoot && items.length) {
            orgScore = items.reduce((a, it) => a + Number(it.score || 0), 0) / items.length;
          } else if (!cmpDataPending && (state.regions || []).length) {
            const regs = state.regions;
            orgScore = regs.reduce((a, r) => a + calcRegionStability(r.id, violations).score, 0) / regs.length;
          }

          let metricsHTML = '';
          if (!cmpDataPending) {
            if (desk || isRegionsRoot) {
              let hiLo = extremesBarHTML;
              if (desk && !isRegionsRoot) {
                const regItems = (state.regions || []).map((r) => ({
                  id: r.id,
                  name: r.name,
                  score: calcRegionStability(r.id, violations).score,
                }));
                hiLo = rdCmpHiLoHTML(cmpFindScoreExtremes(regItems), 'regions');
              }
              metricsHTML = `${rdCmpOrgHeroHTML(orgScore)}${hiLo}`;
            }
          }

          const listTitleHTML = (desk && isRegionsRoot)
            ? ''
            : `<div class="rd-cmp-list-title">${Sec.escapeHTML(listTitle)}</div>`;
          const theadHTML = desk && !cmpDataPending && items.length ? rdCmpTheadHTML(view) : '';
          const toolbarHTML = desk ? '' : `
              <header class="rd-cmp-hd">
                <h3>┘à╪ñ╪┤╪▒╪º╪¬ ╪º┘ä╪º┘à╪¬╪½╪º┘ä</h3>
                <p class="rd-cmp-hd__eye">COMPLIANCE OVERVIEW</p>
              </header>
              <div class="rd-cmp-toolbar">
                <div class="figma-search-wrap rd-cmp-search rd-app-search">
                  <input type="text" class="figma-search-input" id="cmp-search"
                    value="${Sec.escapeHTML(cmpSearchVal)}"
                    placeholder="${Sec.escapeHTML(cmpSearchPh || '╪º╪¿╪¡╪½ ╪¿╪º╪│┘à ╪º┘ä┘à┘å╪╖┘é╪⌐ ╪ú┘ê ╪º┘ä┘à╪»┘è╪▒...')}"
                    oninput="filterCmpSearch()" autocomplete="off" enterkeyhint="search">
                  <button type="button" class="figma-search-btn" onclick="filterCmpSearch()" aria-label="╪¿╪¡╪½">
                    <i class="fas fa-magnifying-glass"></i>
                  </button>
                </div>
                ${canPickCmpScope() ? `<div class="wf-status-filter" id="cmp-filter-dd">
                  <button type="button" class="wf-status-trigger" id="cmp-filter-trigger"
                    onclick="cmpFilterToggle(event)" aria-haspopup="listbox" aria-expanded="false">
                    <span class="wf-status-trigger__label" id="cmp-filter-label">┘â┘ä ╪º┘ä┘à┘å╪º╪╖┘é</span>
                    <i class="fas fa-chevron-down wf-status-trigger__chev" aria-hidden="true"></i>
                  </button>
                  <select id="cmp-filter-scope" class="wf-status-select-native" tabindex="-1" aria-hidden="true"
                    aria-label="┘å╪╖╪º┘é ╪º┘ä╪╣╪▒╪╢" onchange="cmpFilterMobNativeChange(this)">
                    <option value="regions">┘â┘ä ╪º┘ä┘à┘å╪º╪╖┘é</option>
                    <option value="branches">┘â┘ä ╪º┘ä┘ü╪▒┘ê╪╣</option>
                    <option value="employees">┘â┘ä ╪º┘ä┘à┘ê╪╕┘ü┘è┘å</option>
                  </select>
                </div>` : ''}
                <div class="rp-date-wrap" id="cmpNeoDateWrap" hidden>
                  <button type="button" class="rp-tool-btn rp-date-btn" onclick="toggleCmpDatePicker(event)" id="cmp-date-btn">
                    <i class="fas fa-calendar"></i><span id="cmp-date-label">${Sec.escapeHTML(dateLabel)}</span>
                  </button>
                </div>
              </div>
              <p class="cmp-neo-search-meta" hidden>╪╣╪»╪» ╪º┘ä┘å╪¬╪º╪ª╪¼: <strong id="cmp-search-count">${cmpDataPending ? 'ΓÇª' : items.length}</strong></p>`;

          board.innerHTML = `
            <section class="cmp-neo-board rd-cmp-board${desk ? ' rd-cmp-board--desk' : ''}">
              ${toolbarHTML}
              ${metricsHTML}
              ${rdBack}
              ${listTitleHTML}
              <div class="rd-cmp-table${desk ? ' rd-cmp-table--desk' : ''}">
                ${theadHTML}
                <div class="rd-cmp-list ${gridCls}">${cardsHTML}</div>
              </div>
            </section>`;
        } else {
          board.innerHTML = `
          <section class="cmp-neo-board">
            <header class="cmp-neo-board-head">
              <div class="cmp-neo-head-main">
                <div class="cmp-neo-title-wrap">
                  <h3>${Sec.escapeHTML(title)}</h3>
                  ${titleContext ? `<p class="cmp-neo-head-context">${Sec.escapeHTML(titleContext)}</p>` : ''}
                  ${subtitle ? `<p class="cmp-neo-head-desc">${Sec.escapeHTML(subtitle)}</p>` : ''}
                </div>
              </div>
            </header>
            <div class="cmp-neo-toolbar toolbar wf-toolbar" style="display:flex !important;flex-direction:row !important;align-items:center !important;gap:8px !important;width:100% !important;box-sizing:border-box !important">
              <div class="cmp-neo-search-combo${backNav ? ' has-back' : ''}" style="flex:1 1 auto !important;min-width:0 !important;display:flex !important;align-items:center !important;gap:8px !important">
                ${backNav || ''}
                <div class="figma-search-wrap wf-search cmp-neo-search cmp-neo-search-combo__field rd-app-search" style="flex:1 1 auto;min-width:0;width:100%">
                  <input type="text" class="figma-search-input rd-app-search__input" id="cmp-search"
                    value="${Sec.escapeHTML(cmpSearchVal)}"
                    placeholder="${Sec.escapeHTML(cmpSearchPh)}"
                    oninput="filterCmpSearch()"
                    autocomplete="off"
                    enterkeyhint="search">
                  <button type="button" class="figma-search-btn" onclick="filterCmpSearch()" aria-label="╪¿╪¡╪½">
                    <i class="fas fa-magnifying-glass"></i>
                  </button>
                </div>
              </div>
              ${canPickCmpScope() ? `<div class="wf-status-filter" id="cmp-filter-dd" style="flex:0 0 auto !important;max-width:32vw !important">
                <button type="button" class="wf-status-trigger" id="cmp-filter-trigger"
                  onclick="cmpFilterToggle(event)" aria-haspopup="listbox" aria-expanded="false"
                  style="height:42px !important;min-height:42px !important;border-radius:12px !important;padding:0 10px !important;display:flex !important;align-items:center !important;gap:6px !important">
                  <span class="wf-status-trigger__ico" aria-hidden="true" style="flex-shrink:0 !important"><i class="fas fa-filter"></i></span>
                  <span class="wf-status-trigger__label" id="cmp-filter-label" style="font-size:10px !important;white-space:nowrap !important;overflow:hidden !important;text-overflow:ellipsis !important">┘â┘ä ╪º┘ä┘à┘å╪º╪╖┘é</span>
                  <i class="fas fa-chevron-down wf-status-trigger__chev" aria-hidden="true" style="display:none !important"></i>
                </button>
                <select id="cmp-filter-scope" class="wf-status-select-native" tabindex="-1" aria-hidden="true"
                  aria-label="┘å╪╖╪º┘é ╪º┘ä╪╣╪▒╪╢" onchange="cmpFilterMobNativeChange(this)">
                  <option value="regions">┘â┘ä ╪º┘ä┘à┘å╪º╪╖┘é</option>
                  <option value="branches">┘â┘ä ╪º┘ä┘ü╪▒┘ê╪╣</option>
                  <option value="employees">┘â┘ä ╪º┘ä┘à┘ê╪╕┘ü┘è┘å</option>
                </select>
              </div>` : ''}
              <div class="rp-date-wrap" id="cmpNeoDateWrap" style="flex:0 0 auto !important">
                <button type="button" class="rp-tool-btn rp-date-btn" onclick="toggleCmpDatePicker(event)" id="cmp-date-btn"
                  style="width:42px !important;height:42px !important;min-width:42px !important;min-height:42px !important;border-radius:12px !important;padding:0 !important;display:flex !important;align-items:center !important;justify-content:center !important;flex-shrink:0 !important">
                  <i class="fas fa-calendar" style="margin:0 !important;font-size:16px !important"></i><span id="cmp-date-label" style="display:none !important">${Sec.escapeHTML(dateLabel)}</span>
                </button>
              </div>
              ${hasPermission('export_compliance') ? `<button type="button" class="rp-tool-btn cmp-neo-btn--pdf-export" onclick="exportCompliancePDF()">
                <i class="fas fa-file-pdf"></i><span>╪¬╪╡╪»┘è╪▒ PDF</span>
              </button>` : ''}
            </div>
            <p class="cmp-neo-search-meta">╪╣╪»╪» ╪º┘ä┘å╪¬╪º╪ª╪¼: <strong id="cmp-search-count">${cmpDataPending ? 'ΓÇª' : items.length}</strong></p>
            ${extremesBarHTML}
            <div class="${gridCls}">${cardsHTML}</div>
          </section>`;
        }

        const neoBoard = board.querySelector('.cmp-neo-board');
        const filtersBar = document.getElementById('cmpActiveFiltersBar');
        if (neoBoard && filtersBar && filtersBar.parentElement !== neoBoard) {
          neoBoard.appendChild(filtersBar);
        }

        cmpEnsureDatePickerHome();

        if (!cmpDataPending) {
          requestAnimationFrame(() => {
            cmpAnimateDonuts(board);
            cmpAnimateEmpChips(board);
            cmpAnimateNeoBoard(board);
          });
        }

        updateCmpActiveFiltersTags();
        cmpFilterSyncUi();
        if (typeof syncCmpMobileScrollShell === 'function') {
          syncCmpMobileScrollShell('compliance');
          requestAnimationFrame(() => syncCmpMobileScrollShell('compliance'));
        }
      }


      // ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
      // KPIs (4 ╪¿╪╖╪º┘é╪º╪¬ ╪Ñ╪¡╪╡╪º╪ª┘è╪⌐)
      // ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
      function renderCmpKpis(items, tab) {
        const c = document.getElementById('cmpKpis');
        if (!c) return;

        const total = items.length;
        const avgScore = total > 0 ? Math.round(items.reduce((a, b) => a + b.score, 0) / total) : 0;
        const excellent = items.filter(i => i.score >= 90).length;
        const danger = items.filter(i => i.score < 50).length;
        const totalViols = items.reduce((a, b) => a + (b.violCount || 0), 0);
        const safetyRate = total > 0 ? Math.round((excellent / total) * 100) : 0;

        const labels = {
          regions: { entity: '┘à┘å╪╖┘é╪⌐', icon1: 'fa-map-marker-alt' },
          branches: { entity: '┘ü╪▒╪╣', icon1: 'fa-store' },
          employees: { entity: '┘à┘ê╪╕┘ü', icon1: 'fa-user' }
        };
        const lbl = labels[tab] || labels.regions;

        // ┘à╪│╪¬┘ê┘ë ╪º┘ä╪ú╪»╪º╪í ╪º┘ä╪╣╪º┘à (┘à┘à╪¬╪º╪▓/╪¼┘è╪»/╪¬╪¡╪░┘è╪▒/┘à╪¬╪╣╪½╪▒)
        const overallTone = avgScore >= 90 ? 'green' : (avgScore >= 75 ? 'blue' : (avgScore >= 50 ? 'amber' : 'red'));
        const overallLabel = avgScore >= 90 ? '┘à┘à╪¬╪º╪▓' : (avgScore >= 75 ? '╪¼┘è╪»' : (avgScore >= 50 ? '╪¬╪¡╪░┘è╪▒' : '┘à╪¬╪╣╪½╪▒'));

        c.innerHTML = `
        <div class="kpi-card" data-tone="${overallTone}">
          <div class="kpi-head">
            <div class="kpi-icon"><i class="fas fa-gauge-high"></i></div>
            <div class="kpi-title">┘à╪¬┘ê╪│╪╖ ╪º┘ä╪ú╪»╪º╪í ╪º┘ä╪╣╪º┘à</div>
          </div>
          <div class="kpi-value">${avgScore}<span style="font-size:18px;color:var(--text3)">/100</span></div>
          <div class="kpi-foot">
            <span class="kpi-trend ${avgScore >= 75 ? 'up' : (avgScore < 50 ? 'down' : 'flat')}">
              ${overallLabel}
            </span>
            <span>┬╖ ${total} ${lbl.entity}</span>
          </div>
        </div>

        <div class="kpi-card" data-tone="green">
          <div class="kpi-head">
            <div class="kpi-icon"><i class="fas fa-shield-halved"></i></div>
            <div class="kpi-title">┘à╪╣╪»┘ä ╪º┘ä╪º┘å╪╢╪¿╪º╪╖</div>
          </div>
          <div class="kpi-value">${safetyRate}<span style="font-size:18px;color:var(--text3)">%</span></div>
          <div class="kpi-foot">
            <span>${excellent} ┘à┘å ${total} ┘ü┘è ╪º┘ä┘à╪│╪¬┘ê┘ë ╪º┘ä┘à┘à╪¬╪º╪▓</span>
          </div>
        </div>

        <div class="kpi-card" data-tone="${danger > 0 ? 'red' : 'green'}">
          <div class="kpi-head">
            <div class="kpi-icon"><i class="fas fa-triangle-exclamation"></i></div>
            <div class="kpi-title">${lbl.entity}╪º╪¬ ┘à╪¬╪╣╪½╪▒╪⌐</div>
          </div>
          <div class="kpi-value">${danger}</div>
          <div class="kpi-foot">
            ${danger > 0
            ? '<span class="kpi-trend down"><i class="fas fa-arrow-down"></i> ╪ú╪»╪º╪í ╪ú┘é┘ä ┘à┘å 50</span>'
            : '<span class="kpi-trend up"><i class="fas fa-check"></i> ┘ä╪º ┘è┘ê╪¼╪» ╪¬╪╣╪½╪▒</span>'
          }
          </div>
        </div>

        <div class="kpi-card" data-tone="${totalViols > 0 ? 'amber' : 'green'}">
          <div class="kpi-head">
            <div class="kpi-icon"><i class="fas fa-file-circle-exclamation"></i></div>
            <div class="kpi-title">╪º┘ä┘à╪«╪º┘ä┘ü╪º╪¬ (╪╢┘à┘å ╪º┘ä┘ü╪¬╪▒╪⌐)</div>
          </div>
          <div class="kpi-value">${totalViols}</div>
          <div class="kpi-foot">
            <span>╪Ñ╪¼┘à╪º┘ä┘è ┘ü┘è ╪º┘ä┘ü╪¬╪▒╪⌐ ╪º┘ä┘à╪«╪¬╪º╪▒╪⌐</span>
          </div>
        </div>
      `;
      }

      // ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
      // Performance Distribution Bar
      // ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
      function renderCmpDistribution(items, tab) {
        const c = document.getElementById('cmpDistCard');
        if (!c) return;

        const total = items.length;
        const counts = {
          excellent: items.filter(i => i.score >= 90).length,
          good: items.filter(i => i.score >= 75 && i.score < 90).length,
          warn: items.filter(i => i.score >= 50 && i.score < 75).length,
          danger: items.filter(i => i.score < 50).length
        };

        const segments = [
          { key: 'excellent', tone: 'green', label: '┘à┘à╪¬╪º╪▓ (90+)', count: counts.excellent },
          { key: 'good', tone: 'blue', label: '╪¼┘è╪» (75-89)', count: counts.good },
          { key: 'warn', tone: 'amber', label: '┘à╪¬┘ê╪│╪╖ (50-74)', count: counts.warn },
          { key: 'danger', tone: 'red', label: '┘à╪¬╪╣╪½╪▒ (<50)', count: counts.danger }
        ];

        const labels = { regions: '┘à┘å╪╖┘é╪⌐', branches: '┘ü╪▒╪╣', employees: '┘à┘ê╪╕┘ü' };
        const entity = labels[tab] || '┘â┘è╪º┘å';

        if (total === 0) {
          c.innerHTML = `
          <div class="cmp-dist-head">
            <div class="cmp-dist-title"><i class="fas fa-chart-column"></i> ╪¬┘ê╪▓┘è╪╣ ┘à╪│╪¬┘ê┘è╪º╪¬ ╪º┘ä╪ú╪»╪º╪í</div>
          </div>
          <div style="text-align:center;color:var(--text3);padding:20px;font-size:13px">┘ä╪º ╪¬┘ê╪¼╪» ╪¿┘è╪º┘å╪º╪¬</div>
        `;
          return;
        }

        const barHTML = segments.map(s => {
          const pct = (s.count / total) * 100;
          if (pct === 0) return '';
          return `<div class="cmp-dist-segment" data-tone="${s.tone}" style="width:${pct}%" title="${s.label}: ${s.count}">
          ${pct >= 8 ? `${s.count}` : ''}
        </div>`;
        }).join('');

        const legendHTML = segments.map(s => {
          const pct = total > 0 ? Math.round((s.count / total) * 100) : 0;
          const dotColor = { green: 'var(--green)', blue: 'var(--blue)', amber: 'var(--amber)', red: 'var(--red)' }[s.tone];
          return `
          <div class="cmp-dist-legend-item">
            <div class="cmp-dist-legend-dot" style="background:${dotColor}"></div>
            <span>${s.label}:</span>
            <span class="count">${s.count}</span>
            <span style="color:var(--text3)">(${pct}%)</span>
          </div>
        `;
        }).join('');

        c.innerHTML = `
        <div class="cmp-dist-head">
          <div class="cmp-dist-title"><i class="fas fa-chart-column"></i> ╪¬┘ê╪▓┘è╪╣ ┘à╪│╪¬┘ê┘è╪º╪¬ ╪º┘ä╪ú╪»╪º╪í</div>
          <div class="cmp-dist-total">╪º┘ä╪Ñ╪¼┘à╪º┘ä┘è: <strong>${total} ${entity}</strong></div>
        </div>
        <div class="cmp-dist-bar">${barHTML}</div>
        <div class="cmp-dist-legend">${legendHTML}</div>
      `;
      }

      // ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
      // Podium (Top 3 + Bottom 3)
      // ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
      function renderCmpPodium(items, tab) {
        const c = document.getElementById('cmpPodium');
        if (!c) return;

        const sorted = [...items].sort((a, b) => b.score - a.score);
        const top3 = sorted.slice(0, 3);
        
        // ╪º┘ä╪ú┘é┘ä: ┘å╪ú╪«╪░ ╪ó╪«╪▒ 3. 
        // ╪Ñ╪░╪º ┘â╪º┘å ╪º┘ä╪╣╪»╪» ╪º┘ä╪Ñ╪¼┘à╪º┘ä┘è ╪╡╪║┘è╪▒╪º┘ï (╪ú┘é┘ä ┘à┘å 6)╪î ┘ä╪º ┘å╪│╪¬╪½┘å┘è ╪º┘ä┘Ç top3 ┘ä┘å╪╢┘à┘å ╪╕┘ç┘ê╪▒ ╪º┘ä┘à┘å╪º╪╖┘é ╪º┘ä┘à╪¬╪╣╪½╪▒╪⌐ ╪¡╪¬┘ë ┘ä┘ê ┘â╪º┘å╪¬ ┘ü┘è ╪º┘ä┘é╪º╪ª┘à╪⌐ ╪º┘ä┘é╪╡┘è╪▒╪⌐
        let bottom3;
        if (sorted.length <= 6) {
          bottom3 = [...sorted].reverse().slice(0, 3);
        } else {
          const topIds = new Set(top3.map(i => i.id));
          bottom3 = [...sorted].reverse().filter(i => !topIds.has(i.id)).slice(0, 3);
        }
        
        // ╪¬╪¡╪│┘è┘å: ╪º╪│╪¬╪¿╪╣╪º╪» ╪º┘ä╪╣┘å╪º╪╡╪▒ ╪º┘ä╪¬┘è ╪»╪▒╪¼╪¬┘ç╪º 100 ┘à┘å "╪¬╪¡╪¬╪º╪¼ ╪╣┘å╪º┘è╪⌐" ╪Ñ╪░╪º ┘â╪º┘å ┘ç┘å╪º┘â ╪¿╪»╪º╪ª┘ä
        if (bottom3.length > 0) {
           const lowItems = bottom3.filter(it => it.score < 100);
           if (lowItems.length > 0) {
             // ╪Ñ╪░╪º ┘ê╪¼╪»┘å╪º ╪╣┘å╪º╪╡╪▒ ┘à╪¬╪╣╪½╪▒╪⌐ ┘ü╪╣┘ä╪º┘ï╪î ┘å┘â╪¬┘ü┘è ╪¿┘ç╪º
             bottom3 = lowItems;
           } else if (sorted.length > 3) {
             // ╪Ñ╪░╪º ┘â┘ä ╪º┘ä┘Ç bottom3 ╪»╪▒╪¼╪¬┘ç┘à 100╪î ┘ê╪º┘ä╪╣╪»╪» ╪º┘ä┘â┘ä┘è ╪ú┘â╪¿╪▒ ┘à┘å 3╪î ┘è┘ü╪╢┘ä ╪Ñ╪╕┘ç╪º╪▒ ╪▒╪│╪º┘ä╪⌐ "┘å╪╕┘è┘ü"
             // ┘ä┘â┘å┘å╪º ╪│┘å╪¿┘é┘è┘ç╪º ┘â┘é╪º╪ª┘à╪⌐ ┘ü╪º╪▒╪║╪⌐ ┘ä╪¬╪╣╪╖┘è ╪º┘å╪╖╪¿╪º╪╣╪º┘ï ╪¼┘è╪»╪º┘ï
             bottom3 = [];
           }
        }

        const labels = {
          regions: { topTitle: '╪ú╪╣┘ä┘ë ╪º┘ä┘à┘å╪º╪╖┘é ╪º╪│╪¬┘é╪▒╪º╪▒╪º┘ï', bottomTitle: '┘à┘å╪º╪╖┘é ╪¬╪¡╪¬╪º╪¼ ╪╣┘å╪º┘è╪⌐' },
          branches: { topTitle: '╪º┘ä┘ü╪▒┘ê╪╣ ╪º┘ä┘à╪½╪º┘ä┘è╪⌐', bottomTitle: '┘ü╪▒┘ê╪╣ ╪¬╪¡╪¬╪º╪¼ ╪╣┘å╪º┘è╪⌐' },
          employees: { topTitle: '┘å╪¼┘ê┘à ╪º┘ä╪º┘å╪╢╪¿╪º╪╖', bottomTitle: '┘à┘ê╪╕┘ü┘ê┘å ┘è╪¡╪¬╪º╪¼┘ê┘å ┘à╪¬╪º╪¿╪╣╪⌐' }
        };
        const lbl = labels[tab] || labels.regions;

        const medalCls = ['gold', 'silver', 'bronze'];

        const buildItem = (item, idx, isTop) => {
          const lvl = levelClass(item.score);
          const medal = isTop ? medalCls[idx] : 'warn';
          const medalIcon = isTop
            ? (idx === 0 ? '<i class="fas fa-trophy"></i>' : `${idx + 1}`)
            : '<i class="fas fa-exclamation"></i>';
          return `
          <div class="podium-item">
            <div class="podium-medal ${medal}">${medalIcon}</div>
            <div class="podium-info">
              <div class="podium-name">${Sec.escapeHTML(item.name)}${item.empNumber ? ` <span style="color:var(--text3);font-family:var(--mono);font-size:11px">(${Sec.escapeHTML(item.empNumber)})</span>` : ''}</div>
              <div class="podium-meta">${Sec.escapeHTML(item.meta || '')}</div>
            </div>
            <div class="podium-score ${lvl}">${Math.round(item.score)}</div>
          </div>
        `;
        };

        c.innerHTML = `
        <div class="podium-card top">
          <div class="podium-head">
            <div class="podium-head-icon"><i class="fas fa-trophy"></i></div>
            <div class="podium-head-text">
              <div class="podium-head-title">${lbl.topTitle}</div>
              <div class="podium-head-sub">╪ú╪╣┘ä┘ë 3 ┘à┘å ╪¡┘è╪½ ╪º┘ä╪ú╪»╪º╪í</div>
            </div>
          </div>
          <div class="podium-list">
            ${top3.length
            ? top3.map((it, i) => buildItem(it, i, true)).join('')
            : '<div class="podium-empty">┘ä╪º ╪¬┘ê╪¼╪» ╪¿┘è╪º┘å╪º╪¬</div>'
          }
          </div>
        </div>

        <div class="podium-card bottom">
          <div class="podium-head">
            <div class="podium-head-icon"><i class="fas fa-triangle-exclamation"></i></div>
            <div class="podium-head-text">
              <div class="podium-head-title">${lbl.bottomTitle}</div>
              <div class="podium-head-sub">┘è╪¡╪¬╪º╪¼┘ê┘å ┘à╪¬╪º╪¿╪╣╪⌐ ┘ê╪¬╪¡╪│┘è┘å</div>
            </div>
          </div>
          <div class="podium-list">
            ${bottom3.length
            ? bottom3.map((it, i) => buildItem(it, i, false)).join('')
            : '<div class="podium-empty">┘ä╪º ╪¬┘ê╪¼╪» ╪¿┘è╪º┘å╪º╪¬ ╪¬╪¡╪¬╪º╪¼ ┘à╪¬╪º╪¿╪╣╪⌐</div>'
          }
          </div>
        </div>
      `;
      }

      // ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
      // ╪º┘ä╪¼╪»┘ê┘ä ╪º┘ä╪¬┘ü╪╡┘è┘ä┘è ╪º┘ä╪º╪¡╪¬╪▒╪º┘ü┘è
      // ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
      function renderCmpDetailedList(items) {
        const c = document.getElementById('cmpTableCard');
        if (!c) return;

        const tab = state._cmpActiveTab || 'regions';
        const tabLabels = {
          regions: { entity: '╪º┘ä┘à┘å╪╖┘é╪⌐', detail: '╪º┘ä┘ü╪▒┘ê╪╣/╪º┘ä┘à┘ê╪╕┘ü┘è┘å' },
          branches: { entity: '╪º┘ä┘ü╪▒╪╣', detail: '╪º┘ä┘à┘å╪╖┘é╪⌐' },
          employees: { entity: '╪º┘ä┘à┘ê╪╕┘ü', detail: '╪º┘ä┘ü╪▒╪╣' }
        };
        const lbl = tabLabels[tab] || tabLabels.regions;

        if (!items.length) {
          c.innerHTML = `
          <div class="cmp-table-head">
            <div>
              <div class="cmp-table-title"><i class="fas fa-list-check"></i> ╪º┘ä┘é╪º╪ª┘à╪⌐ ╪º┘ä╪¬┘ü╪╡┘è┘ä┘è╪⌐</div>
              <div class="cmp-table-sub">┘ä╪º ╪¬┘ê╪¼╪» ╪¿┘è╪º┘å╪º╪¬</div>
            </div>
          </div>
          <div class="cmp-table-empty">
            <i class="fas fa-folder-open"></i>
            <p>┘ä╪º ╪¬┘ê╪¼╪» ╪¿┘è╪º┘å╪º╪¬ ┘à╪╖╪º╪¿┘é╪⌐ ┘ä┘ä┘ü┘ä╪º╪¬╪▒ ╪º┘ä┘à╪¡╪»╪»╪⌐</p>
          </div>
        `;
          return;
        }

        // ╪¡╪│╪º╪¿ ╪º┘ä┘Ç severity breakdown ╪╣┘ä┘ë ┘à╪│╪¬┘ê┘ë ┘â┘ä ╪╣┘å╪╡╪▒
        const violations = getViolationsForScoring();

        const buildRow = (item, idx) => {
          const lvl = levelClass(item.score);
          const lvlText = item.score >= 90 ? '┘à┘à╪¬╪º╪▓' : (item.score >= 75 ? '╪¼┘è╪»' : (item.score >= 50 ? '╪¬╪¡╪░┘è╪▒' : '┘à╪¬╪╣╪½╪▒'));
          const rankCls = idx === 0 ? 'top1' : (idx === 1 ? 'top2' : (idx === 2 ? 'top3' : ''));
          const rankIcon = idx === 0 ? '<i class="fas fa-crown"></i>' : (idx + 1);

          // ΓöÇΓöÇΓöÇ ╪¡╪│╪º╪¿ Severity Breakdown ┘ä┘ä╪╣┘å╪╡╪▒ ΓöÇΓöÇΓöÇ
          const sevBreakdown = computeSeverityForItem(item, violations);
          const totalSev = sevBreakdown.low + sevBreakdown.mid + sevBreakdown.high + sevBreakdown.crit;

          // ╪┤╪▒┘è╪╖ ╪º┘ä┘Ç severity
          let sevBar = '';
          if (totalSev > 0) {
            const segments = [
              { key: 'low', cls: 'cmp-sev-low', count: sevBreakdown.low },
              { key: 'mid', cls: 'cmp-sev-mid', count: sevBreakdown.mid },
              { key: 'high', cls: 'cmp-sev-high', count: sevBreakdown.high },
              { key: 'crit', cls: 'cmp-sev-crit', count: sevBreakdown.crit }
            ].filter(s => s.count > 0);
            sevBar = `
            <div class="cmp-sev-bar">
              ${segments.map(s => {
              const pct = (s.count / totalSev) * 100;
              return `<div class="${s.cls}" style="width:${pct}%" title="${s.count}"></div>`;
            }).join('')}
            </div>
            <div class="cmp-sev-counts">
              ${sevBreakdown.low > 0 ? `<span><span class="dot cmp-sev-low"></span>${sevBreakdown.low}</span>` : ''}
              ${sevBreakdown.mid > 0 ? `<span><span class="dot cmp-sev-mid"></span>${sevBreakdown.mid}</span>` : ''}
              ${sevBreakdown.high > 0 ? `<span><span class="dot cmp-sev-high"></span>${sevBreakdown.high}</span>` : ''}
              ${sevBreakdown.crit > 0 ? `<span><span class="dot cmp-sev-crit"></span>${sevBreakdown.crit}</span>` : ''}
            </div>
          `;
          } else {
            sevBar = `<div class="cmp-sev-counts"><span style="color:var(--green-text)"><i class="fas fa-check"></i> ╪│╪¼┘ä ┘å╪╕┘è┘ü</span></div>`;
          }

          // ΓöÇΓöÇΓöÇ ╪º┘ä╪¬╪▒┘å╪» ΓöÇΓöÇΓöÇ
          const trendData = computeTrendForItem(item, violations);
          const trendBadge = trendData.label
            ? `<span class="cmp-trend-badge ${trendData.cls}">
              <i class="fas ${trendData.icon}"></i> ${trendData.label}
             </span>`
            : '<span style="color:var(--text3);font-size:11px">ΓÇö</span>';

          // ΓöÇΓöÇΓöÇ ╪º┘ä╪¡╪º┘ä╪⌐ (Status Tags) ΓöÇΓöÇΓöÇ
          const statusTags = [];
          if (item.actionRequired || item.score < 40) {
            statusTags.push(`<span class="cmp-status-tag action"><i class="fas fa-bell"></i> ┘è╪¡╪¬╪º╪¼ ╪¬╪»╪«┘ä</span>`);
          } else if (item.score < 75) {
            statusTags.push(`<span class="cmp-status-tag outlier"><i class="fas fa-triangle-exclamation"></i> ╪¬╪▒╪º╪¼╪╣ ╪ú╪»╪º╪í</span>`);
          }

          if (item.hasOutlier) {
            statusTags.push(`<span class="cmp-status-tag outlier"><i class="fas fa-user-slash"></i> ╪«┘ä┘ä ┘ü╪▒╪»┘è</span>`);
          }
          if (item.outliers > 0) {
            statusTags.push(`<span class="cmp-status-tag outlier"><i class="fas fa-exclamation"></i> ${item.outliers} ┘ü╪▒╪╣ ┘à╪¬╪╣╪½╪▒</span>`);
          }
          if (item.scoreHealed) {
            statusTags.push(`<span class="cmp-status-tag streak"><i class="fas fa-heart-pulse"></i> ╪¬╪╣╪º┘ü┘ë 100</span>`);
          } else if (item.streakBonus > 0) {
            statusTags.push(`<span class="cmp-status-tag streak"><i class="fas fa-fire"></i> ╪¿┘ê┘å╪╡ +${item.streakBonus}</span>`);
          }
          if (item.recencyIndex > 60 && totalSev > 0) {
            statusTags.push(`<span class="cmp-status-tag fresh"><i class="fas fa-clock"></i> ${item.recencyIndex}% ╪¡╪»┘è╪½╪⌐</span>`);
          }
          if (item.score === 100) {
            statusTags.push(`<span class="cmp-status-tag ok"><i class="fas fa-check-double"></i> ╪│╪¼┘ä ┘å╪╕┘è┘ü</span>`);
          }

          if (!statusTags.length) {
            statusTags.push(`<span class="cmp-status-tag ok"><i class="fas fa-check"></i> ╪╖╪¿┘è╪╣┘è</span>`);
          }

          // ΓöÇΓöÇΓöÇ ╪º┘ä╪ú┘ü╪º╪¬╪º╪▒/╪º┘ä╪ú┘è┘é┘ê┘å╪⌐ ΓöÇΓöÇΓöÇ
          const avatarContent = item.type === 'employee'
            ? Sec.escapeHTML((item.name || '┘à').charAt(0))
            : `<i class="fas ${item.icon}"></i>`;

          // ΓöÇΓöÇΓöÇ ┘à╪╣┘ä┘ê┘à╪º╪¬ ╪º┘ä┘à┘ê┘é╪╣ ΓöÇΓöÇΓöÇ
          let locationCell = '';
          if (item.type === 'region') {
            locationCell = `
            <div class="cmp-location-line"><i class="fas fa-store"></i> ${item.extraInfo.branchesCount} ┘ü╪▒╪╣</div>
            <div class="cmp-location-line"><i class="fas fa-users"></i> ${item.extraInfo.totalEmps} ┘à┘ê╪╕┘ü</div>
            <div class="cmp-location-line"><i class="fas fa-user-tie"></i> ${Sec.escapeHTML(item.extraInfo.supName)}</div>
          `;
          } else if (item.type === 'branch') {
            locationCell = `
            <div class="cmp-location-line"><i class="fas fa-map-marker-alt"></i> ${Sec.escapeHTML(item.extraInfo.regionName)}</div>
            <div class="cmp-location-line"><i class="fas fa-shield-halved"></i> ${item.extraInfo.safeEmps}/${item.extraInfo.totalEmps} ┘à┘å╪╢╪¿╪╖</div>
          `;
          } else {
            locationCell = `
            <div class="cmp-location-line"><i class="fas fa-store"></i> ${Sec.escapeHTML(item.extraInfo.branchName)}</div>
            <div class="cmp-location-line"><i class="fas fa-minus"></i> ${item.extraInfo.deducted} ┘å┘é╪╖╪⌐ ┘à╪«╪╡┘ê┘à╪⌐</div>
          `;
          }

          const empNumDisplay = item.empNumber
            ? `<div class="cmp-entity-meta">${Sec.escapeHTML(item.empNumber)}</div>`
            : `<div class="cmp-entity-meta">${item.violCount || 0} ┘à╪«╪º┘ä┘ü╪⌐</div>`;

          const rowClass = (item.actionRequired || item.score < 40) ? 'action-required' : '';

          return `
          <tr class="${rowClass}">
            <td class="cmp-cell-rank" data-label="╪º┘ä╪¬╪▒╪¬┘è╪¿">
              <span class="cmp-rank-num ${rankCls}">${rankIcon}</span>
            </td>
            <td class="cmp-cell-entity" data-label="${Sec.escapeHTML(lbl.entity)}">
              <div class="cmp-entity-wrap${item.isInactive ? ' is-inactive' : ''}">
                <div class="cmp-entity-avatar" data-type="${item.type}">${avatarContent}</div>
                <div class="cmp-entity-text">
                  <div class="cmp-entity-name">${Sec.escapeHTML(item.name)}${item.isInactive ? '<span class="cmp-inactive-badge" title="╪º┘ä┘à╪│╪¬╪«╪»┘à ┘à╪╣╪╖┘æ┘ä ΓÇö ┘è╪╕┘ç╪▒ ┘ç┘å╪º ┘ä┘ä╪¡┘ü╪º╪╕ ╪╣┘ä┘ë ╪º┘ä╪│╪¼┘ä ╪º┘ä╪¬╪º╪▒┘è╪«┘è"><i class="fas fa-user-slash"></i> ┘à╪╣╪╖┘æ┘ä</span>' : ''}</div>
                  ${empNumDisplay}
                </div>
              </div>
            </td>
            <td class="cmp-cell-location" data-label="${Sec.escapeHTML(lbl.detail)}">
              ${locationCell}
            </td>
            <td class="cmp-cell-score" data-label="╪º┘ä╪»╪▒╪¼╪⌐">
              <div class="cmp-score-wrap">
                <div class="cmp-score-num ${lvl}">${Math.round(item.score)}</div>
                <div style="flex:1">
                  <div class="cmp-score-track">
                    <div class="cmp-score-fill ${lvl}" style="width:${Math.min(100, item.score)}%"></div>
                  </div>
                  <span class="cmp-score-label">${lvlText}</span>
                </div>
              </div>
            </td>
            <td class="cmp-cell-severity" data-label="┘å┘ê╪╣┘è╪⌐ ╪º┘ä┘à╪«╪º┘ä┘ü╪º╪¬">
              ${sevBar}
            </td>
            <td class="cmp-cell-trend" data-label="╪º┘ä╪º╪¬╪¼╪º┘ç">
              ${trendBadge}
            </td>
            <td class="cmp-cell-status" data-label="╪º┘ä╪¡╪º┘ä╪⌐">
              <div class="cmp-status-tags">${statusTags.join('')}</div>
            </td>
            <td class="cmp-cell-action" data-label="">
              <button class="cmp-detail-btn" onclick="openCmpItemDetail('${item.type}','${item.id}')">
                <i class="fas fa-eye"></i> ╪¬┘ü╪º╪╡┘è┘ä
              </button>
            </td>
          </tr>
        `;
        };

        c.innerHTML = `
        <div class="cmp-table-head">
          <div>
            <div class="cmp-table-title"><i class="fas fa-list-check"></i> ╪º┘ä┘é╪º╪ª┘à╪⌐ ╪º┘ä╪¬┘ü╪╡┘è┘ä┘è╪⌐</div>
            <div class="cmp-table-sub">${items.length} ╪╣┘å╪╡╪▒ ┬╖ ┘à╪▒╪¬╪¿ ╪¡╪│╪¿ ${cmpfState.sort === 'top' ? '╪º┘ä╪ú╪╣┘ä┘ë ╪ú╪»╪º╪í' : (cmpfState.sort === 'bottom' ? '╪º┘ä╪ú┘é┘ä ╪ú╪»╪º╪í' : '╪º┘ä╪¬╪▒╪¬┘è╪¿ ╪º┘ä╪½╪º╪¿╪¬')}</div>
          </div>
        </div>
        <div class="cmp-table-wrap">
          <table class="cmp-table">
            <thead>
              <tr>
                <th class="cmp-cell-rank">#</th>
                <th class="cmp-cell-entity">${Sec.escapeHTML(lbl.entity)}</th>
                <th class="cmp-cell-location">${Sec.escapeHTML(lbl.detail)}</th>
                <th class="cmp-cell-score">╪º┘ä╪»╪▒╪¼╪⌐</th>
                <th class="cmp-cell-severity">┘å┘ê╪╣┘è╪⌐ ╪º┘ä┘à╪«╪º┘ä┘ü╪º╪¬</th>
                <th class="cmp-cell-trend">╪º┘ä╪º╪¬╪¼╪º┘ç</th>
                <th class="cmp-cell-status">╪º┘ä╪¡╪º┘ä╪⌐</th>
                <th class="cmp-cell-action"></th>
              </tr>
            </thead>
            <tbody>
              ${items.map(buildRow).join('')}
            </tbody>
          </table>
        </div>
      `;
      }

      /**
       * ╪º╪¡╪│╪¿ ╪¬┘ê╪▓┘è╪╣ ╪º┘ä╪«╪╖┘ê╪▒╪⌐ ┘ä╪╣┘å╪╡╪▒ (┘à┘ê╪╕┘ü/┘ü╪▒╪╣/┘à┘å╪╖┘é╪⌐)
       */
      function computeSeverityForItem(item, violations) {
        let viols = [];
        if (item.type === 'employee') {
          viols = violations.filter(v => v.employee_id === item.id);
        } else if (item.type === 'branch') {
          viols = violations.filter(v => v.branch_id === item.id);
        } else if (item.type === 'region') {
          const regBranches = state.branches.filter(b => b.region_id === item.id);
          const branchIds = new Set(regBranches.map(b => b.id));
          viols = violations.filter(v => branchIds.has(v.branch_id));
        }

        const breakdown = { low: 0, mid: 0, high: 0, crit: 0 };
        getRateImpactingViolations(viols).forEach(v => {
          const type = state.violationTypes.find(x => x.name === v.violation_type);
          const sev = type?.severity || '┘à┘å╪«┘ü╪╢';
          if (sev === '┘à┘å╪«┘ü╪╢') breakdown.low++;
          else if (sev === '┘à╪¬┘ê╪│╪╖') breakdown.mid++;
          else if (sev === '╪╣╪º┘ä┘è') breakdown.high++;
          else if (sev === '╪╣╪º┘ä┘è') breakdown.high++;
        });
        return breakdown;
      }

      /**
       * ╪º╪¡╪│╪¿ ╪º┘ä╪¬╪▒┘å╪» ┘ä┘ä╪╣┘å╪╡╪▒ (┘à┘é╪º╪▒┘å╪⌐ 30 ┘è┘ê┘à ╪¿╪º┘ä┘Ç 30 ┘è┘ê┘à ╪º┘ä┘ä┘è ┘é╪¿┘ä┘ç╪º)
       */
      function computeTrendForItem(item, violations) {
        let viols = [];
        if (item.type === 'employee') {
          viols = violations.filter(v => v.employee_id === item.id);
        } else if (item.type === 'branch') {
          viols = violations.filter(v => v.branch_id === item.id);
        } else if (item.type === 'region') {
          const regBranches = state.branches.filter(b => b.region_id === item.id);
          const branchIds = new Set(regBranches.map(b => b.id));
          viols = violations.filter(v => branchIds.has(v.branch_id));
        }

        const recent30 = viols.filter(v => !violationExcludedFromDeduction(v) && violationAgeDays(v) <= 30).length;
        const prev30 = viols.filter(v => {
          if (violationExcludedFromDeduction(v)) return false;
          const a = violationAgeDays(v);
          return a > 30 && a <= 60;
        }).length;

        // ╪Ñ╪░╪º ┘ä╪º ╪¬┘ê╪¼╪» ╪¿┘è╪º┘å╪º╪¬ ┘ü┘è ╪º┘ä┘ü╪¬╪▒╪¬┘è┘å
        if (recent30 === 0 && prev30 === 0) {
          return { label: '┘à╪│╪¬┘é╪▒', cls: 'flat', icon: 'fa-minus' };
        }

        // ╪¬╪¡╪│┘æ┘å: ┘à╪«╪º┘ä┘ü╪º╪¬ ╪ú┘é┘ä ┘ü┘è ╪º┘ä┘ü╪¬╪▒╪⌐ ╪º┘ä╪¡╪»┘è╪½╪⌐
        if (recent30 < prev30) {
          const drop = prev30 - recent30;
          return { label: `╪¬╪¡╪│┘æ┘å`, cls: 'up', icon: 'fa-arrow-trend-up' };
        }

        // ╪¬╪▒╪º╪¼╪╣: ┘à╪«╪º┘ä┘ü╪º╪¬ ╪ú┘â╪½╪▒ ┘ü┘è ╪º┘ä┘ü╪¬╪▒╪⌐ ╪º┘ä╪¡╪»┘è╪½╪⌐
        if (recent30 > prev30) {
          return { label: `╪¬╪▒╪º╪¼╪╣`, cls: 'down', icon: 'fa-arrow-trend-down' };
        }

        return { label: '┘à╪│╪¬┘é╪▒', cls: 'flat', icon: 'fa-minus' };
      }

      // ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ
      // Compliance Item Detail Modal (╪º┘ä┘à╪▒╪¡┘ä╪⌐ 3)
      // ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ

      function openCmpItemDetail(type, id) {
        const violations = getViolationsForScoring();
        let item, related, viols, breakdown;

        // ΓöÇΓöÇΓöÇ ╪¼┘à╪╣ ╪º┘ä╪¿┘è╪º┘å╪º╪¬ ╪¡╪│╪¿ ┘å┘ê╪╣ ╪º┘ä╪╣┘å╪╡╪▒ ΓöÇΓöÇΓöÇ
        if (type === 'employee') {
          const emp = state.users.find(u => u.id === id);
          if (!emp) return showToast('╪º┘ä┘à┘ê╪╕┘ü ╪║┘è╪▒ ┘à┘ê╪¼┘ê╪»', 'error');
          const branch = state.branches.find(b => b.id === emp.branch_id);
          const region = branch ? state.regions.find(r => r.id === branch.region_id) : null;
          const stat = calcEmpScore(emp.id, violations);
          viols = violations.filter(v => v.employee_id === emp.id);

          item = {
            type: 'employee',
            id: emp.id,
            name: emp.name,
            empNumber: emp.employee_number,
            score: stat.score,
            stat,
            context: [
              { icon: 'fa-user-tie', label: '╪º┘ä┘à╪┤╪▒┘ü', value: (region ? state.users.find(u => u.id === region.supervisor_id)?.name : null) || '-' },
              { icon: 'fa-store', label: '╪º┘ä┘ü╪▒╪╣', value: branch?.name || '-' }
            ]
          };
        } else if (type === 'branch') {
          const branch = state.branches.find(b => b.id === id);
          if (!branch) return showToast('╪º┘ä┘ü╪▒╪╣ ╪║┘è╪▒ ┘à┘ê╪¼┘ê╪»', 'error');
          const region = state.regions.find(r => r.id === branch.region_id);
          const stat = calcBranchSafety(branch.id, violations);
          const branchEmps = getBranchStaff(branch.id);
          viols = violations.filter(v => v.branch_id === branch.id);

          item = {
            type: 'branch',
            id: branch.id,
            name: branch.name,
            subtitle: `${branch.city || '-'}`,
            score: stat.score,
            stat,
            context: [
              { icon: 'fa-map-marker-alt', label: '╪º┘ä┘à┘å╪╖┘é╪⌐', value: region?.name || '-' },
              { icon: 'fa-users', label: '╪Ñ╪¼┘à╪º┘ä┘è ╪º┘ä┘à┘ê╪╕┘ü┘è┘å', value: stat.totalEmps },
              { icon: 'fa-shield-halved', label: '┘à┘ê╪╕┘ü┘ê┘å ┘à┘å╪╢╪¿╪╖┘ê┘å', value: `${stat.safeEmps} (${Math.round(stat.safetyRate || 0)}%)` }
            ],
            breakdown: stat
          };
        } else if (type === 'region') {
          const region = state.regions.find(r => r.id === id);
          if (!region) return showToast('╪º┘ä┘à┘å╪╖┘é╪⌐ ╪║┘è╪▒ ┘à┘ê╪¼┘ê╪»╪⌐', 'error');
          const sup = state.users.find(u => u.id === region.supervisor_id);
          const stat = calcRegionStability(region.id, violations);
          const regBranches = state.branches.filter(b => b.region_id === region.id);
          const branchIds = new Set(regBranches.map(b => b.id));
          viols = violations.filter(v => branchIds.has(v.branch_id));

          item = {
            type: 'region',
            id: region.id,
            name: region.name,
            subtitle: '╪Ñ┘é┘ä┘è┘à',
            score: stat.score,
            stat,
            context: [
              { icon: 'fa-store', label: '╪╣╪»╪» ╪º┘ä┘ü╪▒┘ê╪╣', value: stat.branchesCount },
              { icon: 'fa-users', label: '╪Ñ╪¼┘à╪º┘ä┘è ╪º┘ä┘à┘ê╪╕┘ü┘è┘å', value: stat.totalEmps },
              { icon: 'fa-user-tie', label: '╪º┘ä┘à╪┤╪▒┘ü', value: sup?.name || '╪¿╪»┘ê┘å ┘à╪┤╪▒┘ü' }
            ],
            breakdown: stat
          };
        } else {
          return;
        }

        // ΓöÇΓöÇΓöÇ ╪¬╪¡╪»┘è╪½ Modal ΓöÇΓöÇΓöÇ
        const cmpModal = document.getElementById('cmpDetailModal');
        const cmpCard = cmpModal?.querySelector('.modal-card.cmp-detail-card');
        const rdEmp = (typeof isComplianceAtharUi === 'function' && isComplianceAtharUi()) && type === 'employee';
        cmpModal?.classList.toggle('cmp-detail--rd-emp', !!rdEmp);
        cmpCard?.classList.toggle('cmp-detail-card--rd-emp', !!rdEmp);

        document.getElementById('cmpDetailHero').innerHTML = buildCmpDetailHeroHTML(item);
        document.getElementById('cmpDetailBody').innerHTML = buildCmpDetailHTML(item, viols, violations);
        bindCmpTimelineNav(document.getElementById('cmpDetailBody'));

        openModal('cmpDetailModal');
      }



      function buildSeverityDonutHTML(breakdown, total) {
        const legendItems = [
          { count: (breakdown.high || 0) + (breakdown.crit || 0), color: '#FF0000', label: '╪╣╪º┘ä┘è', tone: 'high' },
          { count: breakdown.mid || 0, color: 'var(--amber)', label: '┘à╪¬┘ê╪│╪╖', tone: 'mid' },
          { count: breakdown.low || 0, color: 'var(--blue)', label: '┘à┘å╪«┘ü╪╢', tone: 'low' }
        ];

        const arcSegments = legendItems.filter(s => s.count > 0);
        const radius = 42;
        const circumference = 2 * Math.PI * radius;
        let cumulativeOffset = 0;
        const arcs = arcSegments.map(s => {
          const pct = s.count / total;
          const dashArray = `${pct * circumference} ${circumference}`;
          const arc = `
          <circle cx="70" cy="70" r="${radius}" fill="none"
            stroke="${s.color}" stroke-width="18"
            stroke-dasharray="${dashArray}"
            stroke-dashoffset="${-cumulativeOffset}"
            transform="rotate(-90 70 70)" />`;
          cumulativeOffset += pct * circumference;
          return arc;
        }).join('');

        const dotColors = { high: '#FF0000', mid: 'var(--amber)', low: 'var(--blue)' };
        const legendHTML = legendItems.map(s => {
          const pct = total > 0 ? Math.round((s.count / total) * 100) : 0;
          const muted = s.count === 0 ? ' cmp-sev-legend-item--empty' : '';
          return `
              <div class="cmp-sev-legend-item cmp-sev-legend-item--fig cmp-sev-legend-item--${s.tone}${muted}">
                <span class="cmp-sev-legend-label">
                  <span class="cmp-sev-legend-dot" style="background:${dotColors[s.tone]}"></span>
                  ${s.label}
                </span>
                <span class="cmp-sev-legend-meta">
                  <span class="cmp-sev-legend-count">${s.count}</span>
                  <span class="cmp-sev-legend-pct">${pct}%</span>
                </span>
              </div>`;
        }).join('');

        return `
        <div class="cmp-severity-grid">
          <div class="cmp-severity-legend">${legendHTML}</div>
          <div class="cmp-severity-donut">
            <svg viewBox="0 0 140 140" width="104" height="104" aria-hidden="true">
              <circle cx="70" cy="70" r="${radius}" fill="none" stroke="var(--bg2)" stroke-width="18"></circle>
              ${arcs}
              <text x="70" y="66" text-anchor="middle" fill="var(--text)" style="font-family:var(--mono);font-size:26px;font-weight:800">${total}</text>
              <text x="70" y="86" text-anchor="middle" fill="var(--text3)" style="font-size:11px;font-weight:600">┘à╪«╪º┘ä┘ü╪º╪¬</text>
            </svg>
          </div>
        </div>`;
      }

      function cmpApplyReportsMonthFilter(year, month0) {
        const range = ksaMonthRange(year, month0);
        const fromEl = document.getElementById('rp-from');
        const toEl = document.getElementById('rp-to');
        if (fromEl) fromEl.value = range.fromIso;
        if (toEl) toEl.value = range.toIso;
        const monthStart = new Date(year, month0, 1);
        const monthEnd = new Date(year, month0, range.daysInMonth);
        try {
          if (typeof dpState !== 'undefined') {
            dpState.from = monthStart;
            dpState.to = monthEnd;
            dpState.viewYear = year;
            dpState.viewMonth = month0;
            dpState.quickPreset = null;
            dpState.hover = null;
            dpState.pickerView = 'days';
          }
        } catch (_) { /* dpState ╪║┘è╪▒ ╪¼╪º┘ç╪▓ */ }
        const btn = document.getElementById('rp-date-btn');
        const lbl = document.getElementById('rp-date-label');
        if (btn && lbl) {
          dpApplyDateButtonLabel(btn, lbl, monthStart, monthEnd);
          btn.classList.add('active');
          btn.title = `${KSA_AR_MONTHS[month0]} ${year}`;
        }
        dpFloatClose(document.getElementById('datePickerPopup'));
      }

      function bindCmpTimelineNav(bodyEl) {
        if (!bodyEl || bodyEl.dataset.cmpTimelineNavBound === '1') return;
        bodyEl.dataset.cmpTimelineNavBound = '1';
        bodyEl.addEventListener('click', (e) => {
          const col = e.target.closest('.cmp-timeline-col--link');
          if (!col) return;
          const wrap = col.closest('.cmp-timeline-wrap[data-cmp-nav-type]');
          if (!wrap) return;
          e.preventDefault();
          openReportsFromCmpTimeline(
            Number(col.dataset.cmpYear),
            Number(col.dataset.cmpMonth),
            wrap.dataset.cmpNavType,
            wrap.dataset.cmpNavId
          );
        });
        bodyEl.addEventListener('keydown', (e) => {
          if (e.key !== 'Enter' && e.key !== ' ') return;
          const col = e.target.closest('.cmp-timeline-col--link');
          if (!col) return;
          const wrap = col.closest('.cmp-timeline-wrap[data-cmp-nav-type]');
          if (!wrap) return;
          e.preventDefault();
          openReportsFromCmpTimeline(
            Number(col.dataset.cmpYear),
            Number(col.dataset.cmpMonth),
            wrap.dataset.cmpNavType,
            wrap.dataset.cmpNavId
          );
        });
      }

      function openReportsFromCmpTimeline(year, month0, itemType, itemId) {
        const y = Number(year);
        const m = Number(month0);
        if (!Number.isFinite(y) || !Number.isFinite(m) || m < 0 || m > 11 || !itemType || !itemId) return;

        state.rpDashPreset = null;
        clearFpStateObject(fpState);
        fpState.scope = 'branch';

        if (itemType === 'employee' || itemType === 'supervisor') {
          fpState.employees = [itemId];
        } else if (itemType === 'branch') {
          fpState.branches = [itemId];
        } else if (itemType === 'region') {
          fpState.regions = [itemId];
        }

        const searchInput = document.getElementById('rp-search');
        if (searchInput) searchInput.value = '';

        cmpApplyReportsMonthFilter(y, m);
        populateFpSelects();
        dashSyncFpChipsFromState();
        updateActiveFiltersTags();

        closeModal('cmpDetailModal');
        dashGoTab('reports');
        filterReports({ instant: true });

        const monthName = KSA_AR_MONTHS[m];
        let scopeLabel = '╪º┘ä╪╣┘å╪╡╪▒';
        if (itemType === 'employee' || itemType === 'supervisor') {
          scopeLabel = state.users.find(u => u.id === itemId)?.name || '╪º┘ä┘à┘ê╪╕┘ü';
        } else if (itemType === 'branch') {
          scopeLabel = state.branches.find(b => b.id === itemId)?.name || '╪º┘ä┘ü╪▒╪╣';
        } else if (itemType === 'region') {
          scopeLabel = state.regions.find(r => r.id === itemId)?.name || '╪º┘ä┘à┘å╪╖┘é╪⌐';
        }
        showToast(`╪╣╪▒╪╢ ╪¬┘é╪º╪▒┘è╪▒ ${scopeLabel} ΓÇö ${monthName} ${y}`, 'info');
      }

      function buildTimelineHTML(viols, item) {
        const months = ksaMonthSlots(6).map(m => ({ ...m, count: 0 }));

        viols.forEach(v => {
          if (violationExcludedFromDeduction(v)) return;
          const iso = dashViolationIsoDate(v);
          if (!iso) return;
          const mo = months.find(m => ksaIsoInMonth(iso, m.year, m.month));
          if (!mo) return;
          mo.count++;
        });

        const ordered = [...months].reverse();
        const maxCount = Math.max(1, ...ordered.map(m => m.count));

        const barsHTML = ordered.map((m, idx) => {
          const isCurrent = idx === 0;
          const barTone = isCurrent ? 'cmp-timeline-bar--current' : 'cmp-timeline-bar--muted';
          const h = m.count
            ? Math.max(14, Math.round((m.count / maxCount) * 52))
            : (isCurrent ? 12 : 10);
          const countHtml = m.count ? `<span class="cmp-timeline-count">${m.count}</span>` : '<span class="cmp-timeline-count"></span>';
          const navAttrs = item
            ? ` class="cmp-timeline-col cmp-timeline-col--link" role="button" tabindex="0" data-cmp-year="${m.year}" data-cmp-month="${m.month}" title="╪╣╪▒╪╢ ╪¬┘é╪º╪▒┘è╪▒ ${Sec.escapeHTML(m.monthName)} ${Sec.escapeHTML(m.yearLabel)}"`
            : ` class="cmp-timeline-col" title="${m.count ? m.count + ' ┘à╪«╪º┘ä┘ü╪⌐' : '┘ä╪º ┘å╪┤╪º╪╖'}"`;
          return `
            <div${navAttrs}>
              ${countHtml}
              <div class="cmp-timeline-bar ${barTone}" style="height:${h}px"></div>
              <div class="cmp-timeline-axis">
                <span class="cmp-timeline-month">${Sec.escapeHTML(m.monthName)}</span>
                <span class="cmp-timeline-axis-line" aria-hidden="true"></span>
                <span class="cmp-timeline-year">${Sec.escapeHTML(m.yearLabel)}</span>
              </div>
            </div>`;
        }).join('');

        const wrapAttrs = item
          ? ` data-cmp-nav-type="${Sec.escapeHTML(item.type)}" data-cmp-nav-id="${Sec.escapeHTML(item.id)}"`
          : '';
        return `<div class="cmp-timeline-wrap"${wrapAttrs}><div class="cmp-timeline">${barsHTML}</div></div>`;
      }

      window.openCmpItemDetail = openCmpItemDetail;
      window.openReportsFromCmpTimeline = openReportsFromCmpTimeline;

      // ΓöÇΓöÇΓöÇ Excel Export (┘à╪ñ╪┤╪▒╪º╪¬ ╪º┘ä╪º┘à╪¬╪½╪º┘ä) ΓöÇΓöÇΓöÇ

      function cmpExcelLevelLabel(score) {
        const s = Number(score);
        if (s >= 90) return '┘à┘à╪¬╪º╪▓';
        if (s >= 75) return '╪¼┘è╪»';
        if (s >= 50) return '╪¬╪¡╪░┘è╪▒';
        return '┘à╪¬╪╣╪½╪▒';
      }

      function cmpExcelScoreBar(score, maxLen = 18) {
        const s = Math.max(0, Math.min(100, Number(score) || 0));
        const filled = Math.round((s / 100) * maxLen);
        return 'Γûê'.repeat(filled) + 'Γûæ'.repeat(Math.max(0, maxLen - filled));
      }

      function cmpExcelScoreFill(score) {
        const s = Number(score);
        if (s >= 90) return 'DCFCE7';
        if (s >= 75) return 'DBEAFE';
        if (s >= 50) return 'FEF3C7';
        return 'FEE2E2';
      }

      function cmpExportPeriodLabel() {
        const fromDate = document.getElementById('cmp-from')?.value || '';
        const toDate = document.getElementById('cmp-to')?.value || '';
        if (fromDate && toDate) return `${fromDate} ΓåÆ ${toDate}`;
        if (toDate) return `╪¡╪¬┘ë ${toDate}`;
        if (fromDate) return `┘à┘å ${fromDate}`;
        return '┘â┘ä ╪º┘ä┘ü╪¬╪▒╪º╪¬';
      }

      function cmpExportScopeLists() {
        const violations = getViolationsForScoring();
        let regs = [...state.regions];
        let brs = [...state.branches];
        let emps = state.users.filter(isBranchStaffMember);

        if (cmpShouldScopeToSupervisor()) {
          const supId = state.currentUser.id;
          regs = regs.filter(r => r.supervisor_id === supId);
          const branchIds = state.currentUser.supervisedBranches || [];
          brs = brs.filter(b => branchIds.includes(b.id));
          emps = emps.filter(e => branchIds.includes(e.branch_id));
        } else if (!canSeeAllCompliance() && state.currentUser?.role === 'branch_manager') {
          const bid = state.currentUser.branch_id;
          if (bid) {
            brs = brs.filter(b => b.id === bid);
            regs = regs.filter(r => brs.some(b => b.region_id === r.id));
            emps = emps.filter(e => e.branch_id === bid || e.id === state.currentUser.id);
          } else {
            emps = emps.filter(e => e.id === state.currentUser.id);
            brs = [];
            regs = [];
          }
        }

        if (cmpfState.region) {
          regs = regs.filter(r => r.id === cmpfState.region);
          brs = brs.filter(b => b.region_id === cmpfState.region);
          const bids = new Set(brs.map(b => b.id));
          emps = emps.filter(e => bids.has(e.branch_id));
        }
        if (cmpfState.branch) {
          brs = brs.filter(b => b.id === cmpfState.branch);
          const br = state.branches.find(b => b.id === cmpfState.branch);
          regs = br ? regs.filter(r => r.id === br.region_id) : [];
          emps = emps.filter(e => e.branch_id === cmpfState.branch);
        }
        if (cmpfState.employee) {
          emps = emps.filter(e => e.id === cmpfState.employee);
        }

        return { violations, regs, brs, emps };
      }

      function buildCmpExportTables() {
        const { violations, regs, brs, emps } = cmpExportScopeLists();

        const regionHeaders = [
          '╪º┘ä╪¬╪▒╪¬┘è╪¿', '╪º┘ä┘à┘å╪╖┘é╪⌐', '╪º┘ä┘à╪»┘è┘å╪⌐', '╪º┘ä╪»╪▒╪¼╪⌐', '╪º┘ä┘à╪│╪¬┘ê┘ë', '╪º┘ä╪▒╪│┘à', '╪╣╪»╪» ╪º┘ä┘ü╪▒┘ê╪╣', '╪╣╪»╪» ╪º┘ä┘à┘ê╪╕┘ü┘è┘å',
          '┘à╪¬┘ê╪│╪╖ ┘à╪▒╪¼┘æ╪¡', '╪º┘ä╪º╪¬╪│╪º┘é %', '╪º┘ä╪º╪¬╪¼╪º┘ç', '┘ü╪▒┘ê╪╣ ╪┤╪º╪░╪⌐', '╪╣╪»╪» ╪º┘ä┘à╪«╪º┘ä┘ü╪º╪¬', '╪º┘ä┘à╪┤╪▒┘ü'
        ];
        const regionRows = regs.map((r, i) => {
          const stat = calcRegionStability(r.id, violations);
          const sup = state.users.find(u => u.id === r.supervisor_id);
          const branchIds = state.branches.filter(b => b.region_id === r.id).map(b => b.id);
          const totalViols = violations.filter(v => branchIds.includes(v.branch_id) && !violationExcludedFromDeduction(v)).length;
          return [
            i + 1, r.name, cmpRegionCityLabel(r.id), stat.score, cmpExcelLevelLabel(stat.score),
            cmpExcelScoreBar(stat.score), stat.branchesCount, stat.totalEmps, stat.weightedAvg,
            stat.consistency, stat.trend === 'up' ? '╪¬╪¡╪│┘æ┘å' : stat.trend === 'down' ? '╪¬╪▒╪º╪¼╪╣' : '┘à╪│╪¬┘é╪▒',
            stat.outliers, totalViols, sup?.name || '-'
          ];
        });

        const branchHeaders = [
          '╪º┘ä╪¬╪▒╪¬┘è╪¿', '╪º┘ä┘ü╪▒╪╣', '╪º┘ä┘à┘å╪╖┘é╪⌐', '╪º┘ä┘à╪»┘è┘å╪⌐', '╪º┘ä╪»╪▒╪¼╪⌐', '╪º┘ä┘à╪│╪¬┘ê┘ë', '╪º┘ä╪▒╪│┘à', '┘à┘ê╪╕┘ü┘ê┘å ┘à┘å╪╢╪¿╪╖┘ê┘å',
          '╪Ñ╪¼┘à╪º┘ä┘è ╪º┘ä┘à┘ê╪╕┘ü┘è┘å', '┘à╪¬┘ê╪│╪╖ ╪º┘ä╪»╪▒╪¼╪⌐', '┘å╪│╪¿╪⌐ ╪º┘ä╪ú┘à╪º┘å %', '╪¡╪▒┘è╪⌐ ╪¡╪▒╪¼╪⌐ %', '┘à╪«╪º┘ä┘ü╪º╪¬ ╪¡╪▒╪¼╪⌐', '╪┤╪º╪░', '╪╣╪»╪» ╪º┘ä┘à╪«╪º┘ä┘ü╪º╪¬'
        ];
        const branchRows = brs.map((b, i) => {
          const stat = calcBranchSafety(b.id, violations);
          const region = state.regions.find(r => r.id === b.region_id);
          const totalViols = violations.filter(v => v.branch_id === b.id && !violationExcludedFromDeduction(v)).length;
          return [
            i + 1, b.name, region?.name || '-', b.city || '-', stat.score, cmpExcelLevelLabel(stat.score),
            cmpExcelScoreBar(stat.score), stat.safeEmps, stat.totalEmps, stat.avgScore, stat.safetyRate,
            stat.criticalFreedom, stat.criticalCount, stat.hasOutlier ? '┘å╪╣┘à' : '┘ä╪º', totalViols
          ];
        });

        const empHeaders = [
          '╪º┘ä╪¬╪▒╪¬┘è╪¿', '╪º┘ä┘à┘ê╪╕┘ü', '╪º┘ä╪▒┘é┘à ╪º┘ä┘ê╪╕┘è┘ü┘è', '╪º┘ä┘ü╪▒╪╣', '╪º┘ä┘à┘å╪╖┘é╪⌐', '╪º┘ä╪»╪▒╪¼╪⌐', '╪º┘ä┘à╪│╪¬┘ê┘ë', '╪º┘ä╪▒╪│┘à',
          '╪╣╪»╪» ╪º┘ä┘à╪«╪º┘ä┘ü╪º╪¬', '┘å┘é╪º╪╖ ┘à╪«╪╡┘ê┘à╪⌐', '╪¿┘ê┘å╪╡ ╪º┘ä╪¬╪▓╪º┘à', '┘à┘å╪«┘ü╪╢', '┘à╪¬┘ê╪│╪╖', '╪╣╪º┘ä┘è', '┘è╪¬╪╖┘ä╪¿ ╪Ñ╪¼╪▒╪º╪í'
        ];
        const empRows = emps.map((e, i) => {
          const stat = calcEmpScore(e.id, violations);
          const branch = state.branches.find(b => b.id === e.branch_id);
          const region = branch ? state.regions.find(r => r.id === branch.region_id) : null;
          const sev = stat.severityBreakdown || {};
          return [
            i + 1, e.name, padEmpNum(e.employee_number), branch?.name || '-', region?.name || '-',
            stat.score, cmpExcelLevelLabel(stat.score), cmpExcelScoreBar(stat.score),
            stat.violationsCount, stat.deducted, stat.streakBonus,
            sev['┘à┘å╪«┘ü╪╢'] || 0, sev['┘à╪¬┘ê╪│╪╖'] || 0, sev['╪╣╪º┘ä┘è'] || 0,
            stat.actionRequired ? '┘å╪╣┘à' : '┘ä╪º'
          ];
        });

        const violHeaders = [
          '╪▒┘é┘à ╪º┘ä╪¬╪░┘â╪▒╪⌐', '╪º┘ä╪¬╪º╪▒┘è╪«', '╪º┘ä┘à┘ê╪╕┘ü', '╪º┘ä╪▒┘é┘à ╪º┘ä┘ê╪╕┘è┘ü┘è', '╪º┘ä┘ü╪▒╪╣', '╪º┘ä┘à┘å╪╖┘é╪⌐', '┘å┘ê╪╣ ╪º┘ä┘à╪«╪º┘ä┘ü╪⌐',
          '╪º┘ä╪¡╪»╪⌐', '╪º┘ä┘ê╪▓┘å', '╪º┘ä╪¡╪º┘ä╪⌐', '╪º┘ä┘ê╪╡┘ü'
        ];
        const violRows = violations
          .filter(v => !violationExcludedFromDeduction(v))
          .map(v => {
            const emp = state.users.find(u => u.id === v.employee_id);
            const branch = state.branches.find(b => b.id === v.branch_id);
            const region = branch ? state.regions.find(r => r.id === branch.region_id) : null;
            const type = state.violationTypes.find(x => x.name === v.violation_type);
            return [
              shortTicketNum(v.ticket_number),
              (v.violation_date || v.created_at || '').toString().slice(0, 10),
              emp?.name || '-',
              emp ? padEmpNum(emp.employee_number) : '-',
              branch?.name || '-',
              region?.name || '-',
              v.violation_type || '-',
              type?.severity || '-',
              type?.weight ?? '-',
              v.status_text || STATE_LABELS[v.state] || v.state || '-',
              String(v.description || '').replace(/\r?\n+/g, ' ').trim()
            ];
          });

        return { regionHeaders, regionRows, branchHeaders, branchRows, empHeaders, empRows, violHeaders, violRows, violations, regs, brs, emps };
      }

      function buildCmpDashboardAoA(tables) {
        const dash = buildCmpExportDashboard(tables);
        const { avg, total, buckets, top5, bottom5, rankedBranches } = dash;

        const aoa = [
          ['╪¬┘é╪▒┘è╪▒ ┘à╪ñ╪┤╪▒╪º╪¬ ╪º┘ä╪º┘à╪¬╪½╪º┘ä ΓÇö ┘ä┘ê╪¡╪⌐ ╪º┘ä┘é┘è╪º╪»╪⌐'],
          [],
          ['╪¬╪º╪▒┘è╪« ╪º┘ä╪¬╪╡╪»┘è╪▒', new Date().toLocaleString('ar-SA', { timeZone: 'Asia/Riyadh' })],
          ['┘ü╪¬╪▒╪⌐ ╪º┘ä╪¬┘é┘è┘è┘à', cmpExportPeriodLabel()],
          ['┘å╪╖╪º┘é ╪º┘ä╪¬┘é╪▒┘è╪▒', document.getElementById('cmp-filter-label')?.textContent?.trim() || '╪º┘ä┘â┘ä'],
          ['╪╣╪»╪» ╪º┘ä┘à┘å╪º╪╖┘é', tables.regs.length, '╪╣╪»╪» ╪º┘ä┘ü╪▒┘ê╪╣', tables.brs.length, '╪╣╪»╪» ╪º┘ä┘à┘ê╪╕┘ü┘è┘å', tables.emps.length],
          [],
          ['┘à┘ä╪«╪╡ ╪º┘ä┘à╪ñ╪┤╪▒╪º╪¬'],
          ['┘à╪¬┘ê╪│╪╖ ╪╣╪º┘à', avg, '╪Ñ╪¼┘à╪º┘ä┘è ╪º┘ä┘â┘è╪º┘å╪º╪¬', total, '┘à╪«╪º┘ä┘ü╪º╪¬ ┘à╪¡╪¬╪│╪¿╪⌐', tables.violRows.length],
          [],
          ['╪¬┘ê╪▓┘è╪╣ ╪º┘ä┘à╪│╪¬┘ê┘è╪º╪¬', '╪º┘ä╪╣╪»╪»', '╪º┘ä┘å╪│╪¿╪⌐ %', '╪º┘ä╪▒╪│┘à ╪º┘ä╪¿┘è╪º┘å┘è']
        ];
        buckets.forEach(b => {
          aoa.push([b.label, b.count, b.pct, cmpExcelScoreBar(b.pct, 14)]);
        });
        aoa.push([], ['╪ú╪╣┘ä┘ë 5 ┘ü╪▒┘ê╪╣'], ['╪º┘ä┘ü╪▒╪╣', '╪º┘ä┘à┘å╪╖┘é╪⌐', '╪º┘ä╪»╪▒╪¼╪⌐', '╪º┘ä╪▒╪│┘à']);
        top5.forEach(r => aoa.push([r.name, r.region, r.score, cmpExcelScoreBar(r.score)]));
        aoa.push([], ['╪ú╪»┘å┘ë 5 ┘ü╪▒┘ê╪╣'], ['╪º┘ä┘ü╪▒╪╣', '╪º┘ä┘à┘å╪╖┘é╪⌐', '╪º┘ä╪»╪▒╪¼╪⌐', '╪º┘ä╪▒╪│┘à']);
        bottom5.forEach(r => aoa.push([r.name, r.region, r.score, cmpExcelScoreBar(r.score)]));
        aoa.push(
          [],
          ['╪¿┘è╪º┘å╪º╪¬ ╪º┘ä╪▒╪│┘à ╪º┘ä╪¿┘è╪º┘å┘è (┘ä╪Ñ╪»╪▒╪º╪¼ ┘à╪«╪╖╪╖ ┘ü┘è Excel)'],
          ['╪º┘ä┘à╪│╪¬┘ê┘ë', '╪º┘ä╪╣╪»╪»'],
          ...buckets.map(b => [b.label, b.count]),
          [],
          ['╪¿┘è╪º┘å╪º╪¬ ┘à╪«╪╖╪╖ ╪º┘ä┘ü╪▒┘ê╪╣ (╪ú╪╣┘ä┘ë 10)'],
          ['╪º┘ä┘ü╪▒╪╣', '╪º┘ä╪»╪▒╪¼╪⌐'],
          ...rankedBranches.slice(0, 10).map(r => [r.name, r.score])
        );
        return { aoa, avg, total, buckets };
      }

      function createCmpExcelTableSheet(headers, rows, scoreColIdx) {
        const normRows = rows.map(row => row.map(v => String(v ?? '').replace(/\r?\n+/g, ' ').trim()));
        const sheetData = [headers, ...normRows];
        const ws = XLSX.utils.aoa_to_sheet(sheetData);
        const thinBorder = {
          top: { style: 'thin', color: { rgb: 'CBD5E1' } },
          bottom: { style: 'thin', color: { rgb: 'CBD5E1' } },
          left: { style: 'thin', color: { rgb: 'CBD5E1' } },
          right: { style: 'thin', color: { rgb: 'CBD5E1' } }
        };
        const alignCenter = { horizontal: 'center', vertical: 'center', wrapText: true, readingOrder: 2 };
        const headerStyle = {
          fill: { patternType: 'solid', fgColor: { rgb: 'E8EBF1' } },
          font: { bold: true, color: { rgb: '0F1224' }, sz: 11 },
          alignment: alignCenter,
          border: thinBorder
        };
        const bodyStyle = {
          font: { color: { rgb: '0F1224' }, sz: 11 },
          alignment: alignCenter,
          border: thinBorder
        };
        const rowHeights = [{ hpt: 28 }];
        for (let r = 0; r < sheetData.length; r++) {
          for (let c = 0; c < headers.length; c++) {
            const addr = XLSX.utils.encode_cell({ r, c });
            if (!ws[addr]) continue;
            if (r === 0) {
              ws[addr].s = headerStyle;
              continue;
            }
            if (scoreColIdx === c) {
              const num = parseFloat(normRows[r - 1][c]);
              ws[addr].s = {
                ...bodyStyle,
                fill: { patternType: 'solid', fgColor: { rgb: cmpExcelScoreFill(num) } },
                font: { bold: true, color: { rgb: '0F1224' }, sz: 11 }
              };
            } else {
              ws[addr].s = bodyStyle;
            }
          }
          if (r > 0) rowHeights.push({ hpt: 22 });
        }
        ws['!cols'] = buildReportExcelColWidths(headers, normRows);
        ws['!rows'] = rowHeights;
        return ws;
      }

      function applyCmpDashboardSheet(ws, aoa) {
        const thinBorder = {
          top: { style: 'thin', color: { rgb: 'CBD5E1' } },
          bottom: { style: 'thin', color: { rgb: 'CBD5E1' } },
          left: { style: 'thin', color: { rgb: 'CBD5E1' } },
          right: { style: 'thin', color: { rgb: 'CBD5E1' } }
        };
        const titleStyle = {
          font: { bold: true, sz: 16, color: { rgb: '0F1224' } },
          alignment: { horizontal: 'center', vertical: 'center', readingOrder: 2 }
        };
        const sectionStyle = {
          font: { bold: true, sz: 12, color: { rgb: '1E3A5F' } },
          fill: { patternType: 'solid', fgColor: { rgb: 'E8EBF1' } },
          alignment: { horizontal: 'right', vertical: 'center', readingOrder: 2 },
          border: thinBorder
        };
        const labelStyle = {
          font: { bold: true, color: { rgb: '475569' }, sz: 11 },
          alignment: { horizontal: 'right', vertical: 'center', readingOrder: 2 }
        };
        const bodyStyle = {
          font: { color: { rgb: '0F1224' }, sz: 11 },
          alignment: { horizontal: 'center', vertical: 'center', readingOrder: 2 },
          border: thinBorder
        };
        aoa.forEach((row, r) => {
          row.forEach((val, c) => {
            const addr = XLSX.utils.encode_cell({ r, c });
            if (!ws[addr]) return;
            if (r === 0 && c === 0) ws[addr].s = titleStyle;
            else if (String(val).startsWith('┘à┘ä╪«╪╡') || String(val).startsWith('╪¬┘ê╪▓┘è╪╣') || String(val).includes('╪ú╪╣┘ä┘ë') || String(val).includes('╪ú╪»┘å┘ë') || String(val).includes('╪¿┘è╪º┘å╪º╪¬')) {
              ws[addr].s = sectionStyle;
            } else if (c === 0 && ['╪¬╪º╪▒┘è╪« ╪º┘ä╪¬╪╡╪»┘è╪▒', '┘ü╪¬╪▒╪⌐ ╪º┘ä╪¬┘é┘è┘è┘à', '┘å╪╖╪º┘é ╪º┘ä╪¬┘é╪▒┘è╪▒', '┘à╪¬┘ê╪│╪╖ ╪╣╪º┘à'].includes(String(val))) {
              ws[addr].s = labelStyle;
            } else if (r > 0 && typeof val === 'number' && c === 2 && row[0] && String(row[0]).includes('(')) {
              ws[addr].s = bodyStyle;
            } else if (typeof val === 'number' && (c === 1 || c === 3) && aoa[r - 1]?.[0] === '╪º┘ä┘ü╪▒╪╣') {
              ws[addr].s = {
                ...bodyStyle,
                fill: { patternType: 'solid', fgColor: { rgb: cmpExcelScoreFill(val) } },
                font: { bold: true, color: { rgb: '0F1224' }, sz: 11 }
              };
            } else {
              ws[addr].s = bodyStyle;
            }
          });
        });
        ws['!merges'] = [{ s: { r: 0, c: 0 }, e: { r: 0, c: 5 } }];
        ws['!cols'] = [{ wch: 28 }, { wch: 14 }, { wch: 12 }, { wch: 22 }, { wch: 14 }, { wch: 14 }];
      }

      async function exportComplianceExcel() {
        if (!canExportCompliance()) { showToast('┘ä╪º ╪¬┘à┘ä┘â ╪╡┘ä╪º╪¡┘è╪⌐ ╪¬╪╡╪»┘è╪▒ ┘à╪ñ╪┤╪▒╪º╪¬ ╪º┘ä╪º┘à╪¬╪½╪º┘ä.', 'warning'); return; }
        const tables = buildCmpExportTables();
        if (!tables.regs.length && !tables.brs.length && !tables.emps.length) {
          return showToast('┘ä╪º ╪¬┘ê╪¼╪» ╪¿┘è╪º┘å╪º╪¬ ┘ä┘ä╪¬╪╡╪»┘è╪▒', 'warning');
        }

        try {
          const XLSX = await ensureXlsxLib();
          const wb = XLSX.utils.book_new();

          const dash = buildCmpDashboardAoA(tables);
          const wsDash = XLSX.utils.aoa_to_sheet(dash.aoa);
          applyCmpDashboardSheet(wsDash, dash.aoa);
          XLSX.utils.book_append_sheet(wb, wsDash, '┘ä┘ê╪¡╪⌐ ╪º┘ä┘é┘è╪º╪»╪⌐');

          XLSX.utils.book_append_sheet(wb, createCmpExcelTableSheet(tables.regionHeaders, tables.regionRows, 3), '╪º┘ä┘à┘å╪º╪╖┘é');
          XLSX.utils.book_append_sheet(wb, createCmpExcelTableSheet(tables.branchHeaders, tables.branchRows, 4), '╪º┘ä┘ü╪▒┘ê╪╣');
          XLSX.utils.book_append_sheet(wb, createCmpExcelTableSheet(tables.empHeaders, tables.empRows, 5), '╪º┘ä┘à┘ê╪╕┘ü┘ê┘å');

          if (tables.violRows.length) {
            XLSX.utils.book_append_sheet(wb, createCmpExcelTableSheet(tables.violHeaders, tables.violRows, -1), '╪º┘ä┘à╪«╪º┘ä┘ü╪º╪¬');
          }

          const chartAoa = [
            ['╪¿┘è╪º┘å╪º╪¬ ╪º┘ä╪▒╪│┘ê┘à ╪º┘ä╪¿┘è╪º┘å┘è╪⌐'],
            [],
            ['╪¬┘ê╪▓┘è╪╣ ╪º┘ä┘à╪│╪¬┘ê┘è╪º╪¬'],
            ['╪º┘ä┘à╪│╪¬┘ê┘ë', '╪º┘ä╪╣╪»╪»'],
            ...dash.buckets.map(b => [b.label, b.count]),
            [],
            ['╪»╪▒╪¼╪º╪¬ ╪º┘ä┘ü╪▒┘ê╪╣'],
            ['╪º┘ä┘ü╪▒╪╣', '╪º┘ä╪»╪▒╪¼╪⌐', '╪º┘ä╪▒╪│┘à'],
            ...tables.brs.map(b => {
              const s = calcBranchSafety(b.id, tables.violations).score;
              return [b.name, s, cmpExcelScoreBar(s)];
            })
          ];
          const wsChart = XLSX.utils.aoa_to_sheet(chartAoa);
          applyCmpDashboardSheet(wsChart, chartAoa);
          XLSX.utils.book_append_sheet(wb, wsChart, '╪º┘ä╪▒╪│┘ê┘à ╪º┘ä╪¿┘è╪º┘å┘è╪⌐');

          XLSX.writeFile(wb, `compliance-${ksaCsvDateStamp()}.xlsx`, { cellStyles: true });
          showToast('╪¬┘à ╪¬╪╡╪»┘è╪▒ Excel Γ£ô', 'success');
        } catch (err) {
          if (isMirsadDebugLog()) console.warn('[compliance export]', err);
          showToast('╪¬╪╣╪░┘æ╪▒ ╪¬╪╡╪»┘è╪▒ Excel ΓÇö ╪¬╪¡┘é┘é ┘à┘å ╪º┘ä╪º╪¬╪╡╪º┘ä', 'error');
        }
      }

