      function filterReports(opts) {
        if (isAppDataPending()) {
          renderReportsLoadingState();
          return;
        }

        if (typeof isReportsAtharUi === 'function' && isReportsAtharUi()) {
          try {
            renderReportsRedesign();
          } catch (e) {
            console.warn('[rdReports]', e);
            const host = document.getElementById('rdReports');
            if (host) {
              host.hidden = false;
              host.innerHTML = '<div class="rd-rp-metric"><div class="rd-rp-metric__label">╪¬╪╣╪░╪▒ ╪¬╪¡┘à┘è┘ä ╪º┘ä╪¬┘é╪º╪▒┘è╪▒. ╪¡╪»┘æ╪½ ╪º┘ä╪╡┘ü╪¡╪⌐ ╪ú┘ê ╪ú╪╣╪» ╪º┘ä┘à╪¡╪º┘ê┘ä╪⌐.</div></div>';
            }
          }
          return;
        }
        const rdHost = document.getElementById('rdReports');
        if (rdHost) { rdHost.innerHTML = ''; rdHost.hidden = true; }

        const search = (document.getElementById('rp-search')?.value || '').toLowerCase().trim();
        const fromDate = document.getElementById('rp-from')?.value || '';
        const toDate = document.getElementById('rp-to')?.value || '';

        if (search) state.rpDashPreset = null;

        const visible = getReportsFilteredViolations();

        const approved = visible.filter(v => v.state === 'closed' && (v.status_text || '').includes('┘à╪╣╪¬┘à╪»')).length;
        const rejected = visible.filter(v => v.state === 'closed' && (v.status_text || '').includes('┘à┘ä╪║')).length;
        const pending = visible.filter(v => isTicketWorkflowOpen(v)).length;

        updateReportStatsAnimated({
          total: visible.length,
          approved,
          rejected,
          pending
        });

        renderReportCharts(visible, fromDate, toDate);

        // ╪╣╪»╪º╪» ╪º┘ä┘å╪¬╪º╪ª╪¼ + ╪º┘ä┘ü╪¬╪▒╪⌐ (╪º┘ä╪▒┘é┘à ┘è┘Å╪¡╪»┘æ┘Ä╪½ ╪╢┘à┘å updateReportStatsAnimated)

        const periodEl = document.getElementById('rp-period');
        if (periodEl) {
          if (fromDate || toDate) {
            const dateLbl = document.getElementById('rp-date-label')?.textContent || '';
            if (dateLbl && dateLbl !== '╪º╪«╪¬╪▒ ╪º┘ä┘ü╪¬╪▒╪⌐') {
              periodEl.textContent = `┬╖ ${dateLbl}`;
            } else {
              try {
                const parseIso = iso => {
                  const [y, m, d] = iso.split('-').map(Number);
                  return new Date(y, m - 1, d);
                };
                const f = fromDate ? parseIso(fromDate) : null;
                const t = toDate ? parseIso(toDate) : null;
                periodEl.textContent = f && t ? `┬╖ ${dpFormatRangeLabel(f, t)}` : `┬╖ ${fromDate || '...'} ΓÇö ${toDate || '╪º┘ä╪ó┘å'}`;
              } catch (_) {
                periodEl.textContent = `┬╖ ${fromDate || '...'} ΓÇö ${toDate || '╪º┘ä╪ó┘å'}`;
              }
            }
            periodEl.style.display = '';
          } else {
            periodEl.textContent = '';
            periodEl.style.display = 'none';
          }
        }

        rpRenderReportListAnimated(visible, opts);
        rpRefreshDatePickerIfOpen();
      }

