      function getBroadcastTargetFromUI() {
        const mode = document.getElementById('bc-target-mode')?.value || 'all';
        const target = { mode };
        if (mode === 'roles') {
          bcPickEnsure('roles');
          target.roles = Array.from(state._bcSelectedRoleIds);
        } else if (mode === 'branches') {
          bcPickEnsure('branches');
          target.branchIds = Array.from(state._bcSelectedBranchIds);
        } else if (mode === 'users') {
          bcUserPickEnsureState();
          target.userIds = Array.from(state._bcSelectedUserIds);
        }
        return target;
      }

      function bcDdPositionMenu(trigger, menu) {
        if (!trigger || !menu) return;
        const r = trigger.getBoundingClientRect();
        const gap = 6;
        const pad = 8;
        const vw = window.innerWidth;
        const vh = window.innerHeight;
        const w = Math.ceil(r.width);
        menu.style.width = `${w}px`;
        let top = r.bottom + gap;
        let left = r.left;
        if (left < pad) left = pad;
        if (left + w > vw - pad) left = Math.max(pad, vw - w - pad);
        menu.style.left = `${left}px`;
        menu.style.right = 'auto';
        menu.style.top = `${top}px`;
        menu.style.bottom = 'auto';
        menu.style.maxHeight = '';
        const menuH = menu.offsetHeight || 220;
        if (top + menuH > vh - pad) {
          const above = r.top - gap - menuH;
          if (above >= pad) menu.style.top = `${above}px`;
          else {
            menu.style.top = `${Math.max(pad, vh - menuH - pad)}px`;
            menu.style.maxHeight = `${vh - pad * 2}px`;
          }
        }
      }

      function bcDdRepositionOpen() {
        ['kind', 'target'].forEach(field => {
          const menu = document.getElementById(`bc-${field}-menu`);
          const trigger = document.getElementById(`bc-${field}-trigger`);
          if (menu?.classList.contains('open')) bcDdPositionMenu(trigger, menu);
        });
      }

      function bcDdHome(field) {
        const menu = document.getElementById(`bc-${field}-menu`);
        const home = document.getElementById(`bc-${field}-dd`);
        if (menu && home && menu.parentNode !== home) {
          home.appendChild(menu);
          menu.style.top = '';
          menu.style.left = '';
          menu.style.right = '';
          menu.style.bottom = '';
          menu.style.width = '';
          menu.style.maxHeight = '';
        }
      }

      function bcDdClose(field) {
        const menu = document.getElementById(`bc-${field}-menu`);
        const trigger = document.getElementById(`bc-${field}-trigger`);
        menu?.classList.remove('open');
        trigger?.setAttribute('aria-expanded', 'false');
        bcDdHome(field);
      }

      function bcDdCloseAll() {
        bcDdClose('kind');
        bcDdClose('target');
        bcPickCloseAllResults();
        closeBcExpDatePicker();
        closeBcExpTimePicker();
      }

      function bcDdSync(field) {
        const isKind = field === 'kind';
        const sel = document.getElementById(isKind ? 'bc-kind' : 'bc-target-mode');
        const label = document.getElementById(isKind ? 'bc-kind-label' : 'bc-target-label');
        const menu = document.getElementById(isKind ? 'bc-kind-menu' : 'bc-target-menu');
        const val = sel?.value || (isKind ? 'circular' : 'all');
        const opts = isKind ? BC_KIND_DD_OPTIONS : BC_TARGET_DD_OPTIONS;
        if (label) label.textContent = opts.find(o => o.val === val)?.label || val;
        menu?.querySelectorAll('.wf-status-opt').forEach(btn => {
          btn.classList.toggle('is-active', btn.dataset.val === val);
        });
      }

      function bcDdToggle(field, ev) {
        if (ev) ev.stopPropagation();
        const menu = document.getElementById(`bc-${field}-menu`);
        const trigger = document.getElementById(`bc-${field}-trigger`);
        if (!menu || !trigger) return;
        ['kind', 'target'].filter(f => f !== field).forEach(bcDdClose);
        bcPickCloseAllResults();
        const open = !menu.classList.contains('open');
        const home = document.getElementById(`bc-${field}-dd`);
        if (open && home && menu.parentNode !== document.body) document.body.appendChild(menu);
        menu.classList.toggle('open', open);
        trigger.setAttribute('aria-expanded', open ? 'true' : 'false');
        if (open) {
          closeBcExpDatePicker();
          closeBcExpTimePicker();
          bcDdPositionMenu(trigger, menu);
          requestAnimationFrame(() => bcDdPositionMenu(trigger, menu));
        } else {
          bcDdHome(field);
        }
      }

      function bcDdPick(field, val) {
        const isKind = field === 'kind';
        const sel = document.getElementById(isKind ? 'bc-kind' : 'bc-target-mode');
        if (sel) sel.value = val;
        bcDdSync(field);
        bcDdClose(field);
        if (isKind) updateBroadcastPreview();
        else syncBroadcastTargetPanels();
      }

      function bcUserPickEnsureState() {
        if (!state._bcSelectedUserIds) state._bcSelectedUserIds = new Set();
      }

      function bcUserPickGetCandidates(q) {
        const query = String(q || '').trim().toLowerCase();
        return (state.users || [])
          .filter(u => u.is_active !== false)
          .filter(u => {
            if (!query) return true;
            const roleLbl = ROLE_LABELS[normalizeUserRole(u.role)] || u.role || '';
            const hay = `${u.name || ''} ${u.emp_number || u.employee_number || ''} ${u.email || ''} ${roleLbl}`.toLowerCase();
            return hay.includes(query);
          })
          .sort((a, b) => String(a.name || '').localeCompare(String(b.name || ''), 'ar'))
          .slice(0, 14);
      }

