      function estimateBroadcastRecipients(target) {
        const users = (state.users || []).filter(u => u.is_active !== false);
        const mode = target?.mode || 'all';
        const ids = new Set();
        if (mode === 'all') {
          users.forEach(u => ids.add(u.id));
        } else if (mode === 'roles') {
          const roles = new Set((target.roles || []).map(normalizeUserRole));
          users.forEach(u => { if (roles.has(normalizeUserRole(u.role))) ids.add(u.id); });
        } else if (mode === 'branches') {
          const branchSet = new Set((target.branchIds || []).map(String));
          users.forEach(u => { if (u.branch_id && branchSet.has(String(u.branch_id))) ids.add(u.id); });
          (state.regions || []).forEach(reg => {
            const hasBranch = (state.branches || []).some(b => branchSet.has(String(b.id)) && String(b.region_id) === String(reg.id));
            if (hasBranch && reg.supervisor_id) ids.add(reg.supervisor_id);
          });
        } else if (mode === 'users') {
          (target.userIds || []).forEach(id => { if (id) ids.add(String(id)); });
        }
        return ids.size;
      }

