      function syncBroadcastTargetPanels() {
        const mode = document.getElementById('bc-target-mode')?.value || 'all';
        const grid = document.getElementById('bc-form-grid');
        const usersSearch = document.getElementById('bc-panel-users');
        const rolesPanel = document.getElementById('bc-panel-roles');
        const branchesPanel = document.getElementById('bc-panel-branches');
        if (usersSearch) usersSearch.hidden = true;
        if (rolesPanel) rolesPanel.hidden = true;
        if (branchesPanel) branchesPanel.hidden = true;
        grid?.classList.remove('bc-form-grid--users', 'bc-form-grid--roles', 'bc-form-grid--branches');
        if (mode === 'roles') {
          rolesPanel?.removeAttribute('hidden');
          grid?.classList.add('bc-form-grid--roles');
        }
        if (mode === 'branches') {
          branchesPanel?.removeAttribute('hidden');
          grid?.classList.add('bc-form-grid--branches');
        }
        if (mode === 'users') {
          usersSearch?.removeAttribute('hidden');
          grid?.classList.add('bc-form-grid--users');
        }
        updateBroadcastPreview();
      }

