      function updateBroadcastPreview() {
        const wrap = document.getElementById('bc-preview');
        const summary = document.getElementById('bc-preview-summary');
        if (!wrap || !summary) return;
        const target = getBroadcastTargetFromUI();
        const mode = target?.mode || 'all';
        const emptyHint = BC_TARGET_EMPTY_HINTS[mode];
        const hasSelection = mode === 'roles'
          ? (target.roles || []).length > 0
          : mode === 'branches'
            ? (target.branchIds || []).length > 0
            : mode === 'users'
              ? (target.userIds || []).length > 0
              : true;
        bcRenderPreviewChips(target);
        if (emptyHint && !hasSelection) {
          summary.textContent = emptyHint;
          wrap.classList.add('is-hint');
          return;
        }
        const count = estimateBroadcastRecipients(target);
        wrap.classList.toggle('is-hint', !count);
        summary.textContent = count
          ? `╪º┘ä┘à╪│╪¬┘ä┘à┘ê┘å ╪º┘ä┘à╪¬┘ê┘é╪╣┘ê┘å: ${count} ┘à╪│╪¬╪«╪»┘à`
          : '┘ä╪º ┘è┘ê╪¼╪» ┘à╪│╪¬┘ä┘à┘ê┘å ┘à╪╖╪º╪¿┘é┘ê┘å ΓÇö ╪▒╪º╪¼╪╣ ╪º┘ä╪º╪│╪¬┘ç╪»╪º┘ü';
      }

