      /** ╪Ñ╪┤╪╣╪º╪▒ Push ╪¿╪╣╪» ╪Ñ┘å╪┤╪º╪í ┘à╪«╪º┘ä┘ü╪⌐ ΓÇö ┘ä╪º ┘è┘ê┘é┘ü ╪º┘ä┘ê╪º╪¼┘ç╪⌐ */
      function notifyViolationPushAfterInsert(violationRow) {
        if (!violationRow?.id) return;
        const record = {
          id: violationRow.id,
          ticket_number: violationRow.ticket_number,
          violation_type: violationRow.violation_type,
          employee_id: violationRow.employee_id,
          branch_id: violationRow.branch_id,
          state: violationRow.state
        };
        invokeViolationPush({ notify: true, type: 'INSERT', record })
          .then((data) => {
            if (data?.errors?.length && isMirsadDebugLog()) console.warn('[webPush] new violation notify', data);
            return refreshNotificationsFromDb();
          })
          .then(() => { try { renderNotifications(false); } catch (_) { /* noop */ } })
          .catch((e) => {
            if (isMirsadDebugLog()) console.warn('[webPush] new violation notify', e);
          });
      }

      const _violationPushDedup = new Map();

      /** ╪Ñ╪┤╪╣╪º╪▒ Push ╪╣┘å╪» ╪¬┘à╪▒┘è╪▒ ╪º┘ä╪¬╪░┘â╪▒╪⌐ ┘ä┘à╪▒╪¡┘ä╪⌐ ╪¼╪»┘è╪»╪⌐ (┘à╪½┘ä╪º┘ï ╪º┘ä┘à╪»┘è╪▒ ╪╣┘å╪» mgt) */
      function notifyViolationPushAfterStateChange(violationRow, previousState, opts = {}) {
        if (!violationRow?.id || !violationRow?.state) return;
        if (previousState && String(previousState) === String(violationRow.state)) return;

        const dedupeKey = `${violationRow.id}:${previousState || ''}->${violationRow.state}`;
        const now = Date.now();
        const lastSent = _violationPushDedup.get(dedupeKey);
        if (lastSent && now - lastSent < 120000) return;
        _violationPushDedup.set(dedupeKey, now);

        const record = {
          id: violationRow.id,
          ticket_number: violationRow.ticket_number,
          violation_type: violationRow.violation_type,
          employee_id: violationRow.employee_id,
          branch_id: violationRow.branch_id,
          state: violationRow.state,
          auto_forwarded_emp: violationRow.auto_forwarded_emp,
          auto_forwarded_sup: violationRow.auto_forwarded_sup
        };
        invokeViolationPush({
          notifyState: true,
          previousState: previousState || null,
          record,
          isAutoForward: !!opts.autoForward,
          dedupeKey
        })
          .then((data) => {
            if (data?.errors?.length && isMirsadDebugLog()) console.warn('[webPush] state change notify', data);
            return refreshNotificationsFromDb();
          })
          .then(() => { try { renderNotifications(false); } catch (_) { /* noop */ } })
          .catch((e) => {
            if (isMirsadDebugLog()) console.warn('[webPush] state change notify', e);
          });
      }

      async function removePushSubscriptionFromDb(endpoint) {
        if (!endpoint) return;
        await sb.from('push_subscriptions').delete().eq('endpoint', endpoint);
      }

      function clearAtharWebPushSyncMarkers() {
        try {
          localStorage.removeItem(ATHAR_WEB_PUSH_SYNC_KEY);
          localStorage.removeItem(ATHAR_WEB_PUSH_USER_KEY);
        } catch (_) {}
      }

      /** ┘ç┘ä ┘è╪¡╪¬╪º╪¼ ╪º┘ä╪¼┘ç╪º╪▓ ╪Ñ╪╣╪º╪»╪⌐ ╪▒╪¿╪╖ ╪º┘ä╪º╪┤╪¬╪▒╪º┘â ╪¿╪º┘ä┘à╪│╪¬╪«╪»┘à ╪º┘ä╪¡╪º┘ä┘è╪ƒ */
      async function atharWebPushNeedsResync() {
        if (!state.currentUser?.id) return true;
        const userId = String(state.currentUser.id);
        let lastUser = '';
        let storedVapid = '';
        try { lastUser = localStorage.getItem(ATHAR_WEB_PUSH_USER_KEY) || ''; } catch (_) {}
        try { storedVapid = localStorage.getItem(ATHAR_VAPID_STORAGE_KEY) || ''; } catch (_) {}
        if (storedVapid !== ATHAR_VAPID_PUBLIC_KEY) return true;
        if (lastUser && lastUser !== userId) return true;
        try {
          const reg = await navigator.serviceWorker.getRegistration('./');
          const sub = await reg?.pushManager?.getSubscription();
          if (!sub) return true;
          const { data, error } = await sb
            .from('push_subscriptions')
            .select('user_id')
            .eq('endpoint', sub.endpoint)
            .maybeSingle();
          if (error) return true;
          if (!data || String(data.user_id) !== userId) return true;
        } catch (_) { return true; }
        return false;
      }

      function syncWebPushUiLabels() {
        const supported = isWebPushSupported();
        const perm = typeof Notification !== 'undefined' ? Notification.permission : 'default';

        const topbarBtn = document.getElementById('topbarPushToggle');
        const topbarLabel = document.getElementById('topbarPushToggleLabel');
        if (topbarBtn && topbarLabel) {
          if (!supported) {
            topbarBtn.hidden = true;
          } else {
            const on = perm === 'granted';
            topbarBtn.hidden = on;
            if (!on) {
              topbarLabel.textContent = perm === 'denied'
                ? '╪º┘ä╪Ñ╪┤╪╣╪º╪▒╪º╪¬ ┘à┘ê┘é┘ê┘ü╪⌐ ┘à┘å ╪Ñ╪╣╪»╪º╪»╪º╪¬ ╪º┘ä╪¼┘ç╪º╪▓'
                : '╪¬┘ü╪╣┘è┘ä ╪¬┘å╪¿┘è┘ç╪º╪¬ ╪º┘ä╪¼┘ê╪º┘ä';
              topbarBtn.setAttribute('aria-pressed', 'false');
            }
          }
        }

        const profileRow = document.getElementById('profilePagePushRow');
        const profileToggle = document.getElementById('profilePagePushToggle');
        if (profileRow && profileToggle) {
          if (!supported) {
            profileRow.hidden = true;
          } else {
            profileRow.hidden = false;
            const on = perm === 'granted';
            profileToggle.classList.toggle('push-toggle--on', on);
            profileToggle.setAttribute('aria-pressed', on ? 'true' : 'false');
          }
        }
      }

      /** @deprecated use syncWebPushUiLabels */
