      async function refreshPushSubscription(reg, opts = {}) {
        let stored = '';
        try { stored = localStorage.getItem(ATHAR_VAPID_STORAGE_KEY) || ''; } catch (_) {}
        const mustRefresh = !!(
          opts.forceResubscribe
          || stored !== ATHAR_VAPID_PUBLIC_KEY
        );
        if (mustRefresh) {
          const old = await reg.pushManager.getSubscription();
          if (old) {
            try { await removePushSubscriptionFromDb(old.endpoint); } catch (_) {}
            try { await old.unsubscribe(); } catch (_) {}
          }
        }
        let sub = await reg.pushManager.getSubscription();
        if (!sub) {
          sub = await reg.pushManager.subscribe({
            userVisibleOnly: true,
            applicationServerKey: urlBase64ToUint8Array(ATHAR_VAPID_PUBLIC_KEY)
          });
        }
        try { localStorage.setItem(ATHAR_VAPID_STORAGE_KEY, ATHAR_VAPID_PUBLIC_KEY); } catch (_) {}
        return sub;
      }

      async function ensureAtharWebPushSubscribed(opts = {}) {
        if (!isWebPushSupported() || !state.currentUser) return false;
        try {
          let perm = Notification.permission;
          if (perm === 'default' && opts.requestPermission) {
            perm = await Notification.requestPermission();
          }
          if (perm !== 'granted') return false;
          const reg = await getAtharSwRegistration();
          if (!reg?.pushManager) throw new Error('PushManager ╪║┘è╪▒ ┘à╪¬╪º╪¡');
          const sub = await refreshPushSubscription(reg, opts);
          await savePushSubscriptionToDb(sub);
          try {
            localStorage.setItem(ATHAR_WEB_PUSH_SYNC_KEY, String(Date.now()));
            localStorage.setItem(ATHAR_WEB_PUSH_USER_KEY, String(state.currentUser.id));
          } catch (_) {}
          syncWebPushUiLabels();
          if (opts.welcomeNotify) {
            const shown = await showPushWelcomeNotification();
            if (!shown) showToast('╪¬┘à ╪º┘ä╪¬┘ü╪╣┘è┘ä ΓÇö ╪¬╪¡┘é┘é ┘à┘å ╪Ñ╪╣╪»╪º╪»╪º╪¬ ╪º┘ä╪Ñ╪┤╪╣╪º╪▒╪º╪¬ ┘ü┘è ╪º┘ä╪¼┘ê╪º┘ä', 'warning');
            else showToast('╪¬┘à ╪¬┘ü╪╣┘è┘ä ╪º┘ä╪¬┘å╪¿┘è┘ç╪º╪¬ Γ£ô', 'success');
          }
          return true;
        } catch (e) {
          if (isMirsadDebugLog()) console.error('[webPush] subscribe', e);
          throw e;
        }
      }

      async function syncAtharWebPushSubscription(opts = {}) {
        if (!isWebPushSupported() || !state.currentUser || Notification.permission !== 'granted') return false;
        const minIntervalMs = Number(opts.minIntervalMs) || 0;
        const needsResync = !!opts.force || await atharWebPushNeedsResync();
        if (!needsResync && minIntervalMs > 0) {
          let last = 0;
          try { last = Number(localStorage.getItem(ATHAR_WEB_PUSH_SYNC_KEY) || 0); } catch (_) {}
          if (last && Date.now() - last < minIntervalMs) return true;
        }
        return ensureAtharWebPushSubscribed({ silent: true });
      }

      async function disableAtharWebPush(opts = {}) {
        if (!('serviceWorker' in navigator)) return;
        try {
          const reg = await navigator.serviceWorker.getRegistration('./');
          const sub = await reg?.pushManager?.getSubscription();
          if (sub) {
            await removePushSubscriptionFromDb(sub.endpoint);
            if (opts.unsubscribeBrowser) {
              try { await sub.unsubscribe(); } catch (_) {}
            }
          }
        } catch (e) {
          if (!opts.silent && isMirsadDebugLog()) console.warn('[webPush] disable', e);
        }
        clearAtharWebPushSyncMarkers();
        syncWebPushUiLabels();
      }

      /** ┘à╪▓╪º┘à┘å╪⌐ Push ╪╣┘å╪» ┘ü╪¬╪¡ ╪º┘ä╪¬╪╖╪¿┘è┘é ΓÇö ┘è╪¡╪»┘æ╪½ ╪º╪┤╪¬╪▒╪º┘â ╪º┘ä╪¼┘ç╪º╪▓ ┘ü┘è ┘é╪º╪╣╪»╪⌐ ╪º┘ä╪¿┘è╪º┘å╪º╪¬ */
      async function bootAtharWebPushOnAppOpen() {
        syncWebPushUiLabels();
        if (!state.currentUser || !isWebPushSupported()) return;

        const perm = Notification.permission;
        if (perm === 'granted') {
          await syncAtharWebPushSubscription({ minIntervalMs: ATHAR_WEB_PUSH_OPEN_SYNC_MS });
          return;
        }
        if (perm === 'denied') return;

        let lastPrompt = 0;
        try { lastPrompt = Number(localStorage.getItem('athar_web_push_prompt_last') || 0); } catch (_) {}
        const dayMs = 24 * 60 * 60 * 1000;
        if (lastPrompt && Date.now() - lastPrompt < dayMs) return;

        try { localStorage.setItem('athar_web_push_prompt_last', String(Date.now())); } catch (_) {}
        await initAtharWebPush({ promptIfNeeded: true });
      }

      function webPushTeamLeadRole() {
        const role = normalizeUserRole(state.currentUser?.role);
        return role === 'branch_manager' || role === 'supervisor';
      }

      async function initAtharWebPush(opts = {}) {
        syncWebPushUiLabels();
        if (!state.currentUser) return;
        if (!isWebPushSupported()) {
          if (opts.promptIfNeeded) maybeShowWebPushUnsupportedNotice();
          return;
        }

        const perm = Notification.permission;
        if (perm === 'granted') {
          try { await syncAtharWebPushSubscription({ minIntervalMs: ATHAR_WEB_PUSH_OPEN_SYNC_MS }); }
          catch (e) { if (isMirsadDebugLog()) console.warn('[webPush] background sync', e); }
          return;
        }
        if (!opts.promptIfNeeded) return;
        if (perm === 'denied') {
          showToast('╪º┘ä╪Ñ╪┤╪╣╪º╪▒╪º╪¬ ┘à┘ê┘é┘ê┘ü╪⌐ ┘à┘å ╪Ñ╪╣╪»╪º╪»╪º╪¬ ╪º┘ä╪¼┘ç╪º╪▓ ╪ú┘ê ╪º┘ä┘à╪¬╪╡┘ü╪¡. ┘ü╪╣┘æ┘ä┘ç╪º ┘à┘å ╪º┘ä╪Ñ╪╣╪»╪º╪»╪º╪¬ ╪½┘à ╪º┘ü╪¬╪¡ ╪º┘ä╪¬╪╖╪¿┘è┘é ┘à┘å ╪¼╪»┘è╪».', 'warning');
          return;
        }

        const ok = await confirmDialog(
          '┘å╪▒╪¼┘ê ╪º┘ä╪¬┘â╪▒┘à ╪¿╪¬┘ü╪╣┘è┘ä ╪º┘ä╪Ñ╪┤╪╣╪º╪▒╪º╪¬ ┘ä╪╢┘à╪º┘å ╪¿┘é╪º╪ª┘â┘à ╪╣┘ä┘ë ╪º╪╖┘ä╪º╪╣ ╪»╪º╪ª┘à ╪¿┘â╪º┘ü╪⌐ ╪º┘ä╪¬┘å╪¿┘è┘ç╪º╪¬ ╪º┘ä┘à┘ê╪¼┘ç╪⌐ ┘ä┘â┘à ┘à┘å ╪«┘ä╪º┘ä ╪º┘ä┘å╪╕╪º┘à',
          { type: 'info', title: '╪Ñ╪╣╪»╪º╪»╪º╪¬ ╪º┘ä╪¬┘å╪¿┘è┘ç╪º╪¬', okText: '╪¬┘ü╪╣┘è┘ä', hideCancel: true }
        );
        if (!ok) return;
        try {
          const enabled = await ensureAtharWebPushSubscribed({ requestPermission: true, welcomeNotify: true });
          if (!enabled) showToast('┘è┘Å╪¡╪¬╪º╪¼ ╪Ñ╪░┘å ╪º┘ä╪Ñ╪┤╪╣╪º╪▒╪º╪¬ ┘à┘å ╪Ñ╪╣╪»╪º╪»╪º╪¬ ╪º┘ä╪¼┘ê╪º┘ä ΓÇö ┘ü╪╣┘æ┘ä┘ç╪º ╪½┘à ╪ú╪╣╪» ┘ü╪¬╪¡ ╪º┘ä╪¬╪╖╪¿┘è┘é', 'warning');
        } catch (e) {
          showToast('┘ü╪┤┘ä ╪º┘ä╪¬┘ü╪╣┘è┘ä: ' + formatPushError(e), 'error');
        }
      }

      function scheduleAtharWebPushResync(reason) {
        if (!isWebPushSupported() || !state.currentUser || Notification.permission !== 'granted') return;
        setTimeout(() => {
          syncAtharWebPushSubscription({ minIntervalMs: ATHAR_WEB_PUSH_OPEN_SYNC_MS })
            .catch(e => { if (isMirsadDebugLog()) console.warn('[webPush] resync ' + reason, e); });
        }, 800);
      }

      if (typeof document !== 'undefined') {
        document.addEventListener('visibilitychange', () => {
          if (!document.hidden) scheduleAtharWebPushResync('visible');
        });
      }
      if (typeof window !== 'undefined') {
        window.addEventListener('online', () => scheduleAtharWebPushResync('online'));
      }

      function openSettingsFromUserMenu(event) {
        if (event) {
          event.stopPropagation();
          event.preventDefault();
        }
        if (!hasPermission('tab_settings')) {
          showToast('╪╡┘ä╪º╪¡┘è╪º╪¬ ╪º┘ä┘à┘å╪╡╪⌐ ╪║┘è╪▒ ┘à╪¬╪º╪¡╪⌐ ┘ä╪¡╪│╪º╪¿┘â', 'warning');
          return;
        }
        syncProfilePageShell(false);
        goTab('settings', null);
      }

