      // STAFF BREAKS ΓÇö ╪¿╪▒┘è┘â╪º╪¬ ╪º┘ä┘à┘ê╪╕┘ü┘è┘å (╪╣╪»╪º╪» ╪»╪º╪ª╪▒┘è + ╪¼╪»┘ê┘ä╪⌐ ╪º┘ä┘à╪»╪»)
      const BREAK_OVERTIME_REASON_AFTER_SEC = 5 * 60; // ╪«╪º┘å╪⌐ ╪º┘ä╪│╪¿╪¿ ╪¿╪╣╪» ╪¬╪¼╪º┘ê╪▓ 5 ╪»┘é╪º╪ª┘é
      // ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ

      const STAFF_BREAK_RING_CIRC = 2 * Math.PI * 54; // r=54 like rd-streak

      function canTakeStaffBreak() {
        // ╪º┘ä┘à╪┤╪▒┘ü ┘ê┘à╪»┘è╪▒ ╪º┘ä┘å╪╕╪º┘à ┘è╪┤╪▒┘ü┘ê┘å ┘ü┘é╪╖ ΓÇö ┘ä╪º ┘è╪ú╪«╪░┘ê┘å ╪¿╪▒┘è┘â
        const role = normalizeUserRole(state.currentUser?.role);
        return role === 'employee' || role === 'branch_manager' || role === 'observer';
      }

      function isStaffBreakParticipantUser(u) {
        if (!u || !isActiveUser(u)) return false;
        const role = normalizeUserRole(u.role);
        return role === 'employee' || role === 'branch_manager' || role === 'observer';
      }

      function canManageStaffBreakSchedules() {
        // ┘à╪»╪⌐ ╪º┘ä╪¿╪▒┘è┘â: ┘à╪»┘è╪▒ ╪º┘ä┘å╪╕╪º┘à ┘ü┘é╪╖ (╪¡╪¬┘ë ┘ä┘ê ┘ê┘Å╪¼╪»╪¬ ╪╡┘ä╪º╪¡┘è╪⌐ ┘à╪¡┘ü┘ê╪╕╪⌐ ┘é╪»┘è┘à╪⌐ ┘ä┘ä┘à╪┤╪▒┘ü).
        const role = normalizeUserRole(state.currentUser?.role);
        return role === 'admin';
      }

      function canViewStaffBreakHistory() {
        const role = normalizeUserRole(state.currentUser?.role);
        return role === 'admin' || role === 'manager' || role === 'auditor' || role === 'supervisor' || role === 'branch_manager' || role === 'observer';
      }

      function stopStaffBreakTicker() {
        if (state._staffBreakTicker) {
          clearInterval(state._staffBreakTicker);
          state._staffBreakTicker = null;
        }
      }

      function getReportableActiveBreakSignature() {
        return (state.staffBreaks || [])
          .filter(brk => brk?.status === 'active' && isStaffBreakReportableOvertime(brk))
          .map(brk => brk.id)
          .sort()
          .join(',');
      }

      function ensureStaffBreakTicker() {
        const tab = document.getElementById('tab-breaks');
        const hasActiveMine = !!getMyActiveStaffBreak();
        // Keep ticking while my break is active (any tab) so we can fire expiry notify
        if (!tab?.classList.contains('active') && !hasActiveMine) {
          stopStaffBreakTicker();
          return;
        }
        // Keep the existing 1s interval. Restarting it reset the 12s poll clock
        // and the first tick reloaded every session, overwriting a just-stopped leftover.
        if (state._staffBreakTicker) return;
        state._staffBreakOvertimeFilterSignature = getReportableActiveBreakSignature();
        if (!state._staffBreakSchedulePollAt) {
          state._staffBreakSchedulePollAt = Date.now();
        }
        state._staffBreakTicker = setInterval(() => {
          try {
            // KSA midnight: reload so daily logs / remaining minutes reset
            if (typeof maybeRollStaffBreaksDay === 'function') {
              maybeRollStaffBreaksDay();
            }
            maybeNotifyBreakExpiredLocally();
            // Fallback if realtime schedule events were missed: refresh every 12s
            const now = Date.now();
            const onBreaksTab = !!document.getElementById('tab-breaks')?.classList.contains('active');
            if (onBreaksTab) {
              const signature = getReportableActiveBreakSignature();
              if (signature !== state._staffBreakOvertimeFilterSignature) {
                state._staffBreakOvertimeFilterSignature = signature;
                if (!isStaffBreakActionBusy()) {
                  renderStaffBreaksPage({ soft: true }).catch(() => {});
                }
                return;
              }
            }
            if (!state._staffBreakSchedulePollAt || now - state._staffBreakSchedulePollAt > 12000) {
              state._staffBreakSchedulePollAt = now;
              loadStaffBreaksData().then(() => {
                try {
                  if (onBreaksTab) paintStaffBreakCountdownOnly();
                  maybeNotifyBreakExpiredLocally();
                  if (!getMyActiveStaffBreak() && !onBreaksTab) stopStaffBreakTicker();
                } catch (_) { /* noop */ }
              }).catch(() => { /* noop */ });
            } else if (onBreaksTab) {
              // Keep idle duration badge aligned with latest in-memory schedules
              state._myBreakDurationMins = resolveBreakDurationMinsForUser(state.currentUser);
              paintStaffBreakCountdownOnly();
            } else if (!getMyActiveStaffBreak()) {
              stopStaffBreakTicker();
            }
          } catch (_) { /* noop */ }
        }, 1000);
      }

      function getBreakExpiryNotificationTag(brk) {
        const breakId = String(brk?.id || 'unknown');
        const userId = String(brk?.user_id || state.currentUser?.id || 'unknown');
        return `break_expiry_${breakId}_${userId}`;
      }

      async function showLocalBreakExpiryNotification(brk) {
        const title = brk?.break_type === 'restroom'
          ? '╪º┘å╪¬┘ç╪¬ ┘à╪»╪⌐ ╪¿╪▒┘è┘â ╪»┘ê╪▒╪⌐ ╪º┘ä┘à┘è╪º┘ç'
          : '╪º┘å╪¬┘ç╪¬ ┘à╪»╪⌐ ╪º┘ä╪¿╪▒┘è┘â';
        const body = `${title} ΓÇö ┘è┘Å╪▒╪¼┘ë ╪º┘ä╪╣┘ê╪»╪⌐ ┘ê╪Ñ┘è┘é╪º┘ü ╪º┘ä╪¼┘ä╪│╪⌐ ┘à┘å ╪º┘ä╪¬╪╖╪¿┘è┘é.`;
        const tag = getBreakExpiryNotificationTag(brk);
        try {
          if ('serviceWorker' in navigator && Notification.permission === 'granted') {
            const reg = await navigator.serviceWorker.getRegistration('./')
              || await navigator.serviceWorker.getRegistration();
            if (reg?.showNotification) {
              await reg.showNotification(title, {
                body,
                icon: './icons/athar-pwa-192-v406.png',
                badge: './icons/athar-pwa-192-v406.png',
                tag,
                renotify: false,
                requireInteraction: true,
                dir: 'rtl',
                lang: 'ar',
                data: { url: './index.html?go=breaks' }
              });
              return;
            }
          }
          if ('Notification' in window && Notification.permission === 'granted') {
            new Notification(title, { body, tag, dir: 'rtl', lang: 'ar' });
          }
        } catch (_) { /* noop */ }
      }

      async function cancelScheduledBreakExpiryNotification() {
        try {
          const reg = await navigator.serviceWorker.getRegistration('./')
            || await navigator.serviceWorker.getRegistration();
          if (!reg?.getNotifications) return;
          const list = await reg.getNotifications();
          list
            .filter(n => n.tag === 'break-expiry-scheduled' || n.tag === 'break-expiry-local')
            .forEach((n) => { try { n.close(); } catch (_) { /* noop */ } });
        } catch (_) { /* noop */ }
      }

      /**
       * Web Push ┘à┘å ╪º┘ä╪│┘è╪▒┘ü╪▒ ┘ç┘ê ╪º┘ä┘à╪╡╪»╪▒ ╪º┘ä┘ê╪¡┘è╪» ╪╣┘å╪» ╪Ñ╪║┘ä╪º┘é ╪º┘ä┘à┘å╪╡╪⌐.
       * ┘å╪¡╪░┘ü ╪ú┘è Trigger ┘é╪»┘è┘à ┘â┘è ┘ä╪º ┘è╪╡┘ä ┘à╪╣ ╪Ñ╪┤╪╣╪º╪▒ ╪º┘ä╪│┘è╪▒┘ü╪▒ ┘ê╪º┘ä╪╣╪»╪º╪» ╪½┘ä╪º╪½ ┘à╪▒╪º╪¬.
       */
      async function scheduleBreakExpiryLocalNotification(brk) {
        if (!brk?.id) return;
        await cancelScheduledBreakExpiryNotification();
      }

      function maybeNotifyBreakExpiredLocally() {
        const mine = getMyActiveStaffBreak();
        if (!mine?.id) {
          state._breakExpiryLocalNotifiedId = null;
          return;
        }
        const rem = getBreakRemainingSeconds(mine);
        if (rem > 0) return;
        if (state._breakExpiryLocalNotifiedId === mine.id) return;
        const storageKey = `athar_break_expiry_local_${mine.id}`;
        try {
          if (localStorage.getItem(storageKey) === '1') {
            state._breakExpiryLocalNotifiedId = mine.id;
            return;
          }
          localStorage.setItem(storageKey, '1');
        } catch (_) { /* noop */ }
        state._breakExpiryLocalNotifiedId = mine.id;
        showLocalBreakExpiryNotification(mine);
      }

      function maybeRollStaffBreaksDay() {
        const todayKey = getStaffBreakTodayKey();
        if (!todayKey) return false;
        if (!state._staffBreakDayKey) {
          state._staffBreakDayKey = todayKey;
          return false;
        }
        if (state._staffBreakDayKey === todayKey) return false;
        state._staffBreakDayKey = todayKey;
        loadStaffBreaksData().then(() => {
          const tab = document.getElementById('tab-breaks');
          if (tab?.classList.contains('active')) renderStaffBreaksPage({ soft: true });
        }).catch(() => { /* noop */ });
        return true;
      }

      function formatBreakClock(totalSeconds) {
        const neg = totalSeconds < 0;
        const abs = Math.abs(Math.floor(totalSeconds));
        const h = Math.floor(abs / 3600);
        const m = Math.floor((abs % 3600) / 60);
        const s = abs % 60;
        const body = h > 0
          ? `${h}:${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`
          : `${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`;
        return neg ? `-${body}` : body;
      }

      function getBreakBalanceSeconds(brk) {
        if (!brk) return 0;
        if (brk.remaining_seconds != null && Number.isFinite(Number(brk.remaining_seconds))) {
          return Number(brk.remaining_seconds);
        }
        return Math.max(0, (Number(brk.planned_duration_minutes) || 0) * 60);
      }

      function getStaffBreakTypeLabel(brkOrType) {
        const type = typeof brkOrType === 'string' ? brkOrType : brkOrType?.break_type;
        return type === 'restroom' ? '╪¿╪▒┘è┘â ╪»┘ê╪▒╪⌐ ┘à┘è╪º┘ç' : '╪¿╪▒┘è┘â';
      }

      function getBreakRemainingSeconds(brk, nowMs = Date.now()) {
        if (!brk) return 0;
        const balance = getBreakBalanceSeconds(brk);
        if (brk.status === 'paused') return balance;
        if (brk.status !== 'active' || !brk.started_at) return balance;
        const start = new Date(brk.started_at).getTime();
        const elapsed = Math.max(0, Math.floor((nowMs - start) / 1000));
        return balance - elapsed;
      }

      function getMyActiveStaffBreak() {
        const me = state.currentUser?.id;
        if (!me) return null;
        return (state.staffBreaks || []).find(b => b.status === 'active' && b.user_id === me) || null;
      }

      function getMyOpenStaffBreak() {
        // ╪¿╪╣╪» ╪º┘ä╪Ñ┘è┘é╪º┘ü ╪¬┘Å╪║┘ä┘é ╪º┘ä╪¼┘ä╪│╪⌐ ΓÇö ┬½┘à┘ü╪¬┘ê╪¡┬╗ = ┘å╪┤╪╖ ┘ü┘é╪╖
        return getMyActiveStaffBreak();
      }

      function getStaffBreakDayRowForType(userId, breakType = 'regular') {
        if (!userId) return null;
        const key = `${userId}:${breakType === 'restroom' ? 'restroom' : 'regular'}`;
        return state.staffBreakDayByUserType?.[key] || null;
      }

      function getMyDisplayBreakSeconds(breakType = 'regular') {
        const open = getMyOpenStaffBreak();
        if (open) return getBreakRemainingSeconds(open);
        const me = state.currentUser;
        const type = breakType === 'restroom' ? 'restroom' : 'regular';
        const dayRow = me?.id ? getStaffBreakDayRowForType(me.id, type) : null;
        if (dayRow && (dayRow.status === 'ended' || dayRow.status === 'paused')) {
          return Math.max(0, Number(dayRow.remaining_seconds) || 0);
        }
        // Prefer live schedule resolution so admin/supervisor duration edits show immediately
        return Math.max(0, (resolveBreakDurationMinsForUser(me, type) || 0) * 60);
      }

      /** ╪«┘ä╪╡╪¬ ┘à╪»╪⌐ ╪º┘ä┘è┘ê┘à ╪ú┘ê ╪¡╪╡┘ä ╪¬╪¼╪º┘ê╪▓ ΓÇö ┘è┘à┘å╪╣ ╪¿╪»╪í ╪¿╪▒┘è┘â ╪¼╪»┘è╪» ┘à┘å ┘å┘ü╪│ ╪º┘ä┘å┘ê╪╣ ╪¡╪¬┘ë ┘ä┘ê ╪¿┘é┘è ╪▒╪╡┘è╪» ┘ü┘è ╪¼┘ä╪│╪⌐ ╪ú┘é╪»┘à */
      function isMyBreakAllowanceExhausted(breakType = 'regular') {
        if (getMyOpenStaffBreak()) return false;
        const me = state.currentUser;
        if (!me?.id) return false;
        const type = breakType === 'restroom' ? 'restroom' : 'regular';
        const rows = (state.staffBreakDayRows || []).filter((row) => {
          if (!row || row.user_id !== me.id) return false;
          const rowType = row.break_type === 'restroom' ? 'restroom' : 'regular';
          return rowType === type;
        });
        const list = rows.length
          ? rows
          : [getStaffBreakDayRowForType(me.id, type)].filter(Boolean);
        return list.some((row) => {
          if (row.status !== 'ended' && row.status !== 'paused') return false;
          return Number(row.remaining_seconds || 0) <= 0
            || Number(row.overtime_seconds || 0) > 0;
        });
      }

      /** ┘ä╪º ┘è┘ê╪¼╪» ╪¿╪▒┘è┘â ┘à╪¼╪»┘ê┘ä ┘ä┘ç╪░╪º ╪º┘ä┘è┘ê┘à (┘ä╪º ┘è┘ê╪¼╪» ┘å╪╖╪º┘é ┘ü┘è┘ç ┘à╪»╪⌐ ┘ä┘è┘ê┘à ╪º┘ä╪ú╪│╪¿┘ê╪╣ ╪º┘ä╪¡╪º┘ä┘è) */
      function isMyBreakUnscheduledToday(breakType = 'regular') {
        if (getMyOpenStaffBreak()) return false;
        return !resolveBreakDurationMinsForUser(state.currentUser, breakType);
      }

      function getStaffBreakTodayKey() {
        // Prefer Intl directly ΓÇö ksaFormatParts().month is 0-indexed
        try {
          return new Intl.DateTimeFormat('en-CA', {
            timeZone: 'Asia/Riyadh',
            year: 'numeric',
            month: '2-digit',
            day: '2-digit'
          }).format(new Date());
        } catch (_) { /* fall through */ }
        const p = typeof ksaFormatParts === 'function' ? ksaFormatParts() : null;
        if (p?.year != null && p?.month != null && p?.day != null) {
          return `${p.year}-${String(p.month + 1).padStart(2, '0')}-${String(p.day).padStart(2, '0')}`;
        }
        return new Date().toISOString().slice(0, 10);
      }

      function getStaffBreakTodayWeekday() {
        const key = getStaffBreakTodayKey();
        const [y, m, d] = key.split('-').map(Number);
        return ksaWeekdayIndex(y, (m || 1) - 1, d);
      }

      /** ┘è╪▒╪¼╪╣ ┘à╪»╪⌐ ╪º┘ä╪¿╪▒┘è┘â ╪¿╪º┘ä╪»┘é╪º╪ª┘é ┘ä┘ç╪░╪º ╪º┘ä┘è┘ê┘à╪î ╪ú┘ê null ╪Ñ┘å ┘ä┘à ╪¬┘â┘å ┘à╪¼╪»┘ê┘ä╪⌐ (┘ä╪º ┘è┘ê╪¼╪» ╪¿╪▒┘è┘â ╪º┘ä┘è┘ê┘à) */
      function resolveBreakDurationMinsForUser(u, breakType = 'regular') {
        const type = breakType === 'restroom' ? 'restroom' : 'regular';
        if (!u) {
          return type === 'restroom'
            ? (state._myRestroomBreakDurationMins || null)
            : (state._myBreakDurationMins || null);
        }
        const dow = getStaffBreakTodayWeekday();
        const schedules = (state.staffBreakSchedules || []).filter(s =>
          s && s.is_active !== false &&
          Number(s.day_of_week) === dow &&
          String(s.break_type || 'regular') === type
        );
        const pick = (type, id) => {
          const rows = schedules.filter(s => s.scope_type === type && (id == null ? !s.scope_id : s.scope_id === id));
          if (!rows.length) return null;
          rows.sort((a, b) => new Date(b.updated_at || 0) - new Date(a.updated_at || 0));
          return Number(rows[0].duration_minutes) || null;
        };
        const userMins = pick('user', u.id);
        if (userMins) return userMins;
        if (u.branch_id) {
          const branchMins = pick('branch', u.branch_id);
          if (branchMins) return branchMins;
          if (!state._branchById) rebuildLookupMaps();
          const branch = state._branchById?.get(u.branch_id) || state.branches.find(b => b.id === u.branch_id);
          if (branch?.region_id) {
            const regionMins = pick('region', branch.region_id);
            if (regionMins) return regionMins;
          }
        }
        return pick('global', null);
      }

      function getUserBreakRemainingSeconds(u) {
        if (!u?.id) return 0;
        const open = (state.staffBreaks || []).find(b =>
          b.user_id === u.id && b.status === 'active'
        );
        if (open) return getBreakRemainingSeconds(open);
        const dayRow = state.staffBreakDayByUser?.[u.id];
        if (dayRow && (dayRow.status === 'ended' || dayRow.status === 'paused')) {
          return Math.max(0, Number(dayRow.remaining_seconds) || 0);
        }
        return Math.max(0, (resolveBreakDurationMinsForUser(u) || 0) * 60);
      }

      function getActiveBreakColleagueInMyBranch() {
        const me = state.currentUser;
        if (!me?.id || !me.branch_id) return null;
        const todayKey = getStaffBreakTodayKey();
        return (state.staffBreaks || []).find(b =>
          b.status === 'active' &&
          (!b.day_key || String(b.day_key).slice(0, 10) === todayKey) &&
          b.branch_id === me.branch_id &&
          b.user_id !== me.id
        ) || null;
      }

      function upsertStaffBreakDayRow(row) {
        if (!row?.id) return;
        const todayKey = getStaffBreakTodayKey();
        if (row.day_key && String(row.day_key).slice(0, 10) !== todayKey) return;
        const next = enrichStaffBreak(row);
        const list = [...(state.staffBreakDayRows || [])];
        const idx = list.findIndex(b => b.id === next.id);
        if (idx >= 0) list[idx] = next;
        else list.unshift(next);
        state.staffBreakDayRows = list.sort(
          (a, b) => new Date(b.started_at || b.updated_at || 0) - new Date(a.started_at || a.updated_at || 0)
        );
        rebuildStaffBreakDayMap(state.staffBreakDayRows);
      }

      function getBreakRosterUsers() {
        const me = state.currentUser;
        if (!me) return [];
        const role = normalizeUserRole(me.role);
        let list = [];
        if (role === 'employee' || role === 'branch_manager') {
          list = getBranchStaff(me.branch_id);
        } else if (role === 'supervisor' || role === 'admin' || role === 'manager' || role === 'auditor') {
          const bids = new Set(getSupervisedBranchesForBreaks().map(b => b.id));
          list = state.users.filter(u => isBranchStaffMember(u) && bids.has(u.branch_id));
        } else if (role === 'observer') {
          if (me.branch_id) list = getBranchStaff(me.branch_id);
          else list = state.users.filter(isBranchStaffMember);
        }
        return list
          .slice()
          .sort((a, b) => String(a.name || '').localeCompare(String(b.name || ''), 'ar'));
      }

      function staffBreakRowRecencyMs(row) {
        if (!row) return 0;
        const t = Date.parse(row.updated_at || row.ended_at || row.paused_at || row.started_at || row.created_at || 0);
        return Number.isFinite(t) ? t : 0;
      }

      function staffBreakEndedRecencyMs(row) {
        if (!row) return 0;
        const t = Date.parse(row.ended_at || row.updated_at || row.paused_at || row.started_at || row.created_at || 0);
        return Number.isFinite(t) ? t : 0;
      }

      function rebuildStaffBreakDayMap(rows) {
        const map = {};
        const typeMap = {};
        const rank = { active: 3, paused: 2, ended: 1 };
        (rows || []).slice().sort((a, b) => {
          const ra = rank[a?.status] || 0;
          const rb = rank[b?.status] || 0;
          if (ra !== rb) return rb - ra;
          return staffBreakRowRecencyMs(b) - staffBreakRowRecencyMs(a);
        }).forEach((row) => {
          if (!row?.user_id) return;
          if (!map[row.user_id]) map[row.user_id] = row;
          const type = row.break_type === 'restroom' ? 'restroom' : 'regular';
          const key = `${row.user_id}:${type}`;
          if (!typeMap[key]) typeMap[key] = row;
        });
        state.staffBreakDayByUser = map;
        state.staffBreakDayByUserType = typeMap;
      }

      function enrichStaffBreak(row) {
        if (!row) return row;
        if (!state._userById || !state._branchById || !state._regionById) rebuildLookupMaps();
        const u = state._userById?.get(row.user_id) || state.users.find(x => x.id === row.user_id);
        const branch = row.branch_id
          ? (state._branchById?.get(row.branch_id) || state.branches.find(b => b.id === row.branch_id))
          : null;
        const region = row.region_id
          ? (state._regionById?.get(row.region_id) || state.regions.find(r => r.id === row.region_id))
          : (branch?.region_id
            ? (state._regionById?.get(branch.region_id) || state.regions.find(r => r.id === branch.region_id))
            : null);
        row._user = u || null;
        row._userName = u?.name || 'ΓÇö';
        row._roleLabel = u ? (ROLE_LABELS[normalizeUserRole(u.role)] || u.role) : '';
        row._branchName = branch?.name || 'ΓÇö';
        row._regionName = region?.name || 'ΓÇö';
        return row;
      }

      async function loadStaffBreaksData() {
        if (!state.currentUser?.id || state.currentUser.id === GUEST_LOCAL_PROFILE.id) {
          state.staffBreaks = [];
          state.staffBreakSchedules = [];
          state.staffBreakDayByUser = {};
          state.staffBreakDayByUserType = {};
          state.staffBreakDayRows = [];
          state._staffBreakDayKey = null;
          return;
        }
        try {
          const todayKey = getStaffBreakTodayKey();
          // Close yesterday's open sessions so remaining minutes / logs reset for the new KSA day
          try { await sb.rpc('close_stale_staff_breaks'); } catch (_) { /* older DB */ }
          const [
            { data: breaks, error: bErr },
            { data: schedules, error: sErr },
            { data: myMins, error: dErr },
            { data: myRestroomMins, error: rErr }
          ] = await Promise.all([
            sb.from('staff_breaks')
              .select('id,user_id,branch_id,region_id,break_type,planned_duration_minutes,remaining_seconds,used_seconds,started_at,paused_at,ended_at,overtime_seconds,overtime_reason,status,day_key,created_at,updated_at')
              .eq('day_key', todayKey)
              .in('status', ['active', 'paused', 'ended'])
              .order('started_at', { ascending: false })
              .limit(500),
            sb.from('staff_break_schedules')
              .select('id,scope_type,scope_id,day_of_week,break_type,duration_minutes,label,is_active,updated_at')
              .eq('is_active', true)
              .order('updated_at', { ascending: false })
              .limit(500),
            sb.rpc('resolve_staff_break_duration', {
              p_user_id: state.currentUser.id,
              p_branch_id: state.currentUser.branch_id || null,
              p_region_id: null,
              p_break_type: 'regular'
            }),
            sb.rpc('resolve_staff_break_duration', {
              p_user_id: state.currentUser.id,
              p_branch_id: state.currentUser.branch_id || null,
              p_region_id: null,
              p_break_type: 'restroom'
            })
          ]);
          if (bErr && isMirsadDebugLog()) console.warn('[staff_breaks]', bErr);
          if (sErr && isMirsadDebugLog()) console.warn('[staff_break_schedules]', sErr);
          if (dErr && isMirsadDebugLog()) console.warn('[resolve_staff_break_duration]', dErr);
          if (rErr && isMirsadDebugLog()) console.warn('[resolve_restroom_break_duration]', rErr);
          const seenIds = new Set();
          const enriched = [];
          (breaks || []).forEach((raw) => {
            if (!raw?.id || seenIds.has(raw.id)) return;
            seenIds.add(raw.id);
            enriched.push(enrichStaffBreak(raw));
          });
          rebuildStaffBreakDayMap(enriched);
          state.staffBreakDayRows = enriched;
          // ┬½┘ü┘è ╪º┘ä╪¿╪▒┘è┘â ╪º┘ä╪ó┘å┬╗ = ┘å╪┤╪╖ ┘ü┘é╪╖╪¢ ╪º┘ä╪Ñ┘è┘é╪º┘ü ┘è╪║┘ä┘é ╪º┘ä╪¼┘ä╪│╪⌐ (ended) ┘ê╪¬┘å╪▓┘ä ┘ä┘ä╪│╪¼┘ä
          state.staffBreaks = enriched.filter(b => b.status === 'active');
          state.staffBreakSchedules = schedules || [];
          // null means no break scheduled for today's weekday at any scope
          const resolvedMins = Number(myMins) > 0
            ? Number(myMins)
            : resolveBreakDurationMinsForUser(state.currentUser);
          state._myBreakDurationMins = resolvedMins > 0 ? resolvedMins : null;
          const resolvedRestroomMins = Number(myRestroomMins) > 0
            ? Number(myRestroomMins)
            : resolveBreakDurationMinsForUser(state.currentUser, 'restroom');
          state._myRestroomBreakDurationMins = resolvedRestroomMins > 0 ? resolvedRestroomMins : null;
          state._staffBreakDayKey = todayKey;
          try { ensureStaffBreakTicker(); } catch (_) { /* noop */ }
          try {
            const mine = getMyActiveStaffBreak();
            if (mine) scheduleBreakExpiryLocalNotification(mine);
          } catch (_) { /* noop */ }
        } catch (e) {
          if (isMirsadDebugLog()) console.warn('[staff_breaks] load', e);
          state.staffBreaks = state.staffBreaks || [];
          state.staffBreakSchedules = state.staffBreakSchedules || [];
          state.staffBreakDayByUser = state.staffBreakDayByUser || {};
          state.staffBreakDayByUserType = state.staffBreakDayByUserType || {};
          state.staffBreakDayRows = state.staffBreakDayRows || [];
        }
      }

      function setupStaffBreaksRealtime() {
        if (state._staffBreaksChannel) {
          try { sb.removeChannel(state._staffBreaksChannel); } catch (_) { /* noop */ }
          state._staffBreaksChannel = null;
        }
        const ch = sb.channel('public:staff_breaks')
          .on('postgres_changes', { event: '*', schema: 'public', table: 'staff_breaks' }, (payload) => {
            const todayKey = getStaffBreakTodayKey();
            const row = enrichStaffBreak(payload.new || payload.old);
            const rowDay = row?.day_key ? String(row.day_key).slice(0, 10) : '';
            const isToday = !rowDay || rowDay === todayKey;

            // Keep day log + open list scoped to today's KSA day only
            let dayRows = [...(state.staffBreakDayRows || [])];
            if (payload.eventType === 'DELETE' && row?.id) {
              dayRows = dayRows.filter(b => b.id !== row.id);
            } else if (payload.new && isToday) {
              const next = enrichStaffBreak(payload.new);
              const idx = dayRows.findIndex(b => b.id === next.id);
              if (idx >= 0) dayRows[idx] = next;
              else dayRows.unshift(next);
            } else if (payload.new && !isToday) {
              dayRows = dayRows.filter(b => b.id !== payload.new.id);
            }
            const uniq = [];
            const seen = new Set();
            dayRows
              .filter(b => b?.id && (!b.day_key || String(b.day_key).slice(0, 10) === todayKey))
              .sort((a, b) => new Date(b.started_at || b.updated_at || 0) - new Date(a.started_at || a.updated_at || 0))
              .forEach((b) => {
                if (seen.has(b.id)) return;
                seen.add(b.id);
                uniq.push(b);
              });
            state.staffBreakDayRows = uniq;
            rebuildStaffBreakDayMap(uniq);
            state.staffBreaks = uniq
              .filter(b => b.status === 'active')
              .map(enrichStaffBreak);

            try { ensureStaffBreakTicker(); } catch (_) { /* noop */ }
            const tab = document.getElementById('tab-breaks');
            // Don't replace the ring mid-click ΓÇö keeps busy UI stable until RPC finishes.
            if (tab?.classList.contains('active') && !isStaffBreakActionBusy()) {
              renderStaffBreaksPage({ soft: true });
            }
          })
          .on('postgres_changes', { event: '*', schema: 'public', table: 'staff_break_schedules' }, () => {
            // Duration edits must refresh minutes for every connected employee immediately
            loadStaffBreaksData().then(() => {
              const tab = document.getElementById('tab-breaks');
              if (tab?.classList.contains('active')) renderStaffBreaksPage({ soft: true });
              else if (typeof paintStaffBreakCountdownOnly === 'function') {
                try { paintStaffBreakCountdownOnly(); } catch (_) { /* noop */ }
              }
            });
          })
          .subscribe();
        state._staffBreaksChannel = ch;
        state.realtimeChannels.push(ch);
      }

      function getStaffBreakScopeLabel(sch) {
        if (!sch) return 'ΓÇö';
        if (sch.scope_type === 'global') return '╪╣╪º┘à (┘â┘ä ╪º┘ä┘à┘å╪╡╪⌐)';
        if (sch.scope_type === 'region') {
          const r = state.regions.find(x => x.id === sch.scope_id);
          return `┘à┘å╪╖┘é╪⌐: ${r?.name || 'ΓÇö'}`;
        }
        if (sch.scope_type === 'branch') {
          const b = state.branches.find(x => x.id === sch.scope_id);
          return `┘ü╪▒╪╣: ${b?.name || 'ΓÇö'}`;
        }
        if (sch.scope_type === 'user') {
          const u = state.users.find(x => x.id === sch.scope_id);
          return `┘à┘ê╪╕┘ü: ${u?.name || 'ΓÇö'}`;
        }
        return sch.scope_type;
      }

      function getSupervisedRegionsForBreaks() {
        const me = state.currentUser;
        if (!me) return [];
        if (normalizeUserRole(me.role) === 'admin' || normalizeUserRole(me.role) === 'manager' || normalizeUserRole(me.role) === 'auditor') return state.regions.slice();
        return state.regions.filter(r => r.supervisor_id === me.id);
      }

      function getSupervisedBranchesForBreaks() {
        const regions = getSupervisedRegionsForBreaks();
        if (normalizeUserRole(state.currentUser?.role) === 'admin' || normalizeUserRole(state.currentUser?.role) === 'manager' || normalizeUserRole(state.currentUser?.role) === 'auditor') return state.branches.slice();
        const ids = new Set(regions.map(r => r.id));
        return state.branches.filter(b => ids.has(b.region_id));
      }

      function getManageableBreakUsers() {
        const branches = getSupervisedBranchesForBreaks();
        const bids = new Set(branches.map(b => b.id));
        return state.users.filter(u =>
          isStaffBreakParticipantUser(u) &&
          u.branch_id &&
          bids.has(u.branch_id)
        );
      }

      function getBreakStatusFilter() {
        return state._breakStatusFilter || 'all';
      }

      function setBreakStatusFilter(key) {
        state._breakStatusFilter = key || 'all';
        if (typeof renderStaffBreaksPage === 'function') renderStaffBreaksPage({ soft: true });
      }

      function getBreakSearchQuery() {
        return String(state._breakRosterSearch || '').trim().toLowerCase();
      }

      function breakRecordMatchesSearch({ name, employeeNumber, branchName }) {
        const q = getBreakSearchQuery();
        if (!q) return true;
        const hayName = String(name || '').toLowerCase();
        const hayBranch = String(branchName || '').toLowerCase();
        const empRaw = String(employeeNumber || '').toLowerCase();
        const empPad = typeof padEmpNum === 'function' ? padEmpNum(employeeNumber) : '';
        const empPadHay = empPad && empPad !== '-' ? String(empPad).toLowerCase() : '';
        if (hayName.includes(q) || hayBranch.includes(q) || empRaw.includes(q) || empPadHay.includes(q)) return true;
        const qDigits = q.replace(/\D/g, '');
        const empDigits = empRaw.replace(/\D/g, '');
        return !!(qDigits && empDigits && empDigits.includes(qDigits));
      }

      function staffBreakLiveMatchesSearch(b) {
        const u = b?._user || state._userById?.get(b?.user_id) || state.users.find(x => x.id === b?.user_id);
        return breakRecordMatchesSearch({
          name: b?._userName || u?.name,
          employeeNumber: u?.employee_number,
          branchName: b?._branchName
        });
      }

      function staffBreakUserMatchesSearch(u) {
        const branch = u?.branch_id
          ? (state._branchById?.get(u.branch_id) || state.branches.find(b => b.id === u.branch_id))
          : null;
        return breakRecordMatchesSearch({
          name: u?.name,
          employeeNumber: u?.employee_number,
          branchName: branch?.name
        });
      }

      function refreshBreaksFromSearch(el) {
        state._breakRosterSearch = el && el.value != null ? el.value : (state._breakRosterSearch || '');
        const id = 'rdBreaksSearch';
        const start = el && typeof el.selectionStart === 'number' ? el.selectionStart : null;
        const end = el && typeof el.selectionEnd === 'number' ? el.selectionEnd : start;
        const restore = () => {
          const next = document.getElementById(id);
          if (!next) return;
          next.focus();
          if (start == null) return;
          try { next.setSelectionRange(start, end); } catch (_) { /* noop */ }
        };
        const ret = typeof renderStaffBreaksPage === 'function'
          ? renderStaffBreaksPage({ soft: true })
          : null;
        if (ret && typeof ret.then === 'function') ret.then(restore);
        else restore();
      }

      function getBreakDeskShowCard() {
        return canTakeStaffBreak();
      }

      function renderBreaksDeskToolbarHtml() {
        const filter = getBreakStatusFilter();
        const q = Sec.escapeHTML(state._breakRosterSearch || '');
        const filters = [
          { key: 'all', label: '╪º┘ä┘â┘ä' },
          { key: 'active', label: '┘ü┘è ╪º┘ä╪¿╪▒┘è┘â ╪º┘ä╪ó┘å' },
          { key: 'paused', label: '┘à╪¬┘ê┘é┘ü' },
          { key: 'overage', label: '╪¬╪¼╪º┘ê╪▓ ╪º┘ä┘à╪»╪⌐' },
          { key: 'ended', label: '╪º┘å╪¬┘ç┘ë' }
        ].map(f => {
          const on = filter === f.key;
          return `<button type="button" class="rd-breaks-toolchip${on ? ' is-on' : ''}" onclick="setBreakStatusFilter('${f.key}')">${Sec.escapeHTML(f.label)}</button>`;
        }).join('');
        return `
          <div class="rd-breaks-toolbar">
            <div class="rd-breaks-search rd-app-search">
              <input type="search" class="rd-breaks-search__input rd-app-search__input" id="rdBreaksSearch" value="${q}"
                placeholder="╪¿╪¡╪½ ╪¿╪▒┘é┘à ╪º┘ä┘à┘ê╪╕┘ü╪î ╪º┘ä╪º╪│┘à╪î ╪ú┘ê ╪º┘ä┘ü╪▒╪╣..." autocomplete="off" inputmode="search"
                oninput="refreshBreaksFromSearch(this)" aria-label="╪¿╪¡╪½ ╪¿╪▒┘é┘à ╪º┘ä┘à┘ê╪╕┘ü ╪ú┘ê ╪º┘ä╪º╪│┘à ╪ú┘ê ╪º┘ä┘ü╪▒╪╣">
            </div>
            <div class="rd-breaks-toolbar__filters">
              ${filters}
            </div>
          </div>`;
      }

      function breakRowMatchesFilter(kind) {
        const filter = getBreakStatusFilter();
        if (filter === 'all') return true;
        return filter === kind;
      }

      /** ╪ú┘è ╪ú┘é╪│╪º┘à ╪º┘ä┘é┘ê╪º╪ª┘à ╪¬┘Å╪╣╪▒╪╢ ╪¡╪│╪¿ ╪┤╪▒┘è╪¡╪⌐ ╪º┘ä╪¬╪╡┘ü┘è╪⌐ ╪º┘ä┘å╪┤╪╖╪⌐ */
      function getBreakListSectionsVisibility() {
        const filter = getBreakStatusFilter();
        return {
          // ┬½╪º┘ä┘â┘ä┬╗ ┘é╪º╪ª┘à╪⌐ ┘à┘ê╪¡┘æ╪»╪⌐ ╪¿┘ä╪º ╪╣┘å╪º┘ê┘è┘å ╪ú┘é╪│╪º┘à
          showUnifiedAll: filter === 'all',
          showLive: filter === 'active' || filter === 'overage',
          // ╪¼┘ä╪│╪º╪¬ ╪º┘ä╪¬╪¼╪º┘ê╪▓ ╪º┘ä┘à┘å╪¬┘ç┘è╪⌐ ╪¬╪¿┘é┘ë ┘ü┘è ┘ü┘ä╪¬╪▒ ┬½╪¬╪¼╪º┘ê╪▓ ╪º┘ä┘à╪»╪⌐┬╗ ╪¿╪╣╪» ╪º┘ä╪Ñ┘è┘é╪º┘ü
          showRoster: filter === 'paused' || filter === 'overage' || filter === 'ended'
        };
      }

      function formatBreakDurationLabel(mins) {
        const n = Math.max(0, Number(mins) || 0);
        if (n >= 60) return '╪│╪º╪╣╪⌐';
        return `${n} ╪»┘é┘è┘é╪⌐`;
      }

      function formatBreakOverageClock(totalSeconds) {
        const abs = Math.abs(Math.floor(Number(totalSeconds) || 0));
        return `+${formatBreakClock(abs)}`;
      }

      function paintStaffBreakCountdownOnly() {
        const host = document.getElementById('rdBreaksRingHost') || document.getElementById('breaksRingHost');
        if (host) {
        const desk = !!(host.closest && host.closest('.rd-breaks-page--desk'));
        const open = getMyOpenStaffBreak();
        const active = open?.status === 'active' ? open : null;
        const plannedSec = Math.max(1, (Number(open?.planned_duration_minutes) || state._myBreakDurationMins || 15) * 60);
        const remaining = getMyDisplayBreakSeconds();
        const overtime = !!(active && remaining < 0);
        const isPaused = open?.status === 'paused';
        const readyMins = state._myBreakDurationMins || Math.round(plannedSec / 60);
        let progress;
        if (!open) progress = 1;
        else if (!overtime) progress = Math.max(0.02, Math.min(1, remaining / plannedSec));
        else progress = desk ? 1 : Math.min(1, Math.abs(remaining) / plannedSec);

        const circ = STAFF_BREAK_RING_CIRC;
        const offset = circ * (1 - progress);
        const pauseYellow = 'var(--warning, #ff9500)';
        const stroke = overtime
          ? 'var(--danger)'
          : (active ? 'var(--success)' : (isPaused ? pauseYellow : (desk ? 'var(--text3)' : 'var(--border)')));
        const clockColor = overtime
          ? 'var(--danger)'
          : (active ? (desk ? 'var(--success)' : 'var(--text)') : (isPaused ? pauseYellow : (desk ? 'var(--text3)' : 'var(--text)')));
        const daysEl = host.querySelector('[data-break-clock]');
        const lblEl = host.querySelector('[data-break-lbl]');
        const ringEl = host.querySelector('[data-break-ring-progress]');
        const icoEl = host.querySelector('[data-break-ico]');
        const badgeEl = host.querySelector('[data-break-badge]');
        host.classList.toggle('rd-break-card--paused', !!isPaused);
        host.classList.toggle('rd-break-card--over', !!overtime);
        host.classList.toggle('rd-break-card--icon-center', !!(desk && (host.dataset.breakKind === 'depleted' || host.dataset.breakKind === 'unscheduled' || host.dataset.breakKind === 'viewOnly')));
        if (daysEl) {
          if (desk) {
            if (overtime) daysEl.textContent = formatBreakOverageClock(remaining);
            else if (active || isPaused) daysEl.textContent = formatBreakClock(remaining);
            else if (host.dataset.breakKind === 'branchBusy' || host.dataset.breakKind === 'ready') {
              daysEl.textContent = formatBreakDurationLabel(readyMins);
            }
          } else {
            daysEl.hidden = false;
            daysEl.textContent = formatBreakClock(remaining);
          }
          daysEl.style.color = clockColor;
        }
        if (lblEl) {
          if (desk) {
            lblEl.hidden = true;
          } else {
            lblEl.hidden = false;
            lblEl.textContent = overtime
              ? '╪¬╪¼╪º┘ê╪▓ ╪º┘ä┘à╪»╪⌐'
              : (active ? `┘à╪¬╪¿┘é┘è ┘à┘å ${getStaffBreakTypeLabel(active)}` : (isPaused ? '┘à╪¬┘ê┘é┘ü ΓÇö ┘à╪¬╪¿┘é┘è' : '┘à╪»╪⌐ ╪º┘ä╪¿╪▒┘è┘â'));
            lblEl.style.color = overtime ? 'var(--danger)' : (isPaused ? pauseYellow : 'var(--text3)');
          }
        }
        if (badgeEl) {
          if (desk) {
            if (overtime) {
              badgeEl.hidden = false;
              badgeEl.textContent = '╪¬╪¼╪º┘ê╪▓';
              badgeEl.style.color = 'var(--danger)';
              badgeEl.style.background = 'color-mix(in srgb, var(--danger) 13%, transparent)';
            } else if (active) {
              badgeEl.hidden = false;
              badgeEl.textContent = getStaffBreakTypeLabel(active);
              badgeEl.style.color = 'var(--success)';
              badgeEl.style.background = 'color-mix(in srgb, var(--success) 13%, transparent)';
            } else if (isPaused) {
              badgeEl.hidden = false;
              badgeEl.textContent = '┘à╪¬┘ê┘é┘ü';
              badgeEl.style.color = pauseYellow;
              badgeEl.style.background = 'color-mix(in srgb, var(--warning, #ff9500) 13%, transparent)';
            } else if (host.dataset.breakKind === 'ready') {
              badgeEl.hidden = false;
              badgeEl.textContent = formatBreakDurationLabel(readyMins);
              badgeEl.style.color = 'var(--text3)';
              badgeEl.style.background = 'color-mix(in srgb, var(--text3) 13%, transparent)';
            } else {
              badgeEl.hidden = true;
              badgeEl.textContent = '';
            }
          } else {
            badgeEl.hidden = false;
            badgeEl.innerHTML = overtime
              ? '<i class="fas fa-triangle-exclamation"></i>╪¬╪¼╪º┘ê╪▓'
              : (active
                ? `<i class="fas fa-mug-hot"></i>${Sec.escapeHTML(getStaffBreakTypeLabel(active))}`
                : (isPaused
                  ? '<i class="fas fa-pause"></i>┘à╪¬┘ê┘é┘ü'
                  : (state._myBreakDurationMins
                    ? `<i class="fas fa-hourglass-half"></i>${state._myBreakDurationMins} ╪»┘é┘è┘é╪⌐`
                    : '<i class="fas fa-ban"></i>┘ä╪º ┘è┘ê╪¼╪» ╪¿╪▒┘è┘â ╪º┘ä┘è┘ê┘à')));
            badgeEl.removeAttribute('style');
          }
        }
        if (ringEl) {
          ringEl.setAttribute('stroke', stroke);
          ringEl.setAttribute('stroke-dasharray', String(circ));
          ringEl.setAttribute('stroke-dashoffset', open ? String(offset) : '0');
        }
        if (icoEl) {
          if (desk) {
            icoEl.style.color = clockColor;
          } else {
            icoEl.hidden = false;
            icoEl.style.color = overtime ? 'var(--danger)' : (active ? 'var(--success)' : (isPaused ? pauseYellow : 'var(--text3)'));
            icoEl.className = 'fas ' + (overtime ? 'fa-triangle-exclamation' : (active ? 'fa-mug-hot' : (isPaused ? 'fa-pause' : 'fa-clock')));
            icoEl.style.fontSize = '16px';
            icoEl.style.marginBottom = '4px';
          }
        }
        }
        document.querySelectorAll('[data-break-live-row]').forEach(rowEl => {
          const id = rowEl.getAttribute('data-break-live-row');
          const brk = (state.staffBreaks || []).find(b => b.id === id && b.status === 'active');
          if (!brk) return;
          const rem = getBreakRemainingSeconds(brk);
          const over = rem < 0;
          rowEl.classList.toggle('rd-break-row--paused', false);
          rowEl.classList.toggle('rd-break-row--active', !over);
          rowEl.classList.toggle('rd-break-row--over', over);
          const clock = rowEl.querySelector('[data-break-row-clock]');
          if (clock) {
            clock.textContent = over ? formatBreakOverageClock(rem) : formatBreakClock(rem);
            clock.classList.toggle('rd-break-row__clock--over', over);
            clock.classList.toggle('rd-break-row__clock--paused', false);
            clock.classList.toggle('rd-break-row__clock--active', !over);
          }
          const statusEl = rowEl.querySelector('[data-break-row-status]');
          if (statusEl) {
            const typeLabel = getStaffBreakTypeLabel(brk);
            statusEl.textContent = over ? `${typeLabel} ΓÇö ╪¬╪¼╪º┘ê╪▓ ╪º┘ä┘à╪»╪⌐` : typeLabel;
            statusEl.classList.toggle('rd-break-status--over', over);
            statusEl.classList.toggle('rd-break-status--paused', false);
          }
          const forceBtn = rowEl.querySelector('[data-break-admin-force]');
          if (forceBtn) forceBtn.hidden = !over;
          paintStaffBreakDualBars(brk.user_id);
        });
        document.querySelectorAll('[data-break-roster-user]').forEach(el => {
          const uid = el.getAttribute('data-break-roster-user');
          const u = state._userById?.get(uid) || state.users.find(x => x.id === uid);
          if (!u) return;
          const view = getBreakRosterRowView(u);
          el.textContent = view.minsLabel;
          el.classList.toggle('rd-break-roster__mins--zero', view.unscheduled || (view.depleted && (view.minsLabel === '0 ╪»' || view.minsLabel === '00:00')));
          el.classList.toggle('rd-break-roster__mins--over', view.overEnded);
          el.classList.toggle('rd-break-roster__mins--busy', view.busy);
          const row = el.closest('[data-break-roster-row]');
          if (row) {
            row.classList.toggle('rd-break-roster-row--over', view.overEnded);
            const st = row.querySelector('[data-break-roster-status]');
            if (st) {
              st.textContent = view.statusLbl;
              st.classList.toggle('rd-break-status--over', view.overEnded);
              st.classList.toggle('rd-break-status--busy', view.busy);
              st.classList.toggle('rd-break-status--paused', view.stopped);
            }
          }
          paintStaffBreakDualBars(uid);
        });
      }

      function renderStaffBreakRingHtml() {
        const desk = typeof isAtharDesktopScreenUi === 'function' && isAtharDesktopScreenUi();
        if (!getBreakDeskShowCard()) return '';
        const viewOnly = !canTakeStaffBreak();
        const open = getMyOpenStaffBreak();
        const active = open?.status === 'active' ? open : null;
        const isPaused = open?.status === 'paused';
        const colleague = !active && !isPaused ? getActiveBreakColleagueInMyBranch() : null;
        const regularAvailable = !isMyBreakAllowanceExhausted('regular') && !isMyBreakUnscheduledToday('regular');
        const restroomAvailable = !isMyBreakAllowanceExhausted('restroom') && !isMyBreakUnscheduledToday('restroom');
        const anyBreakAvailable = regularAvailable || restroomAvailable;
        const readyType = regularAvailable ? 'regular' : 'restroom';
        const readyMins = resolveBreakDurationMinsForUser(state.currentUser, readyType) || 15;
        const plannedSec = Math.max(1, (Number(open?.planned_duration_minutes) || readyMins) * 60);
        const remaining = getMyDisplayBreakSeconds(active?.break_type || readyType);
        const overtime = !!(active && remaining < 0);
        const exhausted = !viewOnly && !active && !isPaused && !anyBreakAvailable
          && (isMyBreakAllowanceExhausted('regular') || isMyBreakAllowanceExhausted('restroom'));
        const unscheduledToday = !viewOnly && !active && !isPaused && !anyBreakAvailable && !exhausted;
        const durationLbl = formatBreakDurationLabel(readyMins);

        // ΓöÇΓöÇ ┘à╪│╪º╪▒ ╪º┘ä╪¼┘ê╪º┘ä: ╪│╪º╪╣╪⌐ + ╪¬╪│┘à┘è╪⌐ + ╪▓╪▒ ┘ê╪º╪╢╪¡ (┘ä╪º ┘è┘Å╪╖╪¿┘æ┘Ä┘é ┘à┘ê┘â ╪ú╪¿ ╪│╪╖╪¡ ╪º┘ä┘à┘â╪¬╪¿ ┘ç┘å╪º) ΓöÇΓöÇ
        if (!desk) {
          if (viewOnly) return '';
          let progress = 1;
          if (active && !overtime) progress = Math.max(0, Math.min(1, remaining / plannedSec));
          else if (isPaused) progress = Math.max(0, Math.min(1, remaining / plannedSec));
          else if (overtime) progress = Math.min(1, Math.abs(remaining) / plannedSec);
          const circ = STAFF_BREAK_RING_CIRC;
          const offset = circ * (1 - progress);
          const pauseYellow = 'var(--warning, #ff9500)';
          const stroke = overtime ? 'var(--danger)' : (active ? 'var(--success)' : (isPaused ? pauseYellow : 'var(--border)'));
          const clockColor = overtime ? 'var(--danger)' : (isPaused ? pauseYellow : 'var(--text)');
          const icoColor = overtime ? 'var(--danger)' : (active ? 'var(--success)' : (isPaused ? pauseYellow : 'var(--text3)'));
          const lblColor = overtime ? 'var(--danger)' : (isPaused ? pauseYellow : 'var(--text3)');
          const badge = overtime
            ? '<i class="fas fa-triangle-exclamation"></i>╪¬╪¼╪º┘ê╪▓'
            : (active
              ? `<i class="fas fa-mug-hot"></i>${Sec.escapeHTML(getStaffBreakTypeLabel(active))}`
              : (isPaused
                ? '<i class="fas fa-pause"></i>┘à╪¬┘ê┘é┘ü'
                : (state._myBreakDurationMins
                  ? `<i class="fas fa-hourglass-half"></i>${state._myBreakDurationMins} ╪»┘é┘è┘é╪⌐`
                  : '<i class="fas fa-ban"></i>┘ä╪º ┘è┘ê╪¼╪» ╪¿╪▒┘è┘â ╪º┘ä┘è┘ê┘à')));
          let actionsHtml;
          if (isStaffBreakActionBusy()) {
            const busyLbl = getMyActiveStaffBreak() ? '╪¼╪º╪▒┘è ╪º┘ä╪Ñ┘è┘é╪º┘üΓÇª' : '╪¼╪º╪▒┘è ╪º┘ä╪¿╪»╪íΓÇª';
            actionsHtml = `<button type="button" class="btn btn-primary rd-break-btn rd-break-btn--busy" disabled aria-busy="true"><i class="fas fa-spinner fa-spin" aria-hidden="true"></i>${busyLbl}</button>`;
          } else if (active) {
            actionsHtml = `<button type="button" class="btn btn-primary rd-break-btn rd-break-btn--danger" onclick="endStaffBreakFromUi()">╪Ñ┘è┘é╪º┘ü ╪º┘ä╪¿╪▒┘è┘â</button>`;
          } else if (isPaused) {
            actionsHtml = `<button type="button" class="btn btn-primary rd-break-btn rd-break-btn--success" onclick="startStaffBreakFromUi()">┘à╪¬╪º╪¿╪╣╪⌐ ╪º┘ä╪¿╪▒┘è┘â</button>`;
          } else if (exhausted) {
            actionsHtml = `
              <button type="button" class="btn btn-primary rd-break-btn rd-break-btn--muted" disabled aria-disabled="true">╪¿╪»╪í ╪º┘ä╪¿╪▒┘è┘â</button>
              <p class="rd-break-note rd-break-note--warn">╪«┘ä╪╡╪¬ ┘à╪»╪⌐ ╪¿╪▒┘è┘â ╪º┘ä┘è┘ê┘à</p>`;
          } else if (unscheduledToday) {
            actionsHtml = `
              <button type="button" class="btn btn-primary rd-break-btn rd-break-btn--muted" disabled aria-disabled="true">╪¿╪»╪í ╪º┘ä╪¿╪▒┘è┘â</button>
              <p class="rd-break-note rd-break-note--warn">┘ä╪º ┘è┘ê╪¼╪» ╪¿╪▒┘è┘â ┘à╪¼╪»┘ê┘ä ┘ä┘ç╪░╪º ╪º┘ä┘è┘ê┘à</p>`;
          } else if (colleague) {
            actionsHtml = `
              <button type="button" class="btn btn-primary rd-break-btn rd-break-btn--muted" disabled aria-disabled="true">╪¿╪»╪í ╪º┘ä╪¿╪▒┘è┘â</button>
              <p class="rd-break-note rd-break-note--warn">╪▓┘à┘è┘ä ┘ü┘è ╪¿╪▒┘è┘â ╪º┘ä╪ó┘å (${Sec.escapeHTML(colleague._userName || 'ΓÇö')}) ΓÇö ╪º┘å╪¬╪╕╪▒ ╪¡╪¬┘ë ┘è╪╣┘ê╪»</p>`;
          } else {
            actionsHtml = `<button type="button" class="btn btn-primary rd-break-btn rd-break-btn--gold" onclick="startStaffBreakFromUi()">╪¿╪»╪í ╪º┘ä╪¿╪▒┘è┘â</button>`;
          }
          return `
            <div class="rd-streak rd-break-card${isPaused ? ' rd-break-card--paused' : ''}${overtime ? ' rd-break-card--over' : ''}"
              id="rdBreaksRingHost" data-break-kind="${active ? (overtime ? 'overage' : 'active') : (isPaused ? 'paused' : (exhausted ? 'depleted' : (unscheduledToday ? 'unscheduled' : (colleague ? 'branchBusy' : 'ready'))))}">
              <div class="rd-streak__badge" data-break-badge>${badge}</div>
              <div class="rd-streak__ring rd-break-ring">
                <svg width="168" height="168" viewBox="0 0 132 132" aria-hidden="true">
                  <circle cx="66" cy="66" r="54" fill="none" stroke="var(--border)" stroke-width="10"></circle>
                  <circle data-break-ring-progress cx="66" cy="66" r="54" fill="none" stroke="${stroke}" stroke-width="10"
                    stroke-linecap="round" stroke-dasharray="${circ}" stroke-dashoffset="${open ? offset : 0}"></circle>
                </svg>
                <div class="rd-streak__center">
                  <i data-break-ico class="fas ${overtime ? 'fa-triangle-exclamation' : (active ? 'fa-mug-hot' : (isPaused ? 'fa-pause' : 'fa-clock'))}"
                    style="font-size:16px;color:${icoColor};margin-bottom:4px"></i>
                  <span class="rd-streak__days rd-break-clock" data-break-clock dir="ltr" style="color:${clockColor}">${formatBreakClock(remaining)}</span>
                  <span class="rd-streak__lbl" data-break-lbl style="color:${lblColor}">${
                    overtime ? '╪¬╪¼╪º┘ê╪▓ ╪º┘ä┘à╪»╪⌐' : (active ? `┘à╪¬╪¿┘é┘è ┘à┘å ${getStaffBreakTypeLabel(active)}` : (isPaused ? '┘à╪¬┘ê┘é┘ü ΓÇö ┘à╪¬╪¿┘é┘è' : '┘à╪»╪⌐ ╪º┘ä╪¿╪▒┘è┘â'))
                  }</span>
                </div>
              </div>
              <div class="rd-break-actions">${actionsHtml}</div>
            </div>`;
        }

        let kind = 'ready';
        if (viewOnly) kind = 'viewOnly';
        else if (overtime) kind = 'overage';
        else if (active) kind = 'active';
        else if (isPaused) kind = 'paused';
        else if (exhausted) kind = 'depleted';
        else if (unscheduledToday) kind = 'unscheduled';
        else if (colleague) kind = 'branchBusy';

        let progress = 1;
        if (active && !overtime) progress = Math.max(0.02, Math.min(1, remaining / plannedSec));
        else if (isPaused) progress = Math.max(0.02, Math.min(1, remaining / plannedSec));
        const circ = STAFF_BREAK_RING_CIRC;
        const offset = circ * (1 - progress);
        const pauseYellow = 'var(--warning, #ff9500)';

        const defs = {
          ready: {
            badge: durationLbl, badgeColor: 'var(--text3)', ring: 'var(--text3)',
            center: durationLbl, centerColor: 'var(--text3)', icon: '', actions: 'start'
          },
          active: {
            badge: getStaffBreakTypeLabel(active), badgeColor: 'var(--success)', ring: 'var(--success)',
            center: formatBreakClock(remaining), centerColor: 'var(--success)', icon: '', actions: 'stop'
          },
          paused: {
            badge: durationLbl, badgeColor: 'var(--text3)', ring: 'var(--text3)',
            center: durationLbl, centerColor: 'var(--text3)', icon: '', actions: 'start'
          },
          overage: {
            badge: '╪¬╪¼╪º┘ê╪▓', badgeColor: 'var(--danger)', ring: 'var(--danger)',
            center: formatBreakOverageClock(remaining), centerColor: 'var(--danger)', icon: '', actions: 'stop'
          },
          depleted: {
            badge: '', badgeColor: '', ring: 'var(--text3)',
            center: '', centerColor: 'var(--text3)', icon: 'fa-check', actions: 'disabled',
            note: '╪«┘ä╪╡╪¬ ┘à╪»╪⌐ ╪¿╪▒┘è┘â ╪º┘ä┘è┘ê┘à'
          },
          unscheduled: {
            badge: '', badgeColor: '', ring: 'var(--text3)',
            center: '', centerColor: 'var(--text3)', icon: 'fa-calendar-xmark', actions: 'disabled',
            note: '┘ä╪º ┘è┘ê╪¼╪» ╪¿╪▒┘è┘â ┘à╪¼╪»┘ê┘ä ┘ä┘ç╪░╪º ╪º┘ä┘è┘ê┘à'
          },
          branchBusy: {
            badge: '', badgeColor: '', ring: 'var(--text3)',
            center: durationLbl, centerColor: 'var(--text3)', icon: '', actions: 'disabled',
            note: `╪▓┘à┘è┘ä ┘ü┘è ╪¿╪▒┘è┘â ╪º┘ä╪ó┘å (${colleague?._userName || 'ΓÇö'}) ΓÇö ╪º┘å╪¬╪╕╪▒ ╪¡╪¬┘ë ┘è╪╣┘ê╪»`
          },
          viewOnly: {
            badge: '', badgeColor: '', ring: 'var(--text3)',
            center: '', centerColor: 'var(--text3)', icon: 'fa-eye', actions: 'none',
            note: '╪»┘ê╪▒┘â ╪º┘ä╪¡╪º┘ä┘è ┘ä┘ä╪╣╪▒╪╢ ┘ü┘é╪╖'
          }
        };
        const def = defs[kind] || defs.ready;

        let actionsHtml = '';
        if (isStaffBreakActionBusy()) {
          const busyLbl = (active || overtime) ? '╪¼╪º╪▒┘è ╪º┘ä╪Ñ┘è┘é╪º┘üΓÇª' : '╪¼╪º╪▒┘è ╪º┘ä╪¿╪»╪íΓÇª';
          actionsHtml = `<button type="button" class="rd-break-btn rd-break-btn--busy" disabled aria-busy="true"><i class="fas fa-spinner fa-spin" aria-hidden="true"></i>${busyLbl}</button>`;
        } else if (def.actions === 'start') {
          actionsHtml = `<button type="button" class="rd-break-btn rd-break-btn--gold" onclick="startStaffBreakFromUi()">╪¿╪»╪í ╪º┘ä╪¿╪▒┘è┘â</button>`;
        } else if (def.actions === 'stop') {
          actionsHtml = `<button type="button" class="rd-break-btn rd-break-btn--danger" onclick="endStaffBreakFromUi()">╪Ñ┘è┘é╪º┘ü ╪º┘ä╪¿╪▒┘è┘â</button>`;
        } else if (def.actions === 'disabled') {
          actionsHtml = `<button type="button" class="rd-break-btn rd-break-btn--muted" disabled aria-disabled="true">╪¿╪»╪í ╪º┘ä╪¿╪▒┘è┘â</button>`;
        }
        if (def.note) {
          actionsHtml += `<div class="rd-break-note">${Sec.escapeHTML(def.note)}</div>`;
        }

        const badgeStyle = def.badge
          ? `style="color:${def.badgeColor};background:color-mix(in srgb, ${def.badgeColor} 13%, transparent)"`
          : 'hidden';
        const centerHtml = def.icon
          ? `<i data-break-ico class="fas ${def.icon}" style="font-size:26px;color:${def.centerColor}"></i>
             <span class="rd-streak__days rd-break-clock" data-break-clock hidden dir="ltr"></span>`
          : `<i data-break-ico class="fas fa-clock" hidden aria-hidden="true"></i>
             <span class="rd-streak__days rd-break-clock" data-break-clock dir="ltr" style="color:${def.centerColor}">${Sec.escapeHTML(def.center)}</span>`;

        return `
          <div class="rd-streak rd-break-card${isPaused ? ' rd-break-card--paused' : ''}${overtime ? ' rd-break-card--over' : ''}${def.icon ? ' rd-break-card--icon-center' : ''}"
            id="rdBreaksRingHost" data-break-kind="${kind}">
            <div class="rd-streak__badge" data-break-badge ${badgeStyle}>${def.badge ? Sec.escapeHTML(def.badge) : ''}</div>
            <div class="rd-streak__ring rd-break-ring">
              <svg width="168" height="168" viewBox="0 0 132 132" aria-hidden="true">
                <circle cx="66" cy="66" r="54" fill="none" stroke="var(--border)" stroke-width="10"></circle>
                <circle data-break-ring-progress cx="66" cy="66" r="54" fill="none" stroke="${def.ring}" stroke-width="10"
                  stroke-linecap="round" stroke-dasharray="${circ}" stroke-dashoffset="${(open || isPaused) && !viewOnly ? offset : 0}"></circle>
              </svg>
              <div class="rd-streak__center">
                ${centerHtml}
                <span class="rd-streak__lbl" data-break-lbl hidden></span>
              </div>
            </div>
            <div class="rd-break-actions">${actionsHtml}</div>
          </div>`;
      }

      function getUserBreakTypeMeter(u, breakType = 'regular') {
        const type = breakType === 'restroom' ? 'restroom' : 'regular';
        const label = type === 'restroom' ? '╪»┘ê╪▒╪⌐ ┘à┘è╪º┘ç' : '╪¿╪▒┘è┘â';
        const icon = type === 'restroom' ? 'fa-restroom' : 'fa-mug-hot';
        if (!u?.id) {
          return { type, label, icon, plannedSec: 0, remainingSec: 0, pct: 0, tone: 'none', timeLabel: 'ΓÇö', active: false };
        }
        const plannedMins = resolveBreakDurationMinsForUser(u, type);
        if (!plannedMins) {
          return { type, label, icon, plannedSec: 0, remainingSec: 0, pct: 0, tone: 'none', timeLabel: 'ΓÇö', active: false };
        }
        const plannedSec = Math.max(1, plannedMins * 60);
        const active = (state.staffBreaks || []).find((b) =>
          b.user_id === u.id
          && b.status === 'active'
          && (b.break_type === 'restroom' ? 'restroom' : 'regular') === type
        );
        let remainingSec;
        if (active) {
          remainingSec = getBreakRemainingSeconds(active);
        } else {
          const dayRow = getStaffBreakDayRowForType(u.id, type);
          if (dayRow && (dayRow.status === 'ended' || dayRow.status === 'paused')) {
            remainingSec = Number(dayRow.remaining_seconds);
            if (!Number.isFinite(remainingSec)) remainingSec = 0;
            const overSec = Number(dayRow.overtime_seconds);
            if (Number.isFinite(overSec) && overSec > 0) {
              remainingSec = Math.min(remainingSec, -overSec);
            }
          } else {
            remainingSec = plannedSec;
          }
        }
        const over = remainingSec < 0;
        const pct = over
          ? 0
          : Math.max(0, Math.min(100, (remainingSec / plannedSec) * 100));
        let tone = 'regular';
        if (type === 'restroom') tone = 'restroom';
        if (over) tone = 'over';
        else if (remainingSec <= 0) tone = 'empty';
        else if (pct <= 25) tone = 'low';
        const timeLabel = over
          ? formatBreakOverageClock(remainingSec)
          : formatBreakClock(Math.max(0, remainingSec));
        return {
          type,
          label,
          icon,
          plannedSec,
          remainingSec,
          pct,
          tone,
          timeLabel,
          active: !!active
        };
      }

      function renderStaffBreakDualBarsHtml(u, opts = {}) {
        if (!u?.id) return '';
        // Always show both lines (working + idle) so each type has its own minutes.
        const types = ['regular', 'restroom'];
        const meters = types.map((type) => getUserBreakTypeMeter(u, type));
        return `
          <div class="rd-break-bars" data-break-bars="${Sec.escapeHTML(u.id)}">
            ${meters.map((m) => {
              const minsTone = m.tone === 'over' || m.tone === 'low' || m.tone === 'empty'
                ? ' rd-break-bar__mins--warn'
                : (m.active ? ' rd-break-bar__mins--active' : '');
              return `
              <div class="rd-break-bar" data-break-bar-type="${m.type}" title="${Sec.escapeHTML(m.label)}">
                <i class="fas ${m.icon} rd-break-bar__ico" aria-hidden="true"></i>
                <div class="rd-break-bar__track" role="progressbar"
                  aria-label="${Sec.escapeHTML(m.label)}"
                  aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(m.pct)}"
                  data-break-bar-track>
                  <div class="rd-break-bar__fill rd-break-bar__fill--${m.tone}"
                    data-break-bar-fill style="width:${m.pct.toFixed(1)}%"></div>
                </div>
                <span class="rd-break-bar__mins${minsTone}"
                  data-break-bar-mins dir="ltr">${Sec.escapeHTML(m.timeLabel)}</span>
              </div>`;
            }).join('')}
          </div>`;
      }

      function paintStaffBreakDualBars(uid) {
        if (!uid) return;
        const u = state._userById?.get(uid) || state.users.find((x) => x.id === uid);
        if (!u) return;
        const host = document.querySelector(`[data-break-bars="${uid}"]`);
        if (!host) return;
        ['regular', 'restroom'].forEach((type) => {
          const meter = getUserBreakTypeMeter(u, type);
          const bar = host.querySelector(`[data-break-bar-type="${type}"]`);
          if (!bar) return;
          const fill = bar.querySelector('[data-break-bar-fill]');
          const track = bar.querySelector('[data-break-bar-track]');
          const mins = bar.querySelector('[data-break-bar-mins]');
          if (fill) {
            fill.style.width = `${meter.pct.toFixed(1)}%`;
            fill.className = `rd-break-bar__fill rd-break-bar__fill--${meter.tone}`;
          }
          if (track) track.setAttribute('aria-valuenow', String(Math.round(meter.pct)));
          if (mins) {
            mins.textContent = meter.timeLabel;
            mins.classList.toggle('rd-break-bar__mins--warn',
              meter.tone === 'over' || meter.tone === 'low' || meter.tone === 'empty');
            mins.classList.toggle('rd-break-bar__mins--active',
              !!meter.active && meter.tone !== 'over' && meter.tone !== 'low' && meter.tone !== 'empty');
          }
        });
      }

      function getActiveStaffBreakLiveRows() {
        const todayKey = getStaffBreakTodayKey();
        return (state.staffBreaks || [])
          .filter(b => {
            // ┬½┘ü┘è ╪º┘ä╪¿╪▒┘è┘â ╪º┘ä╪ó┘å┬╗: ╪º┘ä╪¼╪º╪▒┘è ┘ü┘é╪╖ ΓÇö ╪º┘ä╪Ñ┘è┘é╪º┘ü ┘è╪║┘ä┘é ╪º┘ä╪¼┘ä╪│╪⌐ ┘ê╪¬┘å╪▓┘ä ┘ä┘ä╪│╪¼┘ä
            if (b.status !== 'active') return false;
            if (b.day_key && String(b.day_key).slice(0, 10) !== todayKey) return false;
            const u = state._userById?.get(b.user_id) || state.users.find(x => x.id === b.user_id);
            if (u && !isStaffBreakParticipantUser(u)) return false;
            return true;
          })
          .slice()
          .sort((a, b) => new Date(b.started_at || b.updated_at || 0) - new Date(a.started_at || a.updated_at || 0));
      }

      function canAdminForceEndStaffBreak() {
        return normalizeUserRole(state.currentUser?.role) === 'admin';
      }

      function renderStaffBreaksListHtml(opts = {}) {
        let rows = getActiveStaffBreakLiveRows();
        rows = rows.filter(b => {
          const rem = getBreakRemainingSeconds(b);
          const kind = isStaffBreakReportableOvertime(b, rem) ? 'overage' : 'active';
          return breakRowMatchesFilter(kind);
        });
        if (getBreakStatusFilter() === 'ended' || getBreakStatusFilter() === 'paused') rows = [];
        rows = rows.filter(staffBreakLiveMatchesSearch);
        if (!rows.length) {
          if (opts.itemsOnly) return '';
          const emptyLbl = getBreakSearchQuery() ? '┘ä╪º ╪¬┘ê╪¼╪» ┘å╪¬╪º╪ª╪¼ ┘à╪╖╪º╪¿┘é╪⌐' : '┘ä╪º ┘è┘ê╪¼╪» ╪ú╪¡╪» ┘ü┘è ╪¿╪▒┘è┘â ╪¡╪º┘ä┘è╪º┘ï';
          return `<div class="rd-break-empty-panel">${emptyLbl}</div>`;
        }
        const canHist = canViewStaffBreakHistory();
        const canForce = canAdminForceEndStaffBreak();
        const items = rows.map(b => {
          const rem = getBreakRemainingSeconds(b);
          const over = rem < 0;
          const me = b.user_id === state.currentUser?.id;
          const typeLabel = getStaffBreakTypeLabel(b);
          const statusLbl = over ? `${typeLabel} ΓÇö ╪¬╪¼╪º┘ê╪▓ ╪º┘ä┘à╪»╪⌐` : typeLabel;
          const typeIcon = b.break_type === 'restroom' ? 'fa-restroom' : 'fa-mug-hot';
          const user = b._user
            || state._userById?.get(b.user_id)
            || state.users.find((x) => x.id === b.user_id)
            || { id: b.user_id, name: b._userName, branch_id: b.branch_id };
          const clickAttr = canHist
            ? ` role="button" tabindex="0" onclick="openStaffBreakHistory('${Sec.escapeHTML(b.user_id)}')" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();openStaffBreakHistory('${Sec.escapeHTML(b.user_id)}')}"`
            : '';
          const tone = over ? ' rd-break-row--over' : ' rd-break-row--active';
          const timeTxt = over ? formatBreakOverageClock(rem) : formatBreakClock(rem);
          const forceBtn = canForce
            ? `<button type="button" class="rd-break-force-end" data-break-admin-force="${Sec.escapeHTML(b.id)}" ${over ? '' : 'hidden'}
                 onclick="event.stopPropagation(); adminForceEndStaffBreakFromUi('${Sec.escapeHTML(b.id)}')"
                 title="╪Ñ┘è┘é╪º┘ü ╪º┘ä╪¿╪▒┘è┘â ╪º┘ä┘à╪¬╪¼╪º┘ê╪▓">╪Ñ┘è┘é╪º┘ü</button>`
            : '';
          return `
            <div class="rd-list__row rd-break-row rd-break-row--live${tone}${me ? ' rd-break-row--me' : ''}${canHist ? ' rd-break-row--clickable' : ''}"
              data-break-live-row="${Sec.escapeHTML(b.id)}" data-break-live-status="${Sec.escapeHTML(b.status)}" style="cursor:${canHist ? 'pointer' : 'default'}"${clickAttr}>
              <div class="rd-break-row__av rd-break-row__av--type" aria-label="${Sec.escapeHTML(typeLabel)}" title="${Sec.escapeHTML(typeLabel)}">
                <i class="fas ${typeIcon}" aria-hidden="true"></i>
              </div>
              <div class="rd-list__main">
                <div class="rd-list__title">${Sec.escapeHTML(b._userName || 'ΓÇö')}${me ? ' <span class="rd-break-me-tag">╪ú┘å╪¬</span>' : ''}</div>
                <div class="rd-list__sub">${Sec.escapeHTML(b._branchName || 'ΓÇö')} ┬╖ <span data-break-row-status class="rd-break-status${over ? ' rd-break-status--over' : ''}">${Sec.escapeHTML(statusLbl)}</span></div>
              </div>
              ${renderStaffBreakDualBarsHtml(user)}
              <div class="rd-break-row__clock${over ? ' rd-break-row__clock--over' : ' rd-break-row__clock--active'}" data-break-row-clock="${Sec.escapeHTML(b.id)}" dir="ltr">${timeTxt}</div>
              ${forceBtn}
            </div>`;
        }).join('');
        if (opts.itemsOnly) return items;
        return `<div class="rd-list rd-break-list">${items}</div>`;
      }

      function getStaffBreakOvertimeSeconds(dayRow) {
        if (!dayRow) return 0;
        const fromField = Number(dayRow.overtime_seconds);
        if (Number.isFinite(fromField) && fromField > 0) return fromField;
        const rem = Number(dayRow.remaining_seconds);
        if (Number.isFinite(rem) && rem < 0) return Math.abs(rem);
        return 0;
      }

      function isStaffBreakReportableOvertime(brk, remainingSeconds) {
        if (!brk || brk.break_type === 'restroom') return false;
        const remaining = remainingSeconds == null
          ? getBreakRemainingSeconds(brk)
          : Number(remainingSeconds);
        return Number.isFinite(remaining) && remaining < -BREAK_OVERTIME_REASON_AFTER_SEC;
      }

      function getBreakRosterRowView(u) {
        const remSec = Math.max(0, Math.floor(Number(getUserBreakRemainingSeconds(u)) || 0));
        const mins = Math.max(0, Math.floor(remSec / 60));
        const dayRow = state.staffBreakDayByUser?.[u.id];
        const isRestroom = dayRow?.break_type === 'restroom';
        const typeLabel = isRestroom ? '╪¿╪▒┘è┘â ╪»┘ê╪▒╪⌐ ╪º┘ä┘à┘è╪º┘ç' : '╪º┘ä╪¿╪▒┘è┘â';
        const overSec = dayRow?.status === 'ended' ? getStaffBreakOvertimeSeconds(dayRow) : 0;
        const overEnded = !isRestroom
          && overSec > BREAK_OVERTIME_REASON_AFTER_SEC
          && Number(dayRow?.remaining_seconds || 0) <= 0;
        const unscheduled = !dayRow
          && !resolveBreakDurationMinsForUser(u, 'regular')
          && !resolveBreakDurationMinsForUser(u, 'restroom');
        const depleted = !overEnded && (dayRow?.status === 'ended' || dayRow?.status === 'paused') && remSec <= 0;
        const stopped = !overEnded && !depleted && !unscheduled
          && (dayRow?.status === 'ended' || dayRow?.status === 'paused')
          && remSec > 0;
        const busy = !overEnded && !depleted && !unscheduled && !!(state.staffBreaks || []).some(b =>
          b.status === 'active' && b.user_id !== u.id && b.branch_id === u.branch_id
        );
        const usedLbl = dayRow && typeof getBreakSessionUsedLabel === 'function'
          ? getBreakSessionUsedLabel(dayRow)
          : 'ΓÇö';
        let statusLbl = '┘à╪¬╪º╪¡';
        let minsLabel = formatBreakClock(remSec);
        if (overEnded) {
          statusLbl = `${typeLabel} ΓÇö ╪º┘å╪¬┘ç┘ë ┘à╪╣ ╪¬╪¼╪º┘ê╪▓`;
          minsLabel = formatBreakOverageClock(overSec);
        } else if (unscheduled) {
          statusLbl = '╪║┘è╪▒ ┘à╪¼╪»┘ê┘ä ╪º┘ä┘è┘ê┘à';
          minsLabel = 'ΓÇö';
        } else if (depleted) {
          statusLbl = `╪º┘â╪¬┘à┘ä╪¬ ┘à╪»╪⌐ ${typeLabel} ╪º┘ä┘è┘ê┘à`;
          minsLabel = usedLbl && usedLbl !== 'ΓÇö' ? usedLbl : '00:00';
        } else if (stopped) {
          statusLbl = `${typeLabel} ΓÇö ┘à╪¬┘ê┘é┘ü`;
        } else if (busy) {
          statusLbl = '╪º┘ä┘ü╪▒╪╣ ┘à╪┤╪║┘ê┘ä';
        }
        return { mins, dayRow, overEnded, unscheduled, depleted, stopped, busy, statusLbl, minsLabel };
      }

      function renderStaffBreakRosterHtml(opts = {}) {
        // ┬½╪º┘ä╪│╪¼┘ä┬╗: ┘â┘ä ┘à┘å ┘ä┘è╪│ ┘ü┘è ╪¿╪▒┘è┘â ┘å╪┤╪╖ (╪¿╪╣╪» ╪º┘ä╪Ñ┘è┘é╪º┘ü ┘è┘å╪▓┘ä ┘ç┘å╪º)
        const liveIds = new Set(
          (state.staffBreaks || [])
            .filter(b => b.status === 'active')
            .map(b => b.user_id)
        );
        const users = getBreakRosterUsers().filter(u => !liveIds.has(u.id)).filter(u => {
          if (!staffBreakUserMatchesSearch(u)) return false;
          const view = getBreakRosterRowView(u);
          const filter = getBreakStatusFilter();
          if (filter === 'all') return true;
          if (filter === 'active') return false;
          if (filter === 'paused') return view.stopped;
          if (filter === 'overage') return view.overEnded;
          if (filter === 'ended') return view.depleted || view.unscheduled;
          return true;
        }).sort((a, b) => {
          const filter = getBreakStatusFilter();
          if (filter !== 'paused' && filter !== 'overage' && filter !== 'ended') return 0;
          const aRow = state.staffBreakDayByUser?.[a.id];
          const bRow = state.staffBreakDayByUser?.[b.id];
          const recency = filter === 'ended'
            ? staffBreakEndedRecencyMs
            : staffBreakRowRecencyMs;
          return recency(bRow) - recency(aRow);
        });
        if (!users.length) {
          if (opts.itemsOnly) return '';
          return '<div class="rd-break-empty-panel">┘ä╪º ╪¬┘ê╪¼╪» ┘å╪¬╪º╪ª╪¼ ┘à╪╖╪º╪¿┘é╪⌐</div>';
        }
        const canHist = canViewStaffBreakHistory();
        const items = users.map(u => {
          const view = getBreakRosterRowView(u);
          const branch = state._branchById?.get(u.branch_id) || state.branches.find(b => b.id === u.branch_id);
          const me = u.id === state.currentUser?.id;
          const rowTone = view.overEnded ? ' rd-break-roster-row--over' : '';
          const recordTypeLabel = view.dayRow ? getStaffBreakTypeLabel(view.dayRow) : '';
          const recordTypeIcon = view.dayRow?.break_type === 'restroom' ? 'fa-restroom' : 'fa-mug-hot';
          const avatarHtml = view.dayRow
            ? `<div class="rd-break-row__av rd-break-row__av--type" aria-label="${Sec.escapeHTML(recordTypeLabel)}" title="${Sec.escapeHTML(recordTypeLabel)}"><i class="fas ${recordTypeIcon}" aria-hidden="true"></i></div>`
            : `<div class="rd-break-row__av" aria-hidden="true">${Sec.escapeHTML((u.name || '┘à').trim().charAt(0) || '┘à')}</div>`;
          const clickAttr = canHist
            ? ` role="button" tabindex="0" onclick="openStaffBreakHistory('${Sec.escapeHTML(u.id)}')" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();openStaffBreakHistory('${Sec.escapeHTML(u.id)}')}"`
            : '';
          return `
            <div class="rd-list__row rd-break-roster-row${rowTone}${me ? ' rd-break-row--me' : ''}${canHist ? ' rd-break-row--clickable' : ''}"
              data-break-roster-row="${Sec.escapeHTML(u.id)}" style="cursor:${canHist ? 'pointer' : 'default'}"${clickAttr}>
              ${avatarHtml}
              <div class="rd-list__main">
                <div class="rd-list__title">${Sec.escapeHTML(u.name || 'ΓÇö')}${me ? ' <span class="rd-break-me-tag">╪ú┘å╪¬</span>' : ''}</div>
                <div class="rd-list__sub">${Sec.escapeHTML(branch?.name || 'ΓÇö')} ┬╖ <span data-break-roster-status class="rd-break-status${view.overEnded ? ' rd-break-status--over' : ''}${view.busy ? ' rd-break-status--busy' : ''}${view.stopped ? ' rd-break-status--paused' : ''}">${Sec.escapeHTML(view.statusLbl)}</span></div>
              </div>
              ${renderStaffBreakDualBarsHtml(u)}
              <div class="rd-break-roster__mins${view.unscheduled || (view.depleted && (view.minsLabel === '0 ╪»' || view.minsLabel === '00:00')) ? ' rd-break-roster__mins--zero' : ''}${view.overEnded ? ' rd-break-roster__mins--over' : ''}${view.busy ? ' rd-break-roster__mins--busy' : ''}"
                data-break-roster-user="${Sec.escapeHTML(u.id)}" data-break-roster-over="${view.overEnded ? '1' : '0'}" dir="ltr">${Sec.escapeHTML(view.minsLabel)}</div>
            </div>`;
        }).join('');
        if (opts.itemsOnly) return items;
        return `<div class="rd-list rd-break-list">${items}</div>`;
      }

      function renderStaffBreakAllUnifiedHtml() {
        const items = `${renderStaffBreaksListHtml({ itemsOnly: true })}${renderStaffBreakRosterHtml({ itemsOnly: true })}`;
        if (!items.trim()) {
          const emptyLbl = getBreakSearchQuery() ? '┘ä╪º ╪¬┘ê╪¼╪» ┘å╪¬╪º╪ª╪¼ ┘à╪╖╪º╪¿┘é╪⌐' : '┘ä╪º ┘è┘ê╪¼╪» ┘à┘ê╪╕┘ü┘ê┘å ┘ä╪╣╪▒╪╢┘ç┘à';
          return `<div class="rd-break-empty-panel">${emptyLbl}</div>`;
        }
        return `<div class="rd-sec rd-break-list-sec rd-break-list-sec--all">
          <div class="rd-list rd-break-list">${items}</div>
        </div>`;
      }

      function formatBreakHistoryWhen(iso) {
        if (!iso) return 'ΓÇö';
        if (typeof ksaFormatDateTime === 'function') return ksaFormatDateTime(iso);
        try { return new Date(iso).toLocaleString('ar-SA'); } catch (_) { return String(iso); }
      }

      function getBreakSessionUsedLabel(row) {
        const used = Number(row?.used_seconds);
        if (Number.isFinite(used) && used > 0) {
          return `${Math.max(1, Math.ceil(used / 60))} ╪»`;
        }
        if (row?.status === 'active') {
          const rem = getBreakRemainingSeconds(row);
          const planned = Math.max(0, (Number(row.planned_duration_minutes) || 15) * 60);
          const elapsed = Math.max(0, planned - rem);
          return `${Math.max(1, Math.ceil(elapsed / 60))} ╪»`;
        }
        if (row?.started_at && row?.ended_at) {
          const sec = Math.max(0, Math.floor((new Date(row.ended_at) - new Date(row.started_at)) / 1000));
          return `${Math.max(1, Math.ceil(sec / 60))} ╪»`;
        }
        return 'ΓÇö';
      }

      function renderStaffBreakHistorySessionsHtml(sessions) {
        if (!sessions.length) {
          return '<div class="break-history-empty">┘ä╪º ╪¬┘ê╪¼╪» ╪¼┘ä╪│╪º╪¬ ╪¿╪▒┘è┘â ┘ä┘ç╪░╪º ╪º┘ä┘è┘ê┘à</div>';
        }
        // ╪º┘ä╪ú┘é╪»┘à ╪ú┘ê┘ä╪º┘ï: ╪¿╪»╪í/╪Ñ┘è┘é╪º┘ü = ╪º┘ä╪¼┘ä╪│╪⌐ 1╪î ╪½┘à 2╪î ΓÇª
        const ordered = sessions.slice().sort((a, b) =>
          new Date(a.started_at || a.created_at || 0) - new Date(b.started_at || b.created_at || 0)
        );
        return ordered.map((row, idx) => {
          const n = idx + 1;
          const typeLabel = getStaffBreakTypeLabel(row);
          const overSec = getStaffBreakOvertimeSeconds(row);
          let statusLbl = '╪º┘å╪¬┘ç┘ë';
          let tone = '';
          if (row.status === 'active') {
            statusLbl = overSec > 0 || getBreakRemainingSeconds(row) < 0 ? '╪¼╪º╪▒┘è ΓÇö ╪¬╪¼╪º┘ê╪▓ ╪º┘ä┘à╪»╪⌐' : '╪¼╪º╪▒┘è ╪º┘ä╪ó┘å';
            tone = ' break-history-item--active';
          } else if (row.status === 'paused') {
            statusLbl = '╪º┘å╪¬┘ç┘ë';
            tone = ' break-history-item--paused';
          } else if (overSec > 0) {
            statusLbl = `╪º┘å╪¬┘ç┘ë ┘à╪╣ ╪¬╪¼╪º┘ê╪▓ (+${Math.max(1, Math.ceil(overSec / 60))} ╪»)`;
            tone = ' break-history-item--over';
          }
          const endLbl = row.status === 'active'
            ? '┘à╪º ╪▓╪º┘ä ╪¼╪º╪▒┘è┘ï╪º'
            : formatBreakHistoryWhen(row.ended_at || row.paused_at || row.updated_at);
          const endKey = '╪º┘ä╪º┘å╪¬┘ç╪º╪í';
          const reason = String(row.overtime_reason || '').trim();
          const showReason = overSec > 0 || !!reason || (row.status === 'active' && getBreakRemainingSeconds(row) < 0);
          const reasonHtml = showReason
            ? `<div class="break-history-item__reason">
                <dt>╪│╪¿╪¿ ╪º┘ä╪¬╪¼╪º┘ê╪▓</dt>
                <dd>${reason ? Sec.escapeHTML(reason) : '<span class="break-history-item__reason-empty">┘ä┘à ┘è┘Å╪│╪¼┘æ┘Ä┘ä ╪¿╪╣╪»</span>'}</dd>
              </div>`
            : '';
          return `
            <article class="break-history-item${tone}">
              <header class="break-history-item__hd">
                <span class="break-history-item__n">╪º┘ä╪¼┘ä╪│╪⌐ ${n} ┬╖ ${Sec.escapeHTML(typeLabel)}</span>
                <span class="break-history-item__st">${Sec.escapeHTML(statusLbl)}</span>
              </header>
              <dl class="break-history-item__dl">
                <div><dt>╪º┘ä╪¿╪»╪í</dt><dd>${Sec.escapeHTML(formatBreakHistoryWhen(row.started_at))}</dd></div>
                <div><dt>${endKey}</dt><dd>${Sec.escapeHTML(endLbl)}</dd></div>
                <div><dt>┘à╪»╪⌐ ╪º┘ä╪º╪│╪¬┘à╪▒╪º╪▒</dt><dd>${Sec.escapeHTML(getBreakSessionUsedLabel(row))}</dd></div>
                ${reasonHtml}
              </dl>
            </article>`;
        }).join('');
      }

      async function openStaffBreakHistory(userId) {
        if (!canViewStaffBreakHistory()) {
          showToast('┘ä╪º ╪¬┘à┘ä┘â ╪╡┘ä╪º╪¡┘è╪⌐ ╪╣╪▒╪╢ ╪│╪¼┘ä ╪º┘ä╪¿╪▒┘è┘â╪º╪¬', 'warning');
          return;
        }
        if (!userId) return;
        const u = state._userById?.get(userId) || state.users.find(x => x.id === userId);
        const title = document.getElementById('breakHistTitle');
        const empNumEl = document.getElementById('breakHistEmpNum');
        const metaEl = document.getElementById('breakHistMeta');
        const liveEl = document.getElementById('breakHistLive');
        const sub = document.getElementById('breakHistSub');
        const list = document.getElementById('breakHistList');
        const name = u?.name || '╪º┘ä┘à┘ê╪╕┘ü';
        if (title) title.textContent = name;
        if (empNumEl) {
          const empNum = u?.employee_number ? padEmpNum(u.employee_number) : '';
          const showNum = !!(empNum && empNum !== '-');
          empNumEl.textContent = showNum ? empNum : '';
          empNumEl.hidden = !showNum;
        }
        if (metaEl) {
          const roleKey = normalizeUserRole(u?.role);
          const roleLbl = ROLE_LABELS[roleKey] || getStaffJobTitle(u) || 'ΓÇö';
          const branch = state._branchById?.get(u?.branch_id) || state.branches.find(b => b.id === u?.branch_id);
          metaEl.textContent = `${roleLbl} ┬╖ ${branch?.name || 'ΓÇö'}`;
        }
        const openBrk = (state.staffBreaks || []).find(b =>
          b.user_id === userId && b.status === 'active'
        );
        if (liveEl) {
          if (openBrk) {
            const rem = getBreakRemainingSeconds(openBrk);
            const typeLabel = getStaffBreakTypeLabel(openBrk);
            let liveLabel = `${typeLabel} ΓÇö ╪¼╪º╪▒┘ì ╪º┘ä╪ó┘å`;
            if (rem < 0) liveLabel = `${typeLabel} ΓÇö ╪¬╪¼╪º┘ê╪▓ ${formatBreakOverageClock(rem)}`;
            liveEl.hidden = false;
            liveEl.innerHTML = `<span class="break-history-live__dot" aria-hidden="true"></span><span>${Sec.escapeHTML(liveLabel)}</span>`;
          } else {
            liveEl.hidden = true;
            liveEl.innerHTML = '';
          }
        }
        if (sub) sub.textContent = `╪º┘ä┘è┘ê┘à (${getStaffBreakTodayKey()}) ΓÇö ┘â┘ä ╪¿╪»╪í/╪Ñ┘è┘é╪º┘ü = ╪¼┘ä╪│╪⌐ (╪¬╪¿╪»╪ú ┘à┘å ╪º┘ä╪¼┘ä╪│╪⌐ 1)`;
        if (list) list.innerHTML = '<div class="break-history-empty">╪¼╪º╪▒┘è ╪º┘ä╪¬╪¡┘à┘è┘äΓÇª</div>';
        openModal('breakHistoryModal');
        try {
          const todayKey = getStaffBreakTodayKey();
          let sessions = (state.staffBreakDayRows || [])
            .filter(b => b.user_id === userId && (!b.day_key || String(b.day_key).slice(0, 10) === todayKey));
          const { data, error } = await sb.from('staff_breaks')
            .select('id,user_id,branch_id,break_type,planned_duration_minutes,remaining_seconds,used_seconds,started_at,paused_at,ended_at,overtime_seconds,overtime_reason,status,day_key,updated_at')
            .eq('user_id', userId)
            .eq('day_key', todayKey)
            .order('started_at', { ascending: false })
            .limit(100);
          if (error && isMirsadDebugLog()) console.warn('[staff_breaks] history', error);
          if (data?.length) sessions = data.map(enrichStaffBreak);
          sessions = sessions
            .slice()
            .sort((a, b) => new Date(b.started_at || b.updated_at || 0) - new Date(a.started_at || a.updated_at || 0));
          if (list) list.innerHTML = renderStaffBreakHistorySessionsHtml(sessions);
        } catch (e) {
          if (list) list.innerHTML = `<div class="break-history-empty">╪¬╪╣╪░┘æ╪▒ ╪º┘ä╪¬╪¡┘à┘è┘ä: ${Sec.escapeHTML(e.message || e)}</div>`;
        }
      }

