      async function submitComplaintFromUi() {
        if (!canSubmitComplaint()) {
          showToast('╪│╪¼┘æ┘ä ╪º┘ä╪»╪«┘ê┘ä ┘ä╪▒┘ü╪╣ ╪┤┘â┘ê┘ë ╪ú┘ê ╪º┘é╪¬╪▒╪º╪¡', 'warning');
          return;
        }
        const desc = String(document.getElementById('cpDescText')?.value || '').trim();
        if (!desc) {
          showToast('╪º┘â╪¬╪¿ ╪¬┘ü╪º╪╡┘è┘ä ╪º┘ä╪┤┘â┘ê┘ë ╪ú┘ê ╪º┘ä╪º┘é╪¬╪▒╪º╪¡', 'warning');
          return;
        }
        const files = state.uploadedFiles.cp || [];
        if (files.some(f => f.prepStatus === 'error')) {
          showToast('╪ú╪▓┘ä ╪º┘ä┘à╪▒┘ü┘é ╪º┘ä┘ü╪º╪┤┘ä ╪ú┘ê ╪ú╪╣╪» ╪º╪«╪¬┘è╪º╪▒┘ç', 'warning');
          return;
        }
        if (files.length && isAttachmentPrepInProgress('cp')) {
          showToast('╪º┘å╪¬╪╕╪▒ ╪º┘â╪¬┘à╪º┘ä ╪¬╪¡╪╢┘è╪▒ ╪º┘ä┘à╪▒┘ü┘é╪º╪¬', 'warning');
          return;
        }
        const anonymous = !!state.complaintAnonymous;
        const submitBtn = document.getElementById('cpSubmitBtn');
        const prevHtml = submitBtn?.innerHTML;
        try {
          if (submitBtn) {
            submitBtn.dataset.submitting = '1';
            submitBtn.disabled = true;
            submitBtn.innerHTML = `<i class="fas fa-spinner fa-spin"></i> ╪¼╪º╪▒┘è ╪º┘ä╪Ñ╪▒╪│╪º┘äΓÇª`;
          }
          const attachments = await buildComplaintAttachmentsPayload(anonymous);
          const { data, error } = await sb.from('complaints').insert({
            employee_id: state.currentUser.id,
            kind: state.complaintKind,
            category: state.complaintCategory,
            description: desc,
            attachments
          }).select().single();
          if (error) throw error;
          let row = data;
          row = await finalizeComplaintRowAttachments(row);
          state.complaints = [row, ...(state.complaints || []).filter(c => c.id !== row.id)];
          await clearComplaintAttachFiles({ deleteRemote: false });
          closeNewComplaintModal();
          const kindWord = state.complaintKind === 'suggestion' ? '╪º┘ä╪º┘é╪¬╪▒╪º╪¡' : '╪º┘ä╪┤┘â┘ê┘ë';
          showToast(
            anonymous ? `╪¬┘à ╪Ñ╪▒╪│╪º┘ä ${kindWord} ┘â┘à╪¼┘ç┘ê┘ä ╪¿┘å╪¼╪º╪¡` : `╪¬┘à ╪Ñ╪▒╪│╪º┘ä ${kindWord} ╪¿┘å╪¼╪º╪¡`,
            'success'
          );
          paintComplaintsPage();
        } catch (e) {
          showToast('┘ü╪┤┘ä ╪º┘ä╪Ñ╪▒╪│╪º┘ä: ' + (e.message || e), 'error');
        } finally {
          if (submitBtn) {
            submitBtn.dataset.submitting = '0';
            submitBtn.disabled = false;
            submitBtn.innerHTML = prevHtml || `<i class="fas fa-paper-plane"></i> ╪Ñ╪▒╪│╪º┘ä ╪º┘ä╪┤┘â┘ê┘ë`;
            syncAttachmentSubmitButtons('cp');
            syncNewComplaintForm();
          }
        }
      }

      function renderComplaintThreadHtml(c) {
        const logs = visibleComplaintLogs(Array.isArray(c.logs) ? c.logs : [], c.kind);
        if (!logs.length) return '';
        const anon = complaintIsAnonymous(c);
        return `<div style="display:flex;flex-direction:column;gap:10px;margin-bottom:16px">` +
          logs.map((m, msgIdx) => {
            const isAdmin = !!m.is_admin;
            const author = (anon && !isAdmin) ? '┘à╪¼┘ç┘ê┘ä' : (m.author || '');
            const bg = isAdmin ? 'color-mix(in srgb, var(--gold, var(--primary)) 12%, var(--surface))' : 'var(--surface)';
            const authorColor = isAdmin ? 'var(--gold, var(--primary))' : 'var(--text2)';
            const time = formatRelativeAr(m.at) || '';
            const authorIc = isAdmin ? 'fa-headset' : (anon ? 'fa-user-secret' : 'fa-user');
            const msgAtts = normalizeComplaintAttachmentList(m.attachments);
            const msgAttPair = renderComplaintInlineAttPair(msgAtts, `mob-reply-${msgIdx}`);
            const textHtml = m.text
              ? `<div class="rd-cmpl-thread-text" style="font-size:11.5px;color:var(--text2);line-height:1.7">${Sec.escapeHTML(m.text)}</div>`
              : '';
            return `
              <div style="min-width:0;background:${bg};border:1px solid var(--border);border-radius:14px;padding:11px 13px">
                <div style="display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:4px">
                  <span style="display:inline-flex;align-items:center;gap:6px;font-size:10.5px;font-weight:700;color:${authorColor}"><i class="fas ${authorIc}" style="font-size:10px" aria-hidden="true"></i>${Sec.escapeHTML(author)}</span>
                  <span style="font-size:9px;color:var(--text3)">${Sec.escapeHTML(time)}</span>
                </div>
                <div class="rd-cmpl-thread-body${msgAttPair.first ? ' has-inline-att' : ''}">
                  ${textHtml}
                  ${msgAttPair.first}
                </div>
                ${msgAttPair.rest}
              </div>`;
          }).join('') +
          `</div>`;
      }

      function autoExpandComplaintReplyText(textarea) {
        if (!textarea) return;
        textarea.style.setProperty('height', 'auto');
        const minH = 40;
        const maxH = 280;
        const scrollH = textarea.scrollHeight || minH;
        if (scrollH > maxH) {
          textarea.style.setProperty('height', maxH + 'px', 'important');
          textarea.style.setProperty('overflow-y', 'auto', 'important');
        } else {
          textarea.style.setProperty('height', Math.max(minH, scrollH) + 'px', 'important');
          textarea.style.setProperty('overflow-y', 'hidden', 'important');
        }
      }
      window.autoExpandComplaintReplyText = autoExpandComplaintReplyText;

