      async function submitComplaintReplyFromUi() {
        const c = getComplaintById(state.activeComplaintId);
        if (c && isComplaintClosed(c)) {
          showToast('╪º┘ä╪┤┘â┘ê┘ë ┘à╪¡┘ä┘ê┘ä╪⌐ ΓÇö ╪º┘ä╪▒╪» ┘à┘é┘ü┘ê┘ä', 'warning');
          return;
        }
        const text = String(document.getElementById('cpReplyText')?.value || '').trim();
        const files = state.uploadedFiles.cpr || [];
        if (files.some(f => f.prepStatus === 'error')) {
          showToast('╪ú╪▓┘ä ╪º┘ä┘à╪▒┘ü┘é ╪º┘ä┘ü╪º╪┤┘ä ╪ú┘ê ╪ú╪╣╪» ╪º╪«╪¬┘è╪º╪▒┘ç', 'warning');
          return;
        }
        if (files.length && isAttachmentPrepInProgress('cpr')) {
          showToast('╪º┘å╪¬╪╕╪▒ ╪º┘â╪¬┘à╪º┘ä ╪¬╪¡╪╢┘è╪▒ ╪º┘ä┘à╪▒┘ü┘é╪º╪¬', 'warning');
          return;
        }
        if (!text && !files.length) {
          showToast('╪º┘â╪¬╪¿ ┘å╪╡ ╪º┘ä╪▒╪» ╪ú┘ê ╪ú╪▒┘ü┘é ┘à┘ä┘ü╪º┘ï', 'warning');
          return;
        }
        if (!state.activeComplaintId) return;
        const sendBtn = document.getElementById('cpReplySendBtn');
        const prevHtml = sendBtn?.innerHTML;
        try {
          if (sendBtn) {
            sendBtn.dataset.submitting = '1';
            sendBtn.disabled = true;
            sendBtn.innerHTML = `<i class="fas fa-spinner fa-spin"></i> ╪¼╪º╪▒┘è ╪º┘ä╪Ñ╪▒╪│╪º┘äΓÇª`;
          }
          let attachments = await buildComplaintReplyAttachmentsPayload();
          if (attachments.length && c) {
            const moved = await moveComplaintAttachmentsToFinalFolder(
              c.id,
              c.complaint_number,
              attachments,
              { persistColumn: false }
            );
            if (moved) attachments = moved;
          }
          const { data, error } = await sb.rpc('add_complaint_reply', {
            p_complaint_id: state.activeComplaintId,
            p_text: text,
            p_attachments: attachments
          });
          if (error) throw error;
          if (!data?.ok) {
            showToast(data?.error || '╪¬╪╣╪░┘æ╪▒ ╪Ñ╪▒╪│╪º┘ä ╪º┘ä╪▒╪»', 'error');
            return;
          }
          const idx = (state.complaints || []).findIndex(c => c.id === data.complaint.id);
          if (idx >= 0) state.complaints[idx] = data.complaint;
          else state.complaints = [data.complaint, ...(state.complaints || [])];
          await clearComplaintReplyAttachFiles({ deleteRemote: false });
          renderComplaintDetailModal();
          paintComplaintsPage();
          showToast('╪¬┘à ╪Ñ╪▒╪│╪º┘ä ╪º┘ä╪▒╪»', 'success');
        } catch (e) {
          showToast('┘ü╪┤┘ä ╪Ñ╪▒╪│╪º┘ä ╪º┘ä╪▒╪»: ' + (e.message || e), 'error');
        } finally {
          if (sendBtn) {
            sendBtn.dataset.submitting = '0';
            sendBtn.disabled = false;
            sendBtn.innerHTML = prevHtml || '╪Ñ╪▒╪│╪º┘ä ╪º┘ä╪▒╪»';
            if (typeof syncAttachmentSubmitButtons === 'function') syncAttachmentSubmitButtons('cpr');
          }
        }
      }

      async function resolveComplaintFromUi(decision) {
        if (!state.activeComplaintId) return;
        if (!canManageComplaints()) {
          showToast('┘à╪»┘è╪▒ ╪º┘ä┘å╪╕╪º┘à ┘ü┘é╪╖ ┘è┘é╪»╪▒ ┘è╪║┘ä┘é ╪º┘ä╪┤┘â┘ê┘ë', 'warning');
          return;
        }
        try {
          const { data, error } = await resolveComplaintWithDecision(state.activeComplaintId, decision);
          if (error) throw error;
          if (!data?.ok) {
            showToast(data?.error || '╪¬╪╣╪░┘æ╪▒ ╪Ñ╪║┘ä╪º┘é ╪º┘ä╪┤┘â┘ê┘ë', 'error');
            return;
          }
          const idx = (state.complaints || []).findIndex(c => c.id === data.complaint.id);
          if (idx >= 0) state.complaints[idx] = data.complaint;
          renderComplaintDetailModal();
          paintComplaintsPage();
          showToast(complaintDecisionNote(decision), 'success');
        } catch (e) {
          showToast('┘ü╪┤┘ä ╪º┘ä╪Ñ╪║┘ä╪º┘é: ' + (e.message || e), 'error');
        }
      }

      function setupComplaintsRealtime() {
        if (state._complaintsChannel) {
          try { sb.removeChannel(state._complaintsChannel); } catch (_) { /* noop */ }
          state._complaintsChannel = null;
        }
        if (!canSubmitComplaint()) return;
        const ch = sb.channel('public:complaints')
          .on('postgres_changes', { event: '*', schema: 'public', table: 'complaints' }, (payload) => {
            const row = payload.new || payload.old;
            if (!row?.id) return;
            let list = [...(state.complaints || [])];
            if (payload.eventType === 'DELETE') {
              list = list.filter(c => c.id !== row.id);
            } else {
              const idx = list.findIndex(c => c.id === row.id);
              if (idx >= 0) list[idx] = payload.new;
              else list.unshift(payload.new);
            }
            state.complaints = list.sort((a, b) => new Date(b.created_at || 0) - new Date(a.created_at || 0));
            const tab = document.getElementById('tab-complaints');
            if (tab?.classList.contains('active')) {
              if (typeof isAtharDesktopScreenUi === 'function' && isAtharDesktopScreenUi()) {
                if (typeof renderComplaintsDesktop === 'function') renderComplaintsDesktop({ soft: true });
              } else if (typeof paintComplaintsPage === 'function') {
                paintComplaintsPage();
              }
            }
            if (state.activeComplaintId === row.id) renderComplaintDetailModal();
            if (state._rdCmplDetailId === row.id) renderComplaintsOverlays();
          })
          .subscribe();
        state._complaintsChannel = ch;
        state.realtimeChannels.push(ch);
      }

